                'group'      => (string) ($r['group'] ?? ''),
                'device'     => (string) ($r['device'] ?? ''),
                'key'        => (string) ($r['key'] ?? ''),
                'op'         => (string) ($r['op'] ?? '>='),
                /* an empty threshold is empty, as the second and third are:
                   made 0 here, "temperature >= 0" was saved and fired, where
                   the daemon would have asked for a number */
                'value'      => isset($r['value']) && $r['value'] !== '' && $r['value'] !== null ? (float) $r['value'] : null,
                'plug'       => (string) ($r['plug'] ?? ''),
                'do'         => (string) ($r['do'] ?? 'on'),
                'cooldown_s' => (int) ($r['cooldown_s'] ?? 300),
                'from'       => (string) ($r['from'] ?? ''),
                'to'         => (string) ($r['to'] ?? ''),
                'window_end' => (string) ($r['window_end'] ?? ''),
                'for_s'      => (int) ($r['for_s'] ?? 0),
                /* the wait before the action, not before the rule */
                'after_s'    => (int) ($r['after_s'] ?? 0),
                'back'       => isset($r['back']) && $r['back'] !== '' && $r['back'] !== null ? (float) $r['back'] : null,
                'device2'    => (string) ($r['device2'] ?? ''),
                'device3'    => (string) ($r['device3'] ?? ''),
                'key3'       => (string) ($r['key3'] ?? ''),
                'op3'        => (string) ($r['op3'] ?? '>='),
                'value3'     => $r['value3'] ?? null,
                'combine3'   => (string) ($r['combine3'] ?? 'and'),
                'key2'       => (string) ($r['key2'] ?? ''),
                'op2'        => (string) ($r['op2'] ?? '>='),
                'combine'    => (string) ($r['combine'] ?? 'and'),
                'mode'       => (string) ($r['mode'] ?? 'abs'),
                'when'       => (string) ($r['when'] ?? ''),
                'max_per_hour' => (int) ($r['max_per_hour'] ?? 0),
                'value2'     => isset($r['value2']) && $r['value2'] !== '' && $r['value2'] !== null ? (float) $r['value2'] : null,
                'enabled'    => !isset($r['enabled']) || !empty($r['enabled']),
            ];
            if ($row['do'] === 'pulse') {
                $row['pulse_ms'] = (int) ($r['pulse_ms'] ?? 5000);
            }
            $clean[] = $row;
        }
        $body = ['rules' => $clean];
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/rules', 'POST', $body, 20.0);
        exit;
    }
    if ($what === 'managed-save' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $body = ['plugs' => [], 'sensors' => []];
        foreach (['plugs', 'sensors'] as $kind) {
            foreach ((is_array($in) && isset($in[$kind]) && is_array($in[$kind])) ? $in[$kind] : [] as $e) {
                if (!is_array($e)) {
                    continue;
                }
                $row = [
                    'name'      => (string) ($e['name'] ?? ''),
                    'host'      => (string) ($e['host'] ?? ''),
                    'switch_id' => (int) ($e['switch_id'] ?? 0),
                    'mqtt_name' => (string) ($e['mqtt_name'] ?? ''),
                    'source'    => (string) ($e['source'] ?? 'ui'),
                    'role'      => (($e['role'] ?? '') === 'light') ? 'light' : 'plug',
                    'group'     => (string) ($e['group'] ?? ''),
                    'mqtt'      => !empty($e['mqtt']),
                    'mqtt_user' => (string) ($e['mqtt_user'] ?? ''),
                    'enabled'   => !isset($e['enabled']) || !empty($e['enabled']),
                'monitor_only' => !empty($e['monitor_only']),
                'host_state'   => (string) ($e['host_state'] ?? 'enabled'),
                'model'        => (string) ($e['model'] ?? ''),
                'mac'          => (string) ($e['mac'] ?? ''),
                ];
                if (isset($e['password']) && $e['password'] !== '') {
                    $row['password'] = (string) $e['password'];
                }
                if (isset($e['mqtt_password']) && $e['mqtt_password'] !== '') {
                    $row['mqtt_password'] = (string) $e['mqtt_password'];
                }
                if (!empty($e['clear_mqtt_password'])) {
                    $row['clear_mqtt_password'] = true;
                }
                if (!empty($e['clear_password'])) {
                    $row['clear_password'] = true;
                }
                $body[$kind][] = $row;
            }
        }
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/managed', 'POST', $body, 30.0);
        exit;
    }
    if ($what === 'managed-test' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $body = ['host' => (string) ($in['host'] ?? ''), 'password' => (string) ($in['password'] ?? '')];
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/managed/test', 'POST', $body, 20.0);
        exit;
    }
    if ($what === 'managed-discover' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $body = [];
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/managed/discover', 'POST', $body, 20.0);
        exit;
    }
    if ($what === 'plug-switch' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $body = ['name' => (string) ($in['name'] ?? '')];
        if (!empty($in['pulse'])) {
            $body['pulse'] = true;
            $body['ms'] = max(100, min(3600000, (int) ($in['ms'] ?? 5000)));
        } elseif (!empty($in['toggle'])) {
            $body['toggle'] = true;
        } else {
            $body['on'] = !empty($in['on']);
        }
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/plug/switch', 'POST', $body, 30.0 + (!empty($body['pulse']) ? $body['ms'] / 1000.0 : 0));
        exit;
    }
    if ($what === 'plug-reset' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $body = ['name' => (string) ($in['name'] ?? '')];
        $allowed = ['aenergy', 'ret_aenergy', 'on_time', 'switch_on', 'on_above_thr'];
        $body['types'] = (is_array($in) && isset($in['types']) && is_array($in['types']))
            ? array_values(array_intersect($in['types'], $allowed)) : [];
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/plug/reset', 'POST', $body, 60.0);
        exit;
    }
    if ($what === 'bindings-save' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $clean = [];
        foreach ((is_array($in) && isset($in['bindings']) && is_array($in['bindings'])) ? $in['bindings'] : [] as $b) {
            if (!is_array($b)) {
                continue;
            }
            $row = [
                'group'   => (string) ($b['group'] ?? ''),
                'device'  => (string) ($b['device'] ?? ''),
                'action'  => (string) ($b['action'] ?? ''),
                'plug'    => (string) ($b['plug'] ?? ''),
                'do'      => (string) ($b['do'] ?? 'toggle'),
                'hold'    => !empty($b['hold']),
                'enabled' => !isset($b['enabled']) || !empty($b['enabled']),
            ];
            if ($row['do'] === 'pulse') {
                $row['pulse_ms'] = (int) ($b['pulse_ms'] ?? 5000);
            }
            $clean[] = $row;
        }
        $body = ['bindings' => $clean];
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/bindings', 'POST', $body, 20.0);
        exit;
    }
    // ---- signing in (5.19) -------------------------------------------------
    // The token the daemon hands out goes into a cookie the page's script
    // cannot read, and is taken out of the answer: the browser carries it
    // from here on, and nothing in the page holds it.
    // A PIN (5.19.1) goes the same way: ?api=unlock, as it always did, or a
    // sign-in that carries a PIN and how long to unlock for.
    if (($what === 'login' || $what === 'unlock') && $_SERVER['REQUEST_METHOD'] === 'POST') {
        header('Content-Type: application/json; charset=utf-8');
        header('Cache-Control: no-store');
        $in = json_decode((string) file_get_contents('php://input'), true);
        $in = is_array($in) ? $in : [];
        $old = zigmon_session();
        $send = isset($in['pin']) && !isset($in['name'])
            ? ['pin' => substr((string) $in['pin'], 0, 32),
               'minutes' => max(1, min(720, (int) ($in['minutes'] ?? 15)))]
            : ['name' => substr((string) ($in['name'] ?? ''), 0, 64),
               'password' => substr((string) ($in['password'] ?? ''), 0, 200)];
        [$status, $reply] = zigmon_call($what === 'unlock' ? '/api/unlock' : '/api/auth/login', 'POST', $send, 30.0);
        if ($status === 0) {
            http_response_code(503);
            echo json_encode(['ok' => false, 'error' => 'the monitoring daemon is not responding — is zigmon.service running?']);
            exit;
        }
        $data = json_decode($reply, true);
        if ($status === 200 && is_array($data) && !empty($data['token'])) {
            // another account signing in on this page: the one before ends
            if ($old !== '') {
                zigmon_call('/api/auth/logout', 'POST', [], 10.0);
            }
            zigmon_set_session((string) $data['token'], time() + 400 * 86400);
            unset($data['token']);
            echo json_encode($data);
            exit;
        }
        http_response_code($status === 200 ? 400 : $status);
        echo json_encode(is_array($data) ? $data : ['ok' => false, 'error' => 'sign-in failed']);
        exit;
    }
    if (($what === 'logout' || $what === 'lock') && $_SERVER['REQUEST_METHOD'] === 'POST') {
        header('Content-Type: application/json; charset=utf-8');
        header('Cache-Control: no-store');
        if (zigmon_session() !== '') {
            zigmon_call('/api/auth/logout', 'POST', [], 10.0);
        }
        zigmon_set_session('', 0);
        echo json_encode(['ok' => true]);
        exit;
    }
    if ($what === 'whoami') {
        zigmon_relay('/api/auth/whoami', 'GET', null, 10.0);
        exit;
    }
    if ($what === 'password' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        zigmon_relay('/api/auth/password', 'POST', ['old' => (string) ($in['old'] ?? ''),
                                                    'new' => (string) ($in['new'] ?? '')], 30.0);
        exit;
    }
    if ($what === 'accounts') {
        zigmon_relay('/api/accounts', 'GET', null, 10.0);
        exit;
    }
    if ($what === 'accounts-do' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $body = [];
        foreach (['action', 'name', 'role', 'password', 'note', 'kind', 'pin'] as $k) {
            if (isset($in[$k])) {
                $body[$k] = (string) $in[$k];
            }
        }
        if (isset($in['must_change'])) {
            $body['must_change'] = !empty($in['must_change']);
        }
        zigmon_relay('/api/accounts', 'POST', $body, 30.0);
        exit;
    }
    if ($what === 'permit-join' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $body = ['enable' => !empty($in['enable']), 'time' => 254];
        if (is_array($in) && isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (is_array($in) && isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/permit-join', 'POST', $body, 15.0);
        exit;
    }
    if ($what === 'reset' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $in = json_decode((string) file_get_contents('php://input'), true);
        $scope = (string) ($in['scope'] ?? '');
        if (!in_array($scope, ['all', 'history', 'events', 'device'], true)) {
            http_response_code(400);
            header('Content-Type: application/json');
            echo json_encode(['ok' => false, 'error' => 'bad scope']);
            exit;
        }
        $body = ['scope' => $scope];
        if (isset($in['device'])) {
            $body['device'] = (string) $in['device'];
        }
        if (isset($in['pin'])) {
            $body['pin'] = (string) $in['pin'];
        }
        if (isset($in['session'])) {
            $body['session'] = (string) $in['session'];
        }
        zigmon_relay('/api/reset', 'POST', $body, 120.0);
        exit;
    }
    http_response_code(404);
    header('Content-Type: application/json');
    echo json_encode(['ok' => false, 'error' => 'unknown endpoint']);
    exit;
}

// ---- The page ------------------------------------------------------------
$whoami  = zigmon_get('/api/auth/whoami', 5.0);
$who     = is_array($whoami) && is_array($whoami['who'] ?? null) ? $whoami['who'] : null;
$host    = (string) ($_SERVER['HTTP_HOST'] ?? php_uname('n'));

function h($value): string
{
    return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

