<script>
(function () {
  var form = document.getElementById('signin-form'), said = document.getElementById('in-said'),
      go = document.getElementById('in-go'), pass = document.getElementById('in-pass');
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    said.className = 'said'; said.textContent = '';
    go.disabled = true; go.querySelector('span').textContent = 'Signing in\u2026';
    fetch('?api=login', {method: 'POST', credentials: 'same-origin', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({name: document.getElementById('in-name').value, password: pass.value})})
      .then(function (r) { return r.json().then(function (d) { if (!r.ok) throw new Error(d.error || ('HTTP ' + r.status)); return d; }); })
      .then(function () { said.className = 'said good'; said.textContent = 'Welcome back.'; location.reload(); })
      .catch(function (err) {
        said.className = 'said bad'; said.textContent = String(err.message || err);
        go.disabled = false; go.querySelector('span').textContent = 'Sign in';
        pass.value = ''; pass.focus();
      });
  });
  var pinForm = document.getElementById('pin-form'), pin = document.getElementById('in-pin'),
      pinSaid = document.getElementById('pin-said'), pinGo = document.getElementById('pin-go'),
      other = document.getElementById('in-other');
  function shown() { (pinForm.hidden ? document.getElementById('in-name') : pin).focus(); }
  if (other) other.addEventListener('click', function (e) {
    e.preventDefault();
    pinForm.hidden = !pinForm.hidden; form.hidden = !pinForm.hidden;
    other.textContent = pinForm.hidden ? 'Use a PIN instead' : 'Sign in with a name and a password instead';
    shown();
  });
  pinForm.addEventListener('submit', function (e) {
    e.preventDefault();
    pinSaid.className = 'said'; pinSaid.textContent = '';
    pinGo.disabled = true; pinGo.querySelector('span').textContent = 'Unlocking\u2026';
    fetch('?api=unlock', {method: 'POST', credentials: 'same-origin', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({pin: pin.value, minutes: parseInt(document.getElementById('in-minutes').value, 10) || 240})})
      .then(function (r) { return r.json().then(function (d) { if (!r.ok) throw new Error(d.error || ('HTTP ' + r.status)); return d; }); })
      .then(function () { location.reload(); })
      .catch(function (err) {
        pinSaid.className = 'said bad'; pinSaid.textContent = String(err.message || err);
        pinGo.disabled = false; pinGo.querySelector('span').textContent = 'Unlock';
        pin.value = ''; pin.focus();
      });
  });
  var maxlen = parseInt(pin.getAttribute('maxlength') || '0', 10);
  if (maxlen) pin.addEventListener('input', function () {
    pin.value = pin.value.replace(/\D/g, '');
    if (pin.value.length === maxlen) pinForm.requestSubmit ? pinForm.requestSubmit() : pinGo.click();
  });
  shown();
}());
</script>
