    .set-grid{grid-template-columns:1fr}
    .socket-figures{grid-auto-flow:row;grid-template-columns:repeat(auto-fill,100px);justify-content:start}
  }
  .evf{font:inherit;font-size:13px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:9px;padding:7px 10px}
  select.evf{padding-right:26px}
  .set-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px 22px;margin-top:6px;align-items:stretch}
  /* A list of addresses: one per line, in a box that grows with what is in
     it. Past the third entry a one-line box is a letterbox, and a house has a
     phone, a laptop, a work subnet and a friend's address in there before
     long. Monospaced, because that is what makes a typo in a /24 visible. */
  .addrlist textarea{width:100%;font-family:var(--mono,monospace);font-size:12.5px;
    line-height:1.55;padding:7px 9px;border-radius:8px;border:1px solid var(--line);
    background:var(--bg-in,var(--bg));color:var(--tx);resize:vertical;min-height:72px}
  .addrlist textarea:focus{outline:none;border-color:var(--accent)}
  .addrcount{margin-top:3px}
  .set-item.set-bool{flex-direction:row;align-items:center;justify-content:space-between;
                     flex-wrap:wrap}
  /* a cluster: its own grid across the whole width, so what is in it wraps
     only among itself and the next one starts on a fresh line */
  .set-cluster{grid-column:1/-1;display:grid;
               grid-template-columns:repeat(auto-fill,minmax(260px,1fr));
               gap:14px 22px;align-items:stretch;margin-top:2px}
  .set-sub{grid-column:1/-1;font-size:11px;letter-spacing:.1em;text-transform:uppercase;
           color:var(--tx-mut);margin:6px 0 -4px}
  .set-item{display:flex;flex-direction:column;gap:5px;justify-content:flex-end}
  /* Three bands down the whole row - label, control, note - so a two-line
     label does not push its own box below its neighbours'. Where subgrid is
     not to be had, the flex column above still reads correctly. */
  /* Only the SMS card's items have the three parts; elsewhere an item is a
     label over a box and the flex column above is the right shape. The bands
     are explicit about their one column and what fills it, or an <input>
     inside a grid keeps its own width and drifts. */
  @supports (grid-template-rows: subgrid) {
    /* Every settings item is three bands down the row - label, control, note -
       so a two-line label or a note about being taken over moves nothing but
       itself. Without this the item was a flex column and anything added to
       it pushed the box up, leaving the boxes in one row at four different
       heights. */
    :is(#settings-grid, .set-host) .set-grid{grid-auto-rows:auto}
    :is(#settings-grid, .set-host) .set-grid > .set-item{display:grid;grid-template-rows:subgrid;grid-row:span 3;
      grid-template-columns:minmax(0,1fr);justify-items:stretch;gap:5px;align-content:start}
    /* Each part named, rather than left to the order it was added in: the
       label takes the first band, whatever the control is takes the second,
       the note takes the third. An item with no label, or one where the note
       came before something else, used to slide a band. */
    :is(#settings-grid, .set-host) .set-grid > .set-item > label{grid-row:1;align-self:end}
    :is(#settings-grid, .set-host) .set-grid > .set-item > input,
    :is(#settings-grid, .set-host) .set-grid > .set-item > select,
    :is(#settings-grid, .set-host) .set-grid > .set-item > .ladder,
    :is(#settings-grid, .set-host) .set-grid > .set-item > .sw{grid-row:2}
    :is(#settings-grid, .set-host) .set-grid > .set-item > .idle-note{grid-row:3}
    :is(#settings-grid, .set-host) .set-grid > .set-item > input,
    :is(#settings-grid, .set-host) .set-grid > .set-item > select,
    :is(#settings-grid, .set-host) .set-grid > .set-item > .ladder{width:100%;box-sizing:border-box;
      justify-self:stretch;align-self:start}
    /* A switch sits in the second band with the boxes beside it, not up at
       the label line: its label goes beside it rather than above it, which is
       what the row-shaped item was for. */
    :is(#settings-grid, .set-host) .set-grid > .set-item.set-bool{grid-template-columns:minmax(0,1fr) auto}
    :is(#settings-grid, .set-host) .set-grid > .set-item.set-bool > label{grid-row:2;grid-column:1;
      justify-self:start;align-self:center}
    :is(#settings-grid, .set-host) .set-grid > .set-item.set-bool > .sw{grid-row:2;grid-column:2;
      justify-self:end;align-self:center}
    :is(#settings-grid, .set-host) .set-grid > .set-item.set-bool > .idle-note{grid-row:3;grid-column:1/-1}
    /* A heading is a row of its own, one band tall, and has to say so - the
       items around it are three bands each, and an item may not begin in the
       middle of a heading's row. */
    :is(#settings-grid, .set-host) .set-grid > .set-head{grid-column:1/-1;grid-row:span 1}
    /* the bands are per cluster now, since that is the grid the items are in */
    :is(#settings-grid, .set-host) .set-cluster{grid-auto-rows:auto}
    :is(#settings-grid, .set-host) .set-cluster > .set-item{display:grid;grid-template-rows:subgrid;
      grid-row:span 3;grid-template-columns:minmax(0,1fr);gap:5px;align-content:start}
    :is(#settings-grid, .set-host) .set-cluster > .set-item > label{grid-row:1;align-self:end}
    :is(#settings-grid, .set-host) .set-cluster > .set-item > input,
    :is(#settings-grid, .set-host) .set-cluster > .set-item > select,
    :is(#settings-grid, .set-host) .set-cluster > .set-item > .ladder,
    :is(#settings-grid, .set-host) .set-cluster > .set-item > .sw{grid-row:2}
    :is(#settings-grid, .set-host) .set-cluster > .set-item > .idle-note{grid-row:3}
    :is(#settings-grid, .set-host) .set-cluster > .set-item > input,
    :is(#settings-grid, .set-host) .set-cluster > .set-item > select,
    :is(#settings-grid, .set-host) .set-cluster > .set-item > .ladder{width:100%;box-sizing:border-box;
      justify-self:stretch;align-self:start}
    :is(#settings-grid, .set-host) .set-cluster > .set-item.set-bool{grid-template-columns:minmax(0,1fr) auto}
    :is(#settings-grid, .set-host) .set-cluster > .set-item.set-bool > label{grid-row:2;grid-column:1;
      justify-self:start;align-self:center}
    :is(#settings-grid, .set-host) .set-cluster > .set-item.set-bool > .sw{grid-row:2;grid-column:2;
      justify-self:end;align-self:center}
    :is(#settings-grid, .set-host) .set-cluster > .set-item.set-bool > .idle-note{grid-row:3;grid-column:1/-1}
    :is(#settings-grid, .set-host) .set-cluster > .set-item.set-tall{grid-column:1/-1;grid-row:auto;
      display:flex;flex-direction:column;gap:5px;max-width:420px}
    :is(#settings-grid, .set-host) .set-cluster > .set-sub{grid-row:span 1}
    /* A tall thing - the ladder is a dozen rows - takes a line of its own.
       Sharing a row with short boxes stretched their bands to its height and
       left their notes stranded at the bottom, half a screen under the box
       they were about. */
    :is(#settings-grid, .set-host) .set-grid > .set-item.set-tall{grid-column:1/-1;grid-row:auto;
      display:flex;flex-direction:column;gap:5px;max-width:420px}
    #sms-grid .section-body .set-grid{grid-auto-rows:auto}
    #sms-grid .section-body .set-grid > .set-item{display:grid;grid-template-rows:subgrid;grid-row:span 3;
      grid-template-columns:minmax(0,1fr);justify-items:stretch;gap:5px;align-content:start}
    #sms-grid .section-body .set-grid > .set-item > input,
    #sms-grid .section-body .set-grid > .set-item > select{width:100%;box-sizing:border-box;justify-self:stretch;
      /* wide, never tall: a row is as high as the tallest control in it, and
         a grid item fills its row unless told not to. Three switches beside a
         dropdown made the dropdown as tall as they were. */
      align-self:start}
  }
  /* The whole label, however long. Each item is a column with the input at
     the bottom, and grid rows stretch to the tallest item, so a label that
     wraps onto three lines leaves its neighbours' inputs level with its own. */
  .set-item label{font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--tx-mut);
    line-height:1.35;white-space:normal;overflow-wrap:anywhere}
  .set-item input{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:9px;padding:8px 11px;
    width:100%;box-sizing:border-box;text-align:left}
  .set-item label{text-align:left}
  .set-item select{width:100%;box-sizing:border-box}
  .set-item input:focus{border-color:var(--info);outline:none}
  /* a certificate in a setting (5.33): the same box as every other input,
     not the browser's grey one */
  .set-item textarea{font:12.5px/1.45 var(--mono,ui-monospace,monospace);background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:9px 11px;width:100%;box-sizing:border-box;resize:vertical;
    min-height:96px;text-align:left}
  .set-item textarea::placeholder{color:var(--tx-dim)}
  .set-item textarea:focus{border-color:var(--info);outline:none;box-shadow:0 0 0 3px rgba(88,166,255,.18)}
  .set-item textarea:disabled{opacity:.55}
  /* "this one differs from what the file says" - a mark down the left edge and
     a dot beside the label, rather than a blue frame, which read as though the
     box were focused or under the pointer */
  .set-item.overridden > input,.set-item.overridden > select{border-left:3px solid var(--info)}
  .set-item.overridden > label::after{content:'\2022';color:var(--info);margin-left:6px;font-size:15px;line-height:0}
  /* One switch and four fields: the auto-filling grid above would strand the
     last one on a row by itself. This group gets a row of its own with a
     deliberate four across, so a hidden field leaves a gap at the end instead
     of shunting the rest about. */
  .set-sub{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 22px}
  .set-sub > *{min-width:0}
  .set-wide{grid-column:1/-1;max-width:340px}
  @media (max-width:1100px){.set-sub{grid-template-columns:repeat(2,minmax(0,1fr))}}
  @media (max-width:640px){.set-sub{grid-template-columns:1fr}}
  .set-head{grid-column:1/-1;font-size:11.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--tx-dim);margin-top:8px}
  .set-head .dim{color:var(--tx-mut)}
  .notify-grid .pc-block .pc-body{padding-left:21px}
  .nsec{margin:20px 0 4px;font-size:11px;letter-spacing:.09em;text-transform:uppercase;
    color:var(--tx-mut);border-top:1px solid var(--line);padding-top:12px}
  .nsec:first-of-type{border-top:0;margin-top:12px}
  .notify-dev{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
  .notify-devhead{display:flex;flex-direction:column;gap:1px;min-width:200px}
  .notify-devname{font-weight:620;color:var(--tx)}
  .notify-grid{display:block}
  .notify-dev{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:5px 0;font-size:13.5px;color:var(--tx-dim)}
  .notify-dev select{font:inherit;font-size:12.5px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:9px;padding:6px 26px 6px 10px;max-width:210px}
  .notify-dev.overridden select{border-color:var(--info)}
  .notify-dev{flex-wrap:wrap}
  /* one switch per road, for a kind of message that wants its own. While it
     follows the house the switches still show where it goes, dimmed, because
     "follows the house" is not an answer to "so where does it go". */
  .notify-sys{display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:2px 0 2px 2px;
    border-left:2px solid transparent;padding-left:10px}
  /* the same three switches in a settings column, which is narrow: closer
     together, and the whole width of the card rather than one column of it,
     so they stand on one line instead of three */
  .set-grid > .set-item > .roads-field{gap:14px;padding-left:0;border-left:0;align-self:start}
  .set-item.wide{grid-column:1/-1}
  .notify-sys.overridden{border-left-color:var(--info)}
  .notify-sys .swrow.dim{opacity:.45}
  .notify-sys .swrow .swlbl{font-size:12.5px}
  .notify-sys-says{white-space:nowrap}
  .notify-custom .swrow{margin-right:10px}
  .notify-custom{display:inline-flex;gap:10px;flex-wrap:wrap;width:100%;padding:6px 0 2px 2px;font-size:12.5px}
  .notify-custom label{display:inline-flex;gap:5px;align-items:center;cursor:pointer}
  .notify-custom input{accent-color:var(--info)}
  .notify-dev.overridden span:first-child{color:var(--tx)}
  .rule-sub{display:flex;flex-direction:column;gap:7px;padding:4px 0 12px 4px;margin-top:-2px;
    border-bottom:1px solid rgba(38,44,55,.5);font-size:13px;color:var(--tx-dim)}
  .rule-sub-line{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
  .rule-sub .sublbl{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--tx-mut);margin-left:2px}
  .rule-sub .wend{display:inline-flex;gap:6px;align-items:center}
  .rule-sub input,.rule-sub select{font:inherit;font-size:13px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:7px 10px;height:34px;box-sizing:border-box}
  .rule-sub select{padding-right:26px}
  .rule-sub input[type=time]{width:104px}
  .rule-sub .wnum{width:86px}
  .rule-sub .woff{width:72px}
  .rule-sub input:focus,.rule-sub select:focus{border-color:var(--info);outline:none}
  .rule-row{border-bottom:none}
  @media (max-width:900px){.rule-row{grid-template-columns:1fr 1fr 1fr}}
  .bind-row.off>*:not(.sw):not(button),.rule-row.off>*:not(.sw):not(button),.sched-row.off>*:not(.sw):not(button){opacity:.5}
  /* ...and a rule switched off is dimmed whole - the second condition, the
     window, the cooldown: all of it is the one rule */
  .rule-pack.off .rule-sub{opacity:.5}
  .bind-head{color:var(--tx-mut);font-size:11px;letter-spacing:.7px;text-transform:uppercase;font-weight:700;border-bottom:1px solid var(--line)}
  @media (max-width:700px){.bind-row{grid-template-columns:1fr 1fr;} .bind-head{display:none}}

  .actchips{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px}
  .actchips .chip{font-size:10.5px;letter-spacing:.3px;padding:2.5px 9px;border-radius:999px;
    background:var(--panel2);border:1px solid var(--line);color:var(--tx-mut);white-space:nowrap}
  .actchips .chip.more{border-style:dashed;cursor:help}
  .actchips .chip.groups{color:var(--info);border-color:rgba(88,166,255,.3);background:rgba(88,166,255,.07)}
  .lastact .v{transition:color .3s}
  .reading.fresh .v{color:var(--ok);animation:pressed 1.6s ease-out}
  .reading.fresh .l{color:var(--ok)}
  @keyframes pressed{0%{text-shadow:0 0 18px rgba(63,185,80,.85);transform:scale(1.06)}
    60%{text-shadow:0 0 8px rgba(63,185,80,.35)}100%{text-shadow:none;transform:none}}
  .muted{color:var(--tx-dim)} .small{font-size:13px} .center{text-align:center;color:var(--tx-mut);padding:26px 0}
  .note{color:var(--tx-dim);font-size:13px;margin:0 0 12px}
  code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;background:var(--panel2);
       padding:1px 6px;border-radius:6px}

  .toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(20px);opacity:0;
         background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:11px 18px;
         font-size:14px;font-weight:600;transition:opacity .2s,transform .2s;z-index:120;pointer-events:none;
         box-shadow:0 8px 30px rgba(0,0,0,.4)}
  .toast.show{opacity:1;transform:translateX(-50%) translateY(0)}
  .toast.ok{border-color:rgba(63,185,80,.4);color:var(--ok)} .toast.bad{border-color:rgba(248,81,73,.4);color:var(--crit)}

  /* ---- PIN dialog, as in upsmon ---- */
  .backdrop{position:fixed;inset:0;z-index:100;display:flex;align-items:center;
    justify-content:center;background:rgba(2,5,10,.72);backdrop-filter:blur(3px);
    padding:20px;animation:fade .16s ease}
  .backdrop[hidden]{display:none}
  @keyframes fade{from{opacity:0}to{opacity:1}}
  .sw{position:relative;display:inline-block;width:44px;height:26px;flex:0 0 auto;vertical-align:middle}
  .sw input{position:absolute;opacity:0;width:0;height:0}
  .sw .knob{position:absolute;inset:0;border-radius:999px;background:#3a4354;border:1px solid var(--line);cursor:pointer;transition:background .18s,border-color .18s}
  .sw .knob::after{content:'';position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:#fff;
    box-shadow:0 1px 3px rgba(0,0,0,.45);transition:transform .18s cubic-bezier(.2,.9,.3,1)}
  .sw input:checked+.knob{background:var(--ok);border-color:var(--ok)}
  .sw input:checked+.knob::after{transform:translateX(18px)}
  .sw input:focus-visible+.knob{box-shadow:0 0 0 3px rgba(88,166,255,.35)}
  .sw input:disabled+.knob{opacity:.45;cursor:not-allowed}
  .sw.small{width:36px;height:22px} .sw.small .knob::after{width:16px;height:16px} .sw.small input:checked+.knob::after{transform:translateX(14px)}
  .swrow{display:inline-flex;align-items:center;gap:10px}
  .swrow .swlbl{font-size:13.5px}
  #db-run, #rec-run{margin-top:12px;border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:var(--panel2)}
  .runbar{height:4px;border-radius:3px;background:rgba(88,166,255,.15);overflow:hidden;margin-bottom:8px}
  .runbar i{display:block;height:100%;width:38%;border-radius:3px;background:var(--info);animation:runslide 1.1s ease-in-out infinite}
  #db-run.done .runbar i, #rec-run.done .runbar i{width:100%;animation:none;background:var(--ok)}
  #db-run.failed .runbar i, #rec-run.failed .runbar i{width:100%;animation:none;background:var(--crit)}
  @keyframes runslide{0%{margin-left:-40%}100%{margin-left:100%}}
  .runhead{display:flex;justify-content:space-between;align-items:baseline;gap:10px;font-size:13.5px;font-weight:600}
  .runlog{margin:8px 0 0;max-height:190px;overflow:auto;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;
    color:var(--tx-dim);white-space:pre-wrap;word-break:break-word}
  .runlog:empty{display:none}
  #reset-device option.gone{color:var(--warn)}
  .set-item[hidden]{display:none}
  /* ...and in the grids, whose subgrid rule (an id inside :is) outweighed
     the line above: a box that belongs to a choice not made stayed on the
     card (5.30 - ACME's DNS boxes; Duo's were the same) */
  :is(#settings-grid, .set-host) .set-item[hidden],
  :is(#settings-grid, .set-host) .set-cluster[hidden]{display:none}
  /* ...and a tall one, whose own rule outweighed both (5.34.1): the CA's
     certificate stayed on the card with ACME switched off */
  :is(#settings-grid, .set-host) :is(.set-grid, .set-cluster) > .set-item.set-tall[hidden]{display:none}
  /* a certificate in PEM (5.34.1): a box its 64-character lines fit across,
     and tall enough for a whole one */
  :is(#settings-grid, .set-host) :is(.set-grid, .set-cluster) > .set-item.set-tall.set-pem{max-width:none}
  .set-item.set-pem textarea{width:min(100%, 74ch);min-height:22em;font-size:12.5px;line-height:1.45;
    white-space:pre;overflow-wrap:normal;overflow-x:auto}
  .subpanel{margin-top:12px;padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--panel2)}
  .subpanel > .note:first-child{margin-top:0}
  .subpanel .btnrow{flex-wrap:wrap}
  .subpanel .spacer{flex:1 1 auto}
  .sw-cell{display:flex;align-items:center;gap:8px}
  .sw-cap{font-size:11px;color:var(--tx-mut);line-height:1.25}
  #alertband{position:sticky;top:0;z-index:60;display:none;align-items:center;gap:12px;flex-wrap:wrap;
    padding:11px 18px;background:color-mix(in srgb, var(--crit) 22%, var(--panel));
    border-bottom:1px solid var(--crit);box-shadow:0 6px 18px rgba(0,0,0,.28)}
  #alertband.show{display:flex}
  /* what waits to be kept (5.21): a new network, a change of the firewall */
  .changes{position:sticky;top:0;z-index:59;display:flex;flex-direction:column;gap:8px;padding:10px 18px;
    background:color-mix(in srgb, var(--warn) 18%, var(--panel));border-bottom:1px solid var(--warn)}
  .changes[hidden]{display:none}
  .change{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap}
  .change-words{flex:1 1 360px;min-width:0}
  .change-left{color:var(--warn);font-weight:600}
  .change-tools{display:flex;gap:8px;flex-wrap:wrap}
  .net-steps{margin:8px 0 4px;padding-left:22px}
  .net-steps li{margin:3px 0}
  .net-steps li .mark{display:inline-block;width:1.2em;font-weight:700}
  .net-steps li.good .mark{color:var(--ok)}
  .net-steps li.bad .mark{color:var(--crit)}
  .net-steps li .what{margin-right:8px}
  .net-plan h4{margin:12px 0 4px}
  .away-box h3{margin:0 0 8px}
  .ntp-server{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:6px 0}
  .ntp-server input[type=text]{flex:1 1 220px;min-width:0}
  .ntp-server .tick{display:inline-flex;align-items:center;gap:4px;font-size:13px}
  .sw-h{margin:16px 0 6px;font-size:14px}
  .sw-table td.k{color:var(--tx-mut);padding-right:18px;white-space:nowrap}
  .sw-table tr.sw-group td{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--tx-mut);padding-top:10px}
  .sw-ext{display:flex;flex-wrap:wrap;gap:4px;margin-top:4px}
  #alertband .bell{color:var(--crit);flex:0 0 auto;display:flex}
  #alertband .texts{flex:1 1 260px;min-width:0;display:flex;flex-direction:column;gap:2px}
  #alertband .one{font-size:13.5px;font-weight:600;white-space:normal;overflow-wrap:anywhere;line-height:1.35;
    display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
  #alertband .one .when{font-weight:400;color:var(--tx-mut);margin-left:8px;font-size:12px}
  #alertband .more{font-size:12px;color:var(--tx-mut)}
  #alertband .acts{flex:0 0 auto;opacity:0;transition:opacity .15s}
  #alertband:hover .acts, #alertband:focus-within .acts{opacity:1}
  @media (hover:none){#alertband .acts{opacity:1}}
  .socket-hold{margin-top:4px}
  .holdchip{display:inline-flex;align-items:center;gap:5px;padding:2px 9px;border-radius:999px;cursor:pointer;
    background:color-mix(in srgb, var(--warn) 18%, var(--panel2));border:1px solid var(--warn);
    color:var(--warn);font:inherit;font-size:11.5px;font-weight:600}
  .holdchip:hover{background:color-mix(in srgb, var(--warn) 30%, var(--panel2))}
  .who-row{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 2px}
  .whochip{display:inline-flex;align-items:center;gap:6px;padding:2px 9px;border-radius:999px;
    background:var(--panel2);border:1px solid var(--line);font-size:12.5px;color:var(--tx-mut)}
  .whochip.in{color:var(--tx);border-color:color-mix(in srgb, var(--ok) 45%, var(--line))}
  .whochip .dot{width:7px;height:7px;border-radius:50%;background:var(--tx-mut)}
  .whochip.in .dot{background:var(--ok)}
  /* A card is the size of its kind, not of the words that happen to be in it:
     every network tile matches every other, so the wall does not stagger. */
  /* A card is as tall as its kind, not as tall as whatever it happens to sit
     beside: a grid row stretches every card in it to match the tallest, which
     is why one network card next to an access point came out oversized. */
  #wifi-tiles{align-items:start}
  .wifi-tile{display:flex;flex-direction:column;min-width:0;overflow:hidden}
  /* a flex child will not shrink below its content unless told, and a long
     model line pushed the chart button out past the frame */
  .wifi-tile .head{min-width:0}
  .wifi-tile .head > div:first-child{min-width:0;flex:1 1 auto}
  /* nothing is cut short and nothing breaks mid-word: the text wraps where
     words allow, and the cards in a group are levelled to the tallest */
  .wifi-tile .name{overflow-wrap:break-word}
  .wifi-tile .muted, .wifi-tile .reason{overflow-wrap:break-word}
  .wifi-tile .readings{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));
    gap:10px 12px;align-content:start;margin-top:8px}
  .wifi-tile .reading{min-width:0}
  /* an uplink reads "down 7.7 Kbps up 29.4 Kbps"; cutting that at the frame
     tells the reader nothing, so it wraps instead */
  .wifi-tile .reading .v{overflow-wrap:break-word;line-height:1.25}
  .wifi-tile .reading .v .unit{white-space:nowrap}
  /* each direction of the uplink stays whole; the line breaks between them */
  .wifi-tile .reading .v .nowrap{white-space:nowrap;display:inline-block;margin-right:8px}
  .wifi-tile .reading .l{overflow-wrap:break-word;line-height:1.25}
  .wifi-tile .reading .sub{font-size:10.5px;color:var(--tx-mut);line-height:1.3;margin-top:1px}
  .wifi-tile .reading .sub.hint{color:var(--ok)}
  .wifi-tile .model{overflow-wrap:break-word;line-height:1.35}
  .wifi-tile .foot{margin-top:auto;padding-top:8px}
  /* A grid row is as tall as the tallest card in it, so an access point beside
     a network stretched the network to match and the next row did not. Each
     kind is laid out in a grid of its own, where every row is the same. */
  #wifi-tiles{display:block}
  /* every row in a group is as tall as that group's tallest card, so the cards
     match without any of them having to cut its text short */
  .wifi-group .grid{grid-auto-rows:1fr}
  .wifi-group .wifi-tile{height:100%}
  .wifi-group{margin-bottom:16px}
  .wifi-group > h3{margin:2px 0 8px;font-size:11.5px;letter-spacing:.13em;text-transform:uppercase;
    color:var(--tx-dim);font-weight:600}
  .wifi-tile.tile-controller{min-height:170px}
  .wifi-tile.tile-ap{min-height:210px}
  .wifi-tile.tile-ssid{min-height:130px}
  #wifi-clients{margin:12px 0;max-height:300px;overflow:auto;border:1px solid var(--line);border-radius:12px}
  #wifi-clients:empty{display:none}
  .wc-row{display:grid;grid-template-columns:minmax(120px,1.4fr) minmax(140px,1fr) minmax(100px,.8fr) minmax(90px,.7fr) minmax(150px,1fr);
    gap:8px;align-items:center;padding:5px 6px;border-radius:8px;font-size:13px}
  .wc-row:nth-child(odd){background:var(--panel2)}
  .wc-row:not(.head):hover{background:rgba(88,166,255,.07);box-shadow:inset 3px 0 0 var(--info)}
  .wc-row.head{color:var(--tx-mut);font-size:11px;text-transform:uppercase;letter-spacing:.05em;background:none}
  .wc-row .mac{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;color:var(--tx-dim)}
  .wc-row.taken{color:var(--ok)}
  .wc-row.wide{grid-template-columns:minmax(140px,1.5fr) minmax(92px,.9fr) minmax(90px,.9fr)
    minmax(88px,.9fr) minmax(92px,.9fr) minmax(84px,.85fr) minmax(104px,1fr) minmax(66px,.65fr) minmax(72px,.7fr)}
  .wc-row.wide > *{min-width:0}
  #wifi-seen .oth-row{grid-template-columns:1.6fr 1.4fr .6fr .6fr .7fr .5fr .8fr .8fr}
  .oth-row{display:grid;grid-template-columns:minmax(140px,1.6fr) minmax(140px,1.2fr) minmax(64px,.6fr)
    minmax(90px,.8fr) minmax(70px,.6fr) minmax(84px,.7fr) minmax(120px,1.1fr) minmax(80px,.8fr);
    gap:8px;align-items:center;padding:5px 6px;border-radius:8px;font-size:13px}
  .oth-row > *{min-width:0}
  .oth-row:nth-child(odd){background:var(--panel2)}
  .oth-row:not(.head):hover{background:rgba(88,166,255,.07);box-shadow:inset 3px 0 0 var(--info)}
  .oth-row.head{color:var(--tx-mut);font-size:11px;text-transform:uppercase;letter-spacing:.05em;background:none}
  .oth-row .mac{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11.5px;color:var(--tx-dim)}
  .chip-clash{margin-left:6px;padding:1px 6px;border-radius:999px;font-size:10px;text-transform:uppercase;
    letter-spacing:.05em;background:color-mix(in srgb, var(--warn) 20%, var(--panel));color:var(--warn)}
  @media (max-width:820px){.oth-row{grid-template-columns:1fr 1fr}.oth-row.head{display:none}}
  .chip-guest{margin-left:6px;padding:1px 6px;border-radius:999px;background:var(--panel);
    border:1px solid var(--line);font-size:10.5px;text-transform:uppercase;letter-spacing:.05em}
  .sig-good{color:var(--ok)} .sig-ok{color:var(--tx-dim)} .sig-poor{color:var(--warn)}
  .chip-dfs{display:inline-block;margin-left:5px;padding:0 6px;border-radius:999px;font-size:10px;
    letter-spacing:.06em;background:color-mix(in srgb, var(--warn) 22%, var(--panel));color:var(--warn)}
  /* built like the gateway rows: the header is the same grid with a modifier,
     and every control fills its cell, or the columns drift apart */
  /* A message is mostly its words, so it gets a block of its own rather than
     a column squeezed between the settings that describe it. */
  .msg-card{border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin-bottom:10px;background:var(--panel2)}
  .msg-top{display:grid;grid-template-columns:minmax(130px,1.2fr) minmax(150px,1.6fr) 132px 116px 1fr 84px;
    gap:10px;align-items:end}
  .msg-field{display:flex;flex-direction:column;gap:5px;min-width:0}
  .msg-field > label{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--tx-mut)}
  /* the phones under the links are boxes of the same card and must look it:
     their row is not a .tap-row, so they were left with whatever the browser
     draws a bare input as */
  .msg-card input, .msg-card textarea, .tap-row input, .tapkey-row input{font:inherit;font-size:13.5px;background:var(--panel);
    color:var(--tx);border:1px solid var(--line);border-radius:10px;padding:8px 12px;width:100%;
    box-sizing:border-box}
  .msg-card textarea{resize:vertical;min-height:66px;line-height:1.45;font-family:inherit}
  .msg-card input:focus, .msg-card textarea:focus, .tap-row input:focus,
  .tapkey-row input:focus{outline:none;border-color:var(--info)}
  .msg-body{margin-top:10px}
  .msg-tools{display:flex;gap:6px;align-items:center;margin:6px 0 0;flex-wrap:wrap}
  .msg-preview{margin-top:10px;font-size:12.5px;color:var(--tx-dim)}
  .msg-preview:empty{display:none}
  .msg-preview .lbl.warn{color:var(--warn)}
  .msg-preview .lbl{color:var(--tx-mut);font-size:11px;text-transform:uppercase;letter-spacing:.06em;display:block;margin-bottom:5px}
  /* a phone notification, roughly as ntfy / Telegram draw one */
  .ntfy{max-width:420px;background:var(--panel2);border:1px solid var(--line);border-radius:14px;padding:10px 13px;color:var(--tx);box-shadow:0 6px 18px rgba(0,0,0,.25)}
  .ntfy-head{display:flex;justify-content:space-between;font-size:11px;color:var(--tx-mut);margin-bottom:4px}
  .ntfy-app{font-weight:600;letter-spacing:.02em}
  .ntfy-title{font-weight:600;font-size:13.5px;margin-bottom:2px}
  .ntfy-text{white-space:pre-wrap;line-height:1.35}
  .ntfy-img{margin-top:6px;font-size:11.5px;color:var(--tx-mut);word-break:break-all}
  .ntfy.crit{border-color:rgba(248,81,73,.5)} .ntfy.crit .ntfy-title{color:var(--crit)}
  .ntfy.warn .ntfy-title{color:var(--warn)} .ntfy.info .ntfy-title{color:var(--info)}
  .msg-actions{display:flex;gap:6px;justify-self:end}
  /* wide and low rather than a tall column: ~180 emoji or the whole fact
     catalogue should fit on screen without scrolling the page */
  .pickbox{position:absolute;z-index:70;background:var(--panel);border:1px solid var(--line);border-radius:12px;
    padding:10px 12px;box-shadow:0 12px 32px rgba(0,0,0,.45);width:min(720px,94vw);max-height:min(70vh,520px);overflow:auto}
  .pickbox.facts{width:min(860px,94vw)}
  .pickbox.facts .row{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:2px 8px}
  .pickbox.facts button{font-size:12.5px;text-align:left;padding:3px 6px;white-space:normal;overflow-wrap:anywhere;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--info)}
  .pickbox.facts button .d{font-family:inherit;color:var(--tx-dim);font-size:11.5px;margin-left:6px;font-family:system-ui,sans-serif}
  /* a grid, so the count and the bin line up down the column however long a
     room's name is */
  .room-row{display:grid;grid-template-columns:minmax(160px,300px) 120px 36px;align-items:center;gap:10px;padding:5px 0}
  .room-row > input{width:100%;box-sizing:border-box}
  .room-row > .muted{justify-self:start;white-space:nowrap}
  .room-row > .iconbtn{justify-self:end}
  /* The phones borrowed the rooms' row, which keeps 36px at the end for one
     button. Two of them did not fit and stood on top of "last used ...".
     Their own row: the name, then whatever is left over, then as much as the
     buttons need - hard against the right edge, clear of the words. */
  .tapkey-row{display:grid;grid-template-columns:minmax(160px,300px) minmax(0,1fr) max-content;
    align-items:center;gap:12px;padding:5px 0}
  .tapkey-row > input{width:100%;box-sizing:border-box}
  .tapkey-row > .muted{justify-self:start;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .tapkey-row > .btnrow{justify-self:end;flex-wrap:nowrap;gap:6px}
  .room-row input{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:9px;padding:7px 10px;min-width:180px}
  .room-assign{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:8px;margin-top:8px;align-items:stretch}
  .room-item{display:grid;grid-template-columns:minmax(0,1fr);gap:3px;font-size:13px;color:var(--tx-dim);min-width:0;
    padding:6px 8px;border:1px solid var(--line);border-radius:9px;background:var(--panel2)}
  .room-item .room-name{color:var(--tx);font-weight:600;word-break:break-word;line-height:1.25}
  /* Nothing has to be in a room, so a thing that is in none is a question
     left open rather than a fault - the same amber the rest of the page uses
     for that, at a fraction of its strength. A line down the edge and a tint
     barely off the card: the eye finds them when it goes looking and they do
     not shout across the card at somebody who is not. */
  .room-item.unplaced{border-color:rgba(210,153,34,.3);background:rgba(210,153,34,.05);
    box-shadow:inset 2px 0 0 rgba(210,153,34,.5)}
  .room-item.unplaced select{color:var(--tx-dim)}
  .room-item select{font:inherit;font-size:12.5px;background:var(--panel);color:var(--tx);border:1px solid var(--line);border-radius:7px;padding:4px 6px;width:100%;min-width:0}
  .eicon{display:inline-block;width:20px;text-align:center;margin-right:2px;opacity:.85}
  .tbl tr.eroom td{background:rgba(88,166,255,.06);border-top:1px solid var(--line)}
  .tbl tr.eroom .efold{display:inline-block;width:12px;color:var(--tx-mut)}
  .tbl tr.eplug td:first-child{padding-left:22px}
  /* the row above the room cards: every label on the same line, every control
     under its own, whatever kind of control it is */
  .heat-bar{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,max-content));gap:10px 26px;align-items:end;margin-top:10px}
  .heat-bar .set-item{gap:6px}
  .heat-bar .heat-sw{display:flex;align-items:center;height:34px}
  .heat-bar input{max-width:110px}
  .heat-actions{display:flex;align-items:center;gap:10px;height:34px}
  .heatcard{padding:14px 16px}
  .heatcard.warn{border-color:rgba(210,153,34,.45)}
  .heat-head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap}
  .heat-head h3{margin:0;font-size:15px}
  .heat-title{display:flex;align-items:center;gap:10px}
  .heatcard.unheated{opacity:.6}
  .heat-now{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
  .heat-ctl{display:inline-flex;align-items:center;gap:6px;margin-left:8px}
  .heat-ctl .lbl{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .heat-temp{font-size:21px;font-weight:650;color:var(--tx)}
  .heat-want{font-size:13px;color:var(--info);display:inline-flex;align-items:baseline;gap:7px}
  .heat-want.hand{color:var(--warn);font-size:16px;font-weight:650}
  .heat-hand{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;padding:2px 7px;border-radius:999px;background:rgba(210,153,34,.16);color:var(--warn)}
  .heat-hand.dim{background:rgba(139,148,158,.12);color:var(--tx-mut)}
  .heat-valve{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:5px;font-size:12.5px;color:var(--tx-dim)}
  .heat-valve .hv-name{color:var(--tx);font-weight:600}
  .heat-valve .hv-bits{color:var(--tx-mut);margin-right:6px}
  .heat-valve button{margin-left:6px}
  .heat-handbar{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:8px}
  .heat-handbar .lbl{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut);margin-right:2px}
  .heat-slider{-webkit-appearance:none;appearance:none;flex:1 1 190px;min-width:130px;max-width:340px;height:8px;border-radius:999px;
    background:linear-gradient(90deg,var(--info) var(--fill,50%),rgba(139,148,158,.22) var(--fill,50%));outline:none;cursor:pointer;padding:0;border:none}
  .heat-slider::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;border-radius:50%;background:var(--tx);
    border:3px solid var(--info);box-shadow:0 1px 4px rgba(0,0,0,.5);cursor:grab}
  .heat-slider::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:var(--tx);border:3px solid var(--info);cursor:grab}
  .heat-read{min-width:66px;text-align:center;font-size:14px;font-weight:650;color:var(--info);font-variant-numeric:tabular-nums}
  .heat-handbar select{font:inherit;font-size:12px;background:var(--panel2);color:var(--tx-dim);border:1px solid var(--line);border-radius:8px;padding:4px 7px}
  .heat-handbar button{min-width:30px}
  /* The presets are a row inside the hand bar, and on a phone there are more
     of them than fit across it. They wrap within the card rather than hang
     over its edge, so min-width:0 lets the row be squeezed and flex-wrap
     folds it onto a second line. */
  .heat-presets{display:inline-flex;flex-wrap:wrap;min-width:0;gap:4px;margin-left:10px;padding-left:10px;border-left:1px solid var(--line)}
  .heat-presets .btn.on{color:var(--info);border-color:rgba(88,166,255,.5);background:rgba(88,166,255,.12)}
  /* Max is not one of the three temperatures: it is the opposite of Off, and
     it reads as heat rather than as a setting */
  .heat-presets .btn.heat-max.on{color:var(--warn);border-color:rgba(210,153,34,.55);background:rgba(210,153,34,.14)}
  .heat-temps{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px 12px;margin-top:10px}
  .heat-t select{min-width:0;max-width:100%}
  .heat-t{display:flex;flex-direction:column;gap:4px}
  .heat-t .lbl{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .heat-t input,.heat-t select{font:inherit;font-size:13px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:8px;padding:5px 8px}
  .heat-plan{margin-top:12px;display:flex;flex-direction:column;gap:6px}
  /* the switch line stands apart from the plan above it, and its label and
     switch sit on the same baseline instead of the switch riding high */
  .heat-window{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);align-items:center;gap:12px}
  .heat-window label{margin:0}
  .heat-windows{display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center;margin-top:8px;font-size:12.5px;color:var(--tx-dim)}
  .heat-windows .lbl{flex-basis:100%;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .heat-win{display:inline-flex;align-items:center;gap:5px;cursor:pointer}
  .heat-step{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
  .heat-step input[type=time],.heat-step select{font:inherit;font-size:12.5px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:8px;padding:4px 7px}
  .heat-days{display:flex;gap:3px}
  .daybtn{font:inherit;font-size:11px;padding:3px 6px;border-radius:7px;border:1px solid var(--line);background:transparent;color:var(--tx-mut);cursor:pointer}
  .daybtn.on{background:rgba(88,166,255,.16);color:var(--info);border-color:rgba(88,166,255,.45)}
  .acbox{position:absolute;z-index:71;background:var(--panel);border:1px solid var(--line);border-radius:10px;box-shadow:0 12px 32px rgba(0,0,0,.45);
    min-width:320px;max-width:min(560px,92vw);max-height:300px;overflow:auto;padding:4px;font-size:12.5px}
  .ac-kind{display:inline-grid;place-items:center;width:15px;height:15px;border-radius:4px;margin-right:6px;
    font-size:9.5px;font-weight:700;vertical-align:1px;font-family:ui-monospace,Menlo,monospace}
  .ac-kind.prop{background:var(--info-bg);color:var(--info)}
  .ac-kind.func{background:rgba(163,113,247,.14);color:var(--batt)}
  .ac-kind.proc{background:rgba(240,136,62,.14);color:var(--load)}
  .ac-kind.obj{background:var(--panel2);color:var(--tx-dim)}
  .ac-kind svg{width:11px;height:11px}
  .ac-group{padding:6px 8px 2px;font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .ac-row{display:grid;grid-template-columns:max-content 1fr;column-gap:10px;padding:5px 8px;border-radius:7px;cursor:pointer;align-items:baseline}
  .ac-row.sel{background:rgba(88,166,255,.14)}
  .ac-name{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--info);white-space:nowrap}
  .ac-desc{color:var(--tx);white-space:normal;overflow-wrap:anywhere;line-height:1.35}
  .ac-ex{grid-column:2;color:var(--tx-mut);font-size:11.5px;white-space:normal;overflow-wrap:anywhere}
  .ac-empty{padding:8px 10px;color:var(--tx-mut)}
  /* a ready-made block: its name reads as words, and what it would write is
     shown underneath as it will look, line breaks and all */
  .ac-row.block .ac-name{color:var(--ok);font-family:inherit;font-weight:600}
  .ac-ex.shows{white-space:pre-wrap;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
    color:var(--tx-dim);background:#0d111788;border:1px solid var(--line);border-radius:7px;
    padding:4px 7px;margin-top:3px}
  .ac-foot{position:sticky;bottom:-4px;display:flex;align-items:center;gap:12px;margin:4px -4px -4px;
    padding:5px 10px;background:var(--panel2);border-top:1px solid var(--line);
    font-size:11px;color:var(--tx-mut)}
  .ac-foot b{color:var(--tx-dim);font-weight:600}
  .ac-mode{position:sticky;top:-4px;z-index:2;margin:-4px -4px 2px;padding:5px 10px;
    background:var(--panel2);border-bottom:1px solid var(--line);
    font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--info)}
  .ac-count{margin-left:auto}
  .ac-group{position:sticky;top:-4px;background:var(--panel);z-index:1}
  .pickbox h4{margin:6px 0 4px;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut);font-weight:600}
  .pickbox .row{display:flex;flex-wrap:wrap;gap:3px}
  .pickbox button{background:none;border:0;font-size:19px;line-height:1;padding:4px 5px;border-radius:8px;cursor:pointer}
  .pickbox button:hover{background:var(--panel2)}
  @media (max-width:760px){.msg-top{grid-template-columns:1fr 1fr}}
  .person-row{display:grid;grid-template-columns:54px minmax(110px,1fr) minmax(140px,1fr) minmax(180px,2fr) 96px 150px 132px 40px;
    gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid rgba(38,44,55,.5)}
  .person-why{grid-column:1 / -1;padding:0 0 8px 62px;margin-top:-4px;font-size:12.5px;color:var(--tx-dim);border-bottom:1px solid rgba(38,44,55,.5)}
  .person-why b{color:var(--tx-mut);font-weight:600}
  .person-row:has(+ .person-why){border-bottom:none}
  .person-row input{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:10px;padding:8px 12px;width:100%;box-sizing:border-box}
  .person-row input:focus{outline:none;border-color:var(--info)}
  .person-head{color:var(--tx-mut);font-size:11px;letter-spacing:.09em;text-transform:uppercase;
    border-bottom:1px solid var(--line);padding-bottom:8px}
  .person-head .r, .person-row .r{justify-self:end}
  .ptrig-head{color:var(--tx-mut);font-size:11px;letter-spacing:.09em;text-transform:uppercase;
    border-bottom:1px solid var(--line);padding-bottom:8px}
  .person-macs{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
  .macchip{display:inline-flex;align-items:baseline;gap:7px;padding:3px 9px;border-radius:999px;background:var(--panel2);
    border:1px solid var(--line);font-size:12.5px}
  .macchip .macname{font-weight:600}
  .macchip .macaddr{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;color:var(--tx-mut)}
  .macchip button{background:none;border:0;color:var(--tx-mut);cursor:pointer;font-size:13px;line-height:1;padding:0}
  .macchip button:hover{color:var(--crit)}
  .ptrig-row{display:grid;
    grid-template-columns:46px minmax(110px,1fr) minmax(120px,1.1fr) 20px minmax(160px,1.6fr) minmax(96px,.9fr) 40px;
    gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid rgba(38,44,55,.5)}
  .ptrig-row select{width:100%;box-sizing:border-box}
  .ptrig-row .r{justify-self:end}
  .dbb-row{display:grid;grid-template-columns:minmax(130px,170px) minmax(160px,1fr) 90px 320px;gap:10px;align-items:center;padding:6px 0;border-bottom:1px solid rgba(38,44,55,.5)}
  .dbb-row .dbb-acts{display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap}
  .dbb-head{color:var(--tx-mut);font-size:11px;letter-spacing:.7px;text-transform:uppercase;font-weight:700}
  .dbb-acts{display:inline-flex;gap:6px}
  @media (max-width:640px){
    .person-row,.ptrig-row{grid-template-columns:1fr 1fr;grid-auto-rows:auto}
    .person-head,.ptrig-head{display:none}}
  @media (max-width:900px){.dbb-row{grid-template-columns:1fr 1fr}}
  .pager{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:12px}
  .pager .pg.current{border-color:var(--info);color:var(--info);opacity:1}
  .pager .pg:disabled.current{opacity:1}
  .pager .pg-dots{color:var(--tx-mut);padding:0 4px} .pager .pg-info{margin-left:8px}
  .combine-sel{font-weight:700;min-width:64px}
  .subtabs{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 14px}
  .subtabs button{appearance:none;cursor:pointer;font:inherit;font-size:13.5px;font-weight:600;
    background:var(--panel2);color:var(--tx-dim);border:1px solid var(--line);border-radius:999px;padding:7px 15px;
    transition:color .12s,border-color .12s,background .12s}
  .subtabs button:hover{color:var(--tx);border-color:var(--tx-mut)}
  .subtabs button.on{color:var(--info);border-color:var(--info);background:rgba(88,166,255,.10)}
  #tab-control .grid.charts > .sec-off{display:none !important}
  .kv-list{display:grid;grid-template-columns:1fr;gap:0}
  .kv-list .kv{display:flex;justify-content:space-between;gap:16px;padding:6px 0;border-bottom:1px solid rgba(38,44,55,.5);font-size:13.5px}
  .kv-list .kv .k{color:var(--tx-dim)}
  .kv-list .kv .v{text-align:right;font-weight:600}
  #db-restore-select{font:inherit;font-size:13px}
  .attnbox.wide{width:min(900px,96vw)}
  .attnbox{width:min(640px,94vw);max-height:86vh;overflow:auto;border-radius:20px;padding:22px 24px 20px;
    background:linear-gradient(160deg,#1b2230 0%,#141922 60%,#11151d 100%);border:1px solid #2b3444;
    box-shadow:0 24px 70px rgba(0,0,0,.6),0 0 0 1px rgba(255,255,255,.03) inset;animation:rise .2s cubic-bezier(.2,.9,.3,1)}
  .attnhead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}
  .attnhead h3{margin:0;font-size:16px}
  .attn-item{display:grid;grid-template-columns:auto 1fr;gap:6px 12px;padding:10px 0;border-bottom:1px solid rgba(38,44,55,.6);align-items:start}
  .attn-item:last-child{border-bottom:none}
  .attn-item .lvl{font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;font-weight:700;padding:3px 8px;border-radius:999px;margin-top:2px;white-space:nowrap}
  .attn-item .lvl.crit{background:rgba(248,81,73,.16);color:var(--crit)}
  .attn-item .lvl.warn{background:rgba(210,153,34,.16);color:var(--warn)}
  .attn-item .lvl.info{background:rgba(88,166,255,.14);color:var(--info)}
  .attn-item .who{font-weight:600;cursor:pointer}
  .attn-item .who:hover{color:var(--info)}
  .attn-item .why{color:var(--tx-dim);font-size:13px;line-height:1.5}
  .attn-item .when{color:var(--tx-mut);font-size:12px}
  .attn-ok{color:var(--ok);font-weight:600;padding:6px 0 2px}
  .attn-item .lvl.ok{background:rgba(63,185,80,.14);color:var(--ok)}
  .attn-item .lvl.dim{background:rgba(139,148,158,.14);color:var(--tx-mut)}
  .bindtbl td,.bindtbl th{padding:6px 10px}
  /* the same grid the other editors use, so one row of labels above the
     sections does for all of them */
  /* six columns, not seven: the grip is positioned over the row rather than
     taking a cell of its own, so a column reserved for it put every heading
     one place to the left of what it named */
  .tap-row{display:grid;grid-template-columns:44px minmax(140px,1.05fr) minmax(140px,1.05fr)
    minmax(115px,.8fr) 62px minmax(80px,.55fr) var(--tap-tools,auto);gap:10px;align-items:center;
    padding:7px 6px;border-radius:10px}
  /* .hasgrab adds the room for the handle; the header has no handle, so it is
     nudged by the same amount or every column sits one notch to the left */
  /* Two faults that were in every one of these and were fixed one at a time
     until it was plain they are the same two faults:
       - a row carries .hasgrab, which indents it to make room for the drag
         handle; a header has no handle, so without the same indent every
         column name sits one notch to the left of what it names;
       - a header that inherits its row's rounded corners lifts the ends of
         its bottom border off the line.
     Said once here rather than five times apart. */
  .tap-head,.bind-head,.person-head,.ptrig-head,.smscmd-head,.gw-head,.mchan-head{border-radius:0}
  .tap-head,.bind-head,.person-head,.ptrig-head,.smscmd-head{padding-left:16px}
  /* The gateways carry no drag handle and so no indent - not at rest, not
     while arranging; measured with gateways on the page, both ways. A header
     indented to match an indent the rows never take is what put every name
     sixteen pixels right of its box. It takes none. */
  .tap-row:hover:not(.tap-head){outline:1px solid rgba(88,166,255,.35);outline-offset:2px}
  .tap-head{color:var(--tx-mut);font-size:11px;letter-spacing:.7px;text-transform:uppercase;font-weight:700;
    border-bottom:1px solid var(--line);padding-bottom:6px;margin-bottom:2px}
  .tap-row.offrow{opacity:.55}
  .tap-what{display:flex;flex-direction:column;gap:6px;min-width:0}
  /* the writing desk is a second line of the same row, so the columns above
     it stay where they are however much is written underneath */
  .tap-storybox{grid-column:1 / -1;padding:2px 0 4px 44px}
  .tap-act{min-width:0;display:flex;align-items:center}
  .tap-act select{width:100%}
  .tap-act .scene-note{line-height:1.3}
  .tap-storybox{display:flex;flex-direction:column;gap:6px;min-width:0}
  .tap-storybox[hidden],.tap-storytools[hidden],.tap-story[hidden],.tap-preview[hidden]{display:none}
  .tap-story{font:inherit;font-size:13.5px;background:var(--panel);color:var(--tx);
    border:1px solid var(--line);border-radius:10px;padding:9px 12px;width:100%;
    box-sizing:border-box;resize:vertical;min-height:92px;line-height:1.5;font-family:inherit}
  .tap-story:focus{outline:none;border-color:var(--info)}
  .tap-storytools{margin-top:0}
  .tap-preview{margin-top:2px;font-size:12px}
  .tap-what > *{min-width:0}
  .tap-tools{justify-self:end;white-space:nowrap}
  @media (max-width:700px){.tap-row{grid-template-columns:1fr 1fr} .tap-head{display:none}}
  .tap-used{padding:7px 0}
  /* how a link was opened last time: plain when it is on the road the links
     are set to, amber when it is still on the old one and there is a switch
     waiting to be thrown - a question left open, not a fault */
  /* how the links are opened, over the list of them: the switch is in
     Settings and the phones are at the foot of the card, and a person looking
     at their links is looking at neither */
  .tapmode{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:8px 10px;margin-bottom:10px;
    border:1px solid var(--line);border-radius:10px;background:var(--panel2);font-size:12.5px}
  .tapmode-what{font-weight:600;color:var(--tx)}
  .tapmode-code{color:var(--tx-mut)}
  .tapmode-code.on{color:var(--ok)}
  .tapmode.on{border-color:rgba(63,185,80,.3)}
  .tapmode .btn{margin-left:auto}
  /* one press waiting for somebody to say yes */
  .appr-row{display:flex;align-items:center;gap:12px;padding:9px 10px;margin-bottom:8px;
    border:1px solid var(--line);border-left:3px solid var(--info);border-radius:10px;background:var(--panel2)}
  .appr-icon{font-size:15px}
  .appr-what{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
  .appr-ipline{display:block;overflow-wrap:anywhere}
  .appr-ipline .obj-mark{margin-left:4px;vertical-align:-2px}
  /* in the history the address column is as wide as its widest address; the
     mark sits in the gap after it rather than widening the column */
  #blocked-history td .obj-mark{margin-left:4px;margin-right:-18px;vertical-align:-2px}
  /* on a phone the marks, the time left and the button took the whole row,
     and the address and its story were left a column a few letters wide,
     every row thousands of pixels tall: the address goes under them */
  @media (max-width:640px){
    #blocked-list .appr-row,#blocked-watch .appr-row{flex-wrap:wrap;row-gap:6px}
    #blocked-list .appr-what,#blocked-watch .appr-what{flex:1 1 100%;order:5}
  }
  .appr-link{font-weight:620;color:var(--tx)}
  .appr-left{font-variant-numeric:tabular-nums;color:var(--tx-dim);white-space:nowrap}
  .appr-left.soon{color:var(--warn);font-weight:650}
  /* the same hand every other row on the page gets under the pointer */
  .appr-row:hover{background:rgba(88,166,255,.07)}
  .appr-router.off{opacity:.75}
  .appr-router.sick{filter:grayscale(1)}
  /* the boxes in the variables dialogue: the same shape every box on the page
     has, rather than whatever the browser draws a bare input as */
  .varbox{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:7px 10px;width:150px;box-sizing:border-box;
    font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
  .varbox.wide{width:240px;max-width:100%}
  .varbox:focus{border-color:var(--info);outline:none}
  .varbox::placeholder{color:var(--tx-mut);font-family:inherit}
  /* a cell that must not be broken across lines. There was a rule for this,
     but only inside a wifi tile, so every table cell asking for it wrapped
     anyway - a date over two lines and "let back in" over three. */
  td.nowrap, th.nowrap, .nowrap{white-space:nowrap}
  /* on the list to be seen, and doing nothing: struck through, in the colour
     of something that is allowed, so it cannot be read as kept out */
  .appr-row.spared{border-left-color:var(--ok);background:rgba(63,185,80,.06)}
  .appr-row.spared .appr-link{text-decoration:line-through;text-decoration-color:var(--tx-mut)}
  .appr-row.spared .appr-left{color:var(--ok)}
  .appr-row .iconbtn{opacity:.55;transition:opacity .12s}
  .appr-row:hover .iconbtn,.appr-row:focus-within .iconbtn{opacity:1}
  /* the same hand a row on the network gets: a tint and a line down the
     edge, so the eye keeps its place across eight columns */
  #approvals-past td{vertical-align:top}
  #approvals-past tbody tr:nth-child(odd){background:var(--panel2)}
  #approvals-past tbody tr:hover{background:rgba(88,166,255,.07)}
  /* the line goes on the first cell, not on the row: with border-collapse a
     shadow on a row is drawn under the cells and comes out clipped */
  #approvals-past th:first-child, #approvals-past td:first-child{padding-left:7px}
  #approvals-past tbody tr:hover td:first-child{box-shadow:inset 3px 0 0 var(--info)}
  #blocked-history tbody tr:nth-child(odd){background:var(--panel2)}
  #blocked-history tbody tr:hover{background:rgba(88,166,255,.07)}
  #blocked-history th:first-child, #blocked-history td:first-child{padding-left:7px}
  #blocked-history tbody tr:hover td:first-child{box-shadow:inset 3px 0 0 var(--info)}
  /* a box standing in a row of buttons: the same shape a box in Settings has,
     rather than whatever the browser draws a bare input as */
  #blocked-ip{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:8px 11px;width:220px;max-width:100%;
    box-sizing:border-box;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
  #blocked-ip:focus{border-color:var(--info);outline:none}
  #blocked-ip::placeholder{color:var(--tx-mut)}
  .tap-way{font-size:11px;color:var(--tx-mut)}
  .tap-way.behind{color:var(--warn)}
  .bindrow{cursor:pointer}
  .bindrow-bad td{background:color-mix(in srgb, var(--warn) 9%, transparent)}
  .bindmark{width:20px;text-align:center;opacity:.75}
  .bindacts{white-space:nowrap;text-align:right;opacity:0;transition:opacity .12s}
  .bindrow:hover .bindacts,.bindrow:focus-within .bindacts{opacity:1}
  .bindacts .btn{margin-left:4px}
  .binddetail td{background:var(--panel2);border-top:0}
  .binddetail-in{display:flex;flex-direction:column;gap:3px;padding:4px 2px 8px 30px;font-size:12.5px}
  .bindline{display:flex;gap:10px;align-items:baseline}
  .bindlabel{min-width:110px;color:var(--tx-mut);font-size:11px;letter-spacing:.05em;text-transform:uppercase}
  .bindvalue{color:var(--tx-dim);overflow-wrap:anywhere}
  .bindbad{border:1px solid var(--warn);border-radius:10px;padding:10px 12px;margin-bottom:10px;
    background:color-mix(in srgb, var(--warn) 7%, transparent)}
  .bindname{font-weight:650;color:var(--tx)}
  .tbl tr.dim td{color:var(--tx-dim)}
  .mqtt-warn{color:var(--warn);font-size:12px;align-self:center;max-width:340px;overflow-wrap:anywhere}
  .mqtt-strip{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:8px 10px;margin-top:6px;border-top:1px dashed var(--line)}
  .mqtt-strip .lbl{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .mqtt-strip input{font:inherit;font-size:12.5px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:8px;padding:5px 8px;min-width:120px}
  .mqtt-strip input:disabled,.mqtt-strip select:disabled{opacity:.45}
  .mqtt-strip select{font:inherit;font-size:12.5px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);border-radius:8px;padding:5px 8px}
  .pc-block{border-bottom:1px solid rgba(38,44,55,.5)}
  .pc-line{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:7px 0;flex-wrap:wrap}
  .pc-left{display:inline-flex;align-items:center;gap:9px;cursor:pointer;user-select:none;min-width:0;flex:1 1 260px}
  .pc-left .fold{color:var(--tx-mut);width:12px}
  .pc-name{font-weight:650;color:var(--tx);white-space:normal;overflow-wrap:anywhere}
  .pc-draw{font-family:ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums;color:var(--tx-dim);font-size:12.5px}
  .pc-btns{display:inline-flex;gap:6px;flex:0 0 auto}
  .pc-body{display:none;padding:2px 0 10px 21px}
  .pc-block.open .pc-body{display:block}
  .agroup-row{grid-template-columns:44px minmax(160px,1.6fr) 64px 36px !important}
  /* One grid for the whole table: the rows take part in it rather than each
     being a grid of its own, which is why the heading used to sit over
     nothing in particular. */
  /* Each row is a row of its own, sharing one column template, so the
     highlight is a single band the whole way across rather than four
     backgrounds with the joins showing. */
  .sms-whotable{--who-cols:minmax(140px,1.6fr) minmax(150px,1fr) 110px 120px;
    margin-top:6px;border:1px solid var(--line);border-radius:10px;background:var(--panel2);overflow:hidden}
  .sms-whotable-row{display:grid;grid-template-columns:var(--who-cols);align-items:center;
    border-bottom:1px solid rgba(38,44,55,.7)}
  .sms-whotable-row:last-child{border-bottom:0}
  .sms-whotable-row:not(.head):hover{background:rgba(88,166,255,.07)}
  .sms-whotable-cell{background:none;border:0}
  .sms-whotable-cell .sw{flex:0 0 auto}
  /* One band per row: no rounding or border on the cells themselves, or the
     row reads as four boxes with the highlight cut between them. */
  .sms-whotable-row > *{padding:9px 12px;border:0;border-radius:0;background:none;
    font-size:13px;color:var(--tx-dim);min-height:42px;display:flex;align-items:center}
  .sms-whotable-row.head{background:rgba(255,255,255,.02);border-bottom:1px solid var(--line)}
  .sms-whotable-row.head > *{padding:8px 12px;font-size:10.5px;letter-spacing:.07em;
    text-transform:uppercase;color:var(--tx-mut);min-height:0}
  .sms-person-name{color:var(--tx);font-weight:600}
  .sms-person-num{font-family:ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums}
  .msg-ways{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
  .msg-way{display:flex;gap:6px;align-items:center;font-size:12.5px;color:var(--tx-dim);cursor:pointer;white-space:nowrap}
  .msg-smswho{display:flex;flex-direction:column;gap:8px;margin:8px 0 4px;padding:9px 11px;
    border:1px solid var(--line);border-left:3px solid var(--info);border-radius:10px;background:var(--panel2)}
  .msg-towrap.off{opacity:.45}
  .whopick{display:flex;flex-direction:column;gap:2px;padding:6px;max-height:260px;overflow:auto}
  .whopick button{text-align:left;font-size:13px;padding:6px 9px;border-radius:8px;white-space:nowrap}
  .whopick .dim{color:var(--tx-mut);font-family:ui-monospace,Menlo,monospace;font-size:12px}
  .msg-smswho .set-item{gap:4px}
  .smscmd-row{display:grid;grid-template-columns:44px minmax(150px,1.3fr) minmax(190px,1.5fr) minmax(130px,.9fr) 44px 44px 36px;
    gap:8px 10px;align-items:center;padding:11px 0 9px;border-bottom:1px solid rgba(38,44,55,.5)}
  /* the answer is written, not squeezed into a column: its own line, the full
     width, with its tools and its preview under it - the same shape the alert
     editor uses */
  #sms-grid > .section{margin:0 0 10px}
  #sms-grid .section-body .set-grid{padding:6px 16px 14px}
  /* a switch stands where an input's box would, so the bands read straight
     across whether the setting is a yes-or-no or something to type in */
  #sms-grid .set-item .sms-sw{display:flex;align-items:center;gap:10px;min-height:39px;cursor:pointer}
  #sms-grid .set-item .sms-sw-word{font-size:13px;color:var(--tx-dim);letter-spacing:.02em}
  #sms-grid .set-item .btnhelp{min-height:1em;line-height:1.35;overflow-wrap:anywhere}
  /* two lines of label and one of note, whether or not the browser has
     subgrid: the boxes then sit level across the row either way */
  /* a switch is a <label> too, and must not be drawn as one: it grew a third taller here */
  #sms-grid .set-item label:not(.sw){line-height:1.3;display:flex;align-items:flex-end;min-height:2.6em}
  #sms-grid .set-item .btnhelp{min-height:1.35em}
  .sms-extras .set-item label:not(.sw){display:flex;align-items:flex-end;min-height:2.6em;line-height:1.3}
  .sms-extras .set-item .btnhelp{min-height:1.35em;line-height:1.35}
  @supports (grid-template-rows: subgrid) {
    .sms-extras{grid-auto-rows:auto}
    .sms-extras > .set-item{display:grid;grid-template-rows:subgrid;grid-row:span 3;
      grid-template-columns:minmax(0,1fr);gap:5px;align-content:start}
  }
  #sms-grid .section-head .muted{font-weight:400;overflow-wrap:anywhere}
  #sms-grid select{width:100%;text-overflow:ellipsis}
  .sms-push{display:flex;flex-direction:column;gap:7px;margin-top:10px;grid-column:1/-1;
    border:1px solid var(--line);border-left:3px solid var(--info);border-radius:10px;padding:10px 12px;background:var(--panel2)}
  .sms-push-head{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .sms-push-url{font-family:ui-monospace,Menlo,monospace;font-size:12.5px;color:var(--tx);overflow-wrap:anywhere}
  .sms-push .btn{align-self:flex-start}
  .smscmd-answer{display:flex;align-items:center;gap:9px;margin-bottom:2px}
  .smscmd-replycell.quiet textarea{opacity:.45}
  .smscmd-replycell{grid-column:1/-1;display:flex;flex-direction:column;gap:7px;min-width:0;padding:2px 0 2px 54px}
  .smscmd-reply{min-height:76px;max-height:240px;resize:vertical;line-height:1.45;width:100%;box-sizing:border-box;
    font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);
    border-radius:10px;padding:9px 12px}
  .smscmd-reply:focus{border-color:var(--info);outline:none;box-shadow:0 0 0 3px rgba(88,166,255,.16)}
  .smscmd-replycell .msg-tools{display:flex;gap:6px;flex-wrap:wrap;margin:0;align-items:center}
  .smscmd-replycell .lbl{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .sms-bubble{background:var(--panel2);border:1px solid var(--line);border-radius:12px 12px 12px 4px;
    padding:8px 11px;color:var(--tx);font-size:12.5px;white-space:pre-wrap;overflow-wrap:anywhere;max-width:40em}
  .smscmd-row > .iconbtn{justify-self:end;width:34px;height:34px;flex:0 0 auto;
    display:inline-flex;align-items:center;justify-content:center;padding:0 !important;gap:0}
  .smscmd-row > .iconbtn svg{display:block}
  .smscmd-head{padding-top:0;padding-right:0;padding-bottom:4px;padding-left:16px;border:0;font-size:10.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--tx-mut)}
  .smscmd-head span{padding-left:2px}
  /* A fold insets what it holds by ten and a header stands above the folds,
     so it takes the same ten or every name sits that far left of its box.
     Written after the headers' own padding so that order agrees with
     specificity rather than relying on one of them. */

  .smscmd-do{display:flex;align-items:center;min-width:0}
  .smscmd-do select{width:100%}
  .smscmd-row input,.smscmd-row select{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:7px 10px;min-width:0;width:100%;box-sizing:border-box}
  .sgroup-row{display:grid;grid-template-columns:44px minmax(120px,1.1fr) minmax(110px,.9fr) minmax(140px,1fr) 74px minmax(110px,.8fr) 60px 36px;
    gap:8px;align-items:center;padding:9px 0 6px;border-bottom:1px solid rgba(38,44,55,.5);position:relative}
  .sgroup-row input,.sgroup-row select{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:7px 10px;min-width:0;width:100%;box-sizing:border-box}
  .sgroup-now{font-family:ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums;color:var(--info);text-align:right;font-weight:600}
  .sgroup-members{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:5px;padding:2px 0 6px 44px}
  .sgroup-chip{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:var(--tx-dim);cursor:pointer;
    border:1px solid var(--line);border-radius:999px;padding:4px 10px;background:var(--panel2)}
  .sgroup-chip.on{color:var(--tx);border-color:rgba(88,166,255,.5);background:rgba(88,166,255,.12)}
  .sgroup-chip input{width:auto;accent-color:var(--info)}
  .sections{display:flex;flex-direction:column;gap:6px;margin-top:6px}
  .section{border:1px solid var(--line);border-radius:10px;background:rgba(88,166,255,.03)}
  .section-head{display:flex;align-items:center;gap:9px;padding:8px 10px 8px 22px;cursor:pointer;user-select:none;position:relative}
  .section-head .fold{color:var(--tx-mut);width:12px} .section-name{font-weight:650;color:var(--tx)}
  .section-count{color:var(--tx-mut);font-size:12px;margin-left:2px}
  .section-body > .muted{padding:6px 4px}
  .section-tools{margin-left:auto;display:inline-flex;gap:4px}
  .section-body{display:none;padding:2px 10px 8px}
  .section.open .section-body{display:block}
  .section-add{margin-top:8px}
  .movemenu{position:fixed;z-index:160;min-width:190px;background:var(--panel);border:1px solid var(--line);border-radius:10px;
    box-shadow:0 12px 34px rgba(0,0,0,.55);padding:6px;display:flex;flex-direction:column;gap:2px}
  .mm-head{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut);padding:4px 8px 6px}
  .mm-item{font:inherit;font-size:13px;text-align:left;background:transparent;border:none;color:var(--tx);padding:7px 10px;border-radius:7px;cursor:pointer}
  .mm-item:hover{background:rgba(88,166,255,.14)} .mm-item.on{color:var(--info)} .mm-new{color:var(--tx-dim);border-top:1px solid var(--line);border-radius:0 0 7px 7px;margin-top:2px}
  .rule-pack{display:block}
  .person-phone{font-variant-numeric:tabular-nums}
  .sms-people{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:10px}
  .sms-free{font:inherit;font-size:13px;background:var(--panel2);color:var(--tx);border:1px solid var(--line);
    border-radius:999px;padding:5px 12px;min-width:180px;font-variant-numeric:tabular-nums}
  .sms-compose textarea{width:100%;box-sizing:border-box;font:inherit;font-size:14px;line-height:1.45;background:var(--panel2);
    color:var(--tx);border:1px solid var(--line);border-radius:12px;padding:11px 13px;resize:vertical;min-height:110px}
  .sms-compose .btnrow{margin-top:8px;align-items:center}
  .sms-preview{margin-top:12px;display:flex;flex-direction:column;gap:5px}
  .sms-bubble{background:var(--panel2);border:1px solid var(--line);border-radius:14px;padding:9px 13px;font-size:13.5px;
    color:var(--tx);white-space:pre-wrap;overflow-wrap:anywhere;max-width:min(520px,100%)}
  .sms-bubble.out{border-color:rgba(88,166,255,.45);background:rgba(88,166,255,.10)}
  .sms-bubble.in{border-color:rgba(63,185,80,.35);background:rgba(63,185,80,.08)}
  .subtabs{display:flex;gap:6px;margin:4px 0 12px}
  .subtabs .on{background:var(--info);border-color:var(--info);color:#fff}
  .sms-line{display:grid;grid-template-columns:minmax(140px,200px) minmax(0,1fr) auto;gap:10px;align-items:start;
    padding:9px 0;border-bottom:1px solid rgba(38,44,55,.5)}
  .sms-line.in .sms-bubble{justify-self:start}
  .sms-line.out .sms-bubble{justify-self:start}
  .sms-line.bad .sms-bubble{border-color:rgba(248,81,73,.5);background:rgba(248,81,73,.08)}
  /* amber, not red: the gateway did not answer, which is a question left open
     rather than a message that failed */
  .sms-line.unsure .sms-bubble{border-color:rgba(210,153,34,.5);background:rgba(210,153,34,.07)}
  .sms-who{display:flex;flex-direction:column;gap:2px;min-width:0}
  .sms-name{font-weight:600;color:var(--tx);overflow-wrap:anywhere}
  .sms-when{color:var(--tx-mut);font-size:11.5px}
  /* quiet: it is worth seeing when somebody asks why a message was slow, and
     worth ignoring the rest of the time */
  .sms-road{color:var(--tx-mut);font-size:10.5px;margin-left:5px;opacity:.65;cursor:help}
  .sms-road:hover{opacity:1}
  .sms-tail{display:flex;align-items:center;gap:6px;white-space:nowrap}
  .findbox{width:min(560px,94vw);background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:14px;
    box-shadow:0 24px 60px rgba(0,0,0,.6);margin-top:8vh;align-self:flex-start}
  #findinput{width:100%;box-sizing:border-box;font:inherit;font-size:16px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:12px;padding:11px 14px;outline:none}
  #findinput:focus{border-color:var(--info);box-shadow:0 0 0 3px rgba(88,166,255,.18)}
  .findlist{max-height:46vh;overflow:auto;margin-top:8px;display:flex;flex-direction:column;gap:2px}
  .finditem{display:flex;align-items:baseline;gap:9px;padding:8px 10px;border-radius:9px;cursor:pointer;font-size:13.5px}
  .finditem .what{color:var(--tx-mut);font-size:11.5px;margin-left:auto;text-transform:uppercase;letter-spacing:.06em}
  .finditem:hover,.finditem.on{background:rgba(88,166,255,.14)}
  .card.found{outline:2px solid var(--info);outline-offset:2px;transition:outline-color .4s}
  .findhint{color:var(--tx-mut);font-size:11.5px;margin:8px 2px 0}
  .energy-reset-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:6px;padding:4px 0 2px}
  .energy-reset-row .btn{justify-content:flex-start;width:100%}
  .money-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px 22px;align-items:end}
  .money-big{font-size:26px;font-weight:650;color:var(--tx);font-variant-numeric:tabular-nums}
  .money-sub{font-size:12px;color:var(--tx-mut);margin-top:2px}
  .money-lbl{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .money-top{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:8px 16px;font-size:12.5px;color:var(--tx-dim);border-top:1px solid var(--line);padding-top:10px}
  .room-name{font-weight:600;color:var(--tx)}
  .ntfy-when{color:var(--tx-mut);font-size:11.5px;margin-left:auto}
  /* every pack keeps the room for a drag handle whether it has one or not, so
     a gateway from config.json, which cannot be dragged, sits in the same
     column as one made here that can - and the header can then line up with
     all of them rather than with whichever happens to come first */
  .gw-pack{display:block;padding-left:16px}
  #messages-list textarea,.msg-card textarea{min-height:170px;max-height:420px;line-height:1.45;font-size:14px}
  .msg-card input,.tap-row input{font-size:14px;padding:9px 12px}
  .msg-tools{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:8px}
  .msg-tools .btn{white-space:nowrap}
  /* said again after .msg-tools: a hidden writing desk stays hidden however
     the styles are read, not only where the more particular rule wins */
  .tap-storytools[hidden]{display:none}
  .msg-preview .sms-bubble{margin-top:4px}
  .acl-row{display:flex;align-items:baseline;gap:9px;padding:5px 0;border-bottom:1px solid rgba(38,44,55,.5);font-size:13px;flex-wrap:wrap}
  .acl-row .mark{width:14px} .acl-row .who{color:var(--tx-dim)} .acl-row .top{font-family:ui-monospace,Menlo,monospace;color:var(--tx)}
  .acl-row .why{color:var(--tx-mut);font-size:12px;margin-left:auto}
  .acl-row.bad .top{color:var(--warn)}
  .acl-row.quiet{opacity:.72}
  /* A row lights up under the pointer, the way a device card does: the same
     outline, so the eye is told the same thing in the same way wherever it
     looks. */
  /* a rule is its main line and the quiet one under it: the pack lights up,
     the line inside it does not - two outlines read as two things */
  .bind-row:not(.bind-head):hover,.rule-pack:hover,.scene-row:hover,.sched-row:hover,
  .sgroup-row:hover,.agroup-row:hover,.smscmd-row:hover,.ptrig-row:not(.head):hover,
  .person-row:not(.head):hover,.mdev:hover,.room-row:hover,.msg-card:hover,.gw-pack:hover,
  .seq-row:hover,.acl-row:hover,.dbb-row:hover,.wc-row:hover,.appr-row:hover{
    outline:1px solid rgba(88,166,255,.35);outline-offset:2px;border-radius:10px}
  /* the row, not each cell: an outline per cell is what made the highlight
     look chopped into four */
  .sms-whotable-row:not(.head):hover{outline:1px solid rgba(88,166,255,.35);outline-offset:-1px}
  /* a table row cannot take an outline offset outwards without the cells
     drifting, so it is drawn just inside the row */
  .bindrow:hover{outline:1px solid rgba(88,166,255,.35);outline-offset:-1px}
  .gw-pack{border-radius:10px}
  .gw-pack:hover{outline-offset:3px}
  .gw-pack .gw-row:hover{outline:0}       /* the pack is outlined, not the row inside it */
  #whatif-row{gap:8px;flex-wrap:wrap;align-items:center}
  #whatif-row select,#whatif-row input{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:7px 10px;min-width:0}
  #whatif-out{margin-top:10px}
  .acl-fix{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin-top:10px;
    font-family:ui-monospace,Menlo,monospace;font-size:12.5px;color:var(--tx);white-space:pre;overflow:auto}
  .lat-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:8px 18px}
  .lat-head{margin:12px 0 4px;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--tx-mut)}
  .lat-row{display:flex;justify-content:space-between;align-items:baseline;gap:10px;padding:5px 0;border-bottom:1px solid rgba(38,44,55,.5);font-size:13px}
  .lat-row .k{color:var(--tx-dim)} .lat-row .v{font-family:ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums;font-weight:600}
  .lat-row .v.ok{color:var(--ok)} .lat-row .v.warn{color:var(--warn)} .lat-row .v.crit{color:var(--crit)} .lat-row .v.dim{color:var(--tx-mut);font-weight:400}
  /* A box that opens a list has to look like one. Each of these rows sets a
     background shorthand of its own, which wiped out the arrow the base
     select draws - so those boxes looked like plain fields and there was
     nothing to say they could be opened. The arrow is put back here, with
     room kept for it; test/columns.py insists the two lists stay in step. */
  .rule-row select,.rule-sub select,.smscmd-row select,.sgroup-row select,.seq-row select,.seq-steps select,
  .mdev-line select,.mchan select,.dev-row select,.scene-actions select,.sched-row select,#whatif-row select{
    background-image:var(--pickarrow);background-repeat:no-repeat;
    background-position:right 9px center;background-size:13px;padding-right:26px}
  /* the small boxes of the heating and the strips: a smaller arrow, less room */
  .trv select,.notify-dev select,.room-item select,.heat-handbar select,.heat-t select,
  .heat-step select,.mqtt-strip select{
    background-image:var(--pickarrow);background-repeat:no-repeat;
    background-position:right 5px center;background-size:11px;padding-right:20px}
  .notify-dev select{padding-right:22px}
  .rowgrab{position:absolute;left:1px;top:50%;transform:translateY(-50%);cursor:grab;color:var(--tx-mut);
    font-size:15px;line-height:1;opacity:.45;padding:2px 3px;user-select:none}
  .rowgrab:hover{opacity:1;color:var(--info)}
  .hasgrab{position:relative;padding-left:16px}
  /* Every row somebody can add with a + is a thing of its own, and it says so
     where the eye looks for it: its mark at the row's left edge, in line with
     the section's above it, rather than tucked inside the first box. */
  .rule-waiting{color:var(--warn)}
  .hasmark{position:relative;padding-left:19px}
  .hasmark > .obj-mark.row-mark{position:absolute;left:0;top:13px;margin:0;opacity:.6}
  .hasmark:hover > .obj-mark.row-mark,.obj-mark.row-mark.open{opacity:1}
  .hasgrab.hasmark{padding-left:34px}
  .hasgrab.hasmark > .obj-mark.row-mark{left:15px}
  .mdev.hasmark,.msg-card.hasmark{padding-left:28px}
  .mdev.hasgrab.hasmark,.msg-card.hasgrab.hasmark{padding-left:40px}
  .mdev.hasmark > .obj-mark.row-mark,.msg-card.hasmark > .obj-mark.row-mark{left:8px;top:15px}
  .mdev.hasgrab.hasmark > .obj-mark.row-mark,.msg-card.hasgrab.hasmark > .obj-mark.row-mark{left:21px}
  .rule-pack.hasmark > .obj-mark.row-mark{top:17px}
  /* on a phone the row's mark takes the narrowest strip it can */
  @media (max-width:640px){
    .hasmark{padding-left:16px}
    .hasgrab.hasmark{padding-left:28px}
    .hasgrab.hasmark > .obj-mark.row-mark{left:13px}
    .mdev.hasmark,.msg-card.hasmark{padding-left:24px}
    .mdev.hasgrab.hasmark,.msg-card.hasgrab.hasmark{padding-left:34px}
    .mdev.hasgrab.hasmark > .obj-mark.row-mark,.msg-card.hasgrab.hasmark > .obj-mark.row-mark{left:16px}
  }
  .dragrow{opacity:.5;outline:1px dashed var(--info);border-radius:8px}
  .readpop{position:fixed;z-index:150;background:var(--panel);border:1px solid var(--line);border-radius:12px;
    box-shadow:0 12px 34px rgba(0,0,0,.55);padding:9px 11px;min-width:230px;max-width:340px;font-size:12.5px;pointer-events:none}
  .rp-head{display:flex;justify-content:space-between;gap:12px;margin-bottom:6px;padding-bottom:6px;border-bottom:1px solid var(--line)}
  .rp-name{font-weight:600;color:var(--tx)} .rp-when{color:var(--tx-mut);font-size:11.5px;white-space:nowrap}
  .rp-list{display:flex;flex-direction:column;gap:2px}
  .rp-row{display:flex;justify-content:space-between;gap:12px;padding:2px 6px;border-radius:6px;color:var(--tx-dim)}
  .rp-row.pick{background:rgba(88,166,255,.14);color:var(--tx)} .rp-row.pick .rp-v{color:var(--info);font-weight:650}
  .rp-k{white-space:normal;overflow-wrap:anywhere} .rp-v{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap}
  .rp-foot{margin-top:6px;padding-top:6px;border-top:1px solid var(--line);color:var(--tx-mut);font-size:11.5px}
  .qrpop{position:fixed;z-index:150;background:#fff;padding:8px 8px 4px;border-radius:12px;
    box-shadow:0 12px 34px rgba(0,0,0,.55);border:1px solid #2b3444;line-height:0}
  .qrpop .qrcap{font:500 10.5px system-ui,sans-serif;color:#555;text-align:center;line-height:1.6;letter-spacing:.04em}
  /* One line, whatever the value is. A long one - an otpauth:// URI is a
     hundred and thirty characters - used to break across four lines and
     become a block, which reads as a different kind of thing from the chip
     beside it. The whole of it is still what is copied, still what the QR
     code holds, and still what the tooltip says; only the drawing is cut. */
  .copyme{display:inline-block;cursor:pointer;background:rgba(88,166,255,.10);border:1px solid rgba(88,166,255,.25);
    border-radius:6px;padding:2px 7px;margin:2px 0;max-width:100%;vertical-align:bottom;
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
    font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11.5px;color:var(--info)}
  .copyme:hover{background:rgba(88,166,255,.20)}
  .attn-item .why code{font-size:11.5px}
  .attn-sec{margin:14px 0 2px;font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--tx-mut)}
  .attn-sec:first-child{margin-top:0}
  #pill,#m-attn-card,#m-online-card,#m-home-card,#m-devices-card{cursor:pointer}
  .askbox #askinput{width:100%;box-sizing:border-box;font:inherit;font-size:16px;text-align:center;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:12px;padding:11px 14px;margin:4px 0 6px}
  .askbox #askinput:focus{outline:none;border-color:var(--info);box-shadow:0 0 0 3px rgba(88,166,255,.18)}
  .pinbox{width:min(380px,94vw);border-radius:20px;padding:28px 26px 22px;text-align:center;
    background:linear-gradient(160deg,#1b2230 0%,#141922 60%,#11151d 100%);
    border:1px solid #2b3444;
    box-shadow:0 24px 70px rgba(0,0,0,.6),0 0 0 1px rgba(255,255,255,.03) inset;
    animation:rise .2s cubic-bezier(.2,.9,.3,1)}
  @keyframes rise{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:none}}
  .pinicon{width:52px;height:52px;margin:0 auto 14px;border-radius:50%;
    display:flex;align-items:center;justify-content:center;color:var(--info);
    background:radial-gradient(circle at 50% 35%,rgba(88,166,255,.28),rgba(88,166,255,.07));
    border:1px solid rgba(88,166,255,.34)}
  .pinicon.danger{color:var(--crit);
    background:radial-gradient(circle at 50% 35%,rgba(248,81,73,.26),rgba(248,81,73,.07));
    border-color:rgba(248,81,73,.34)}
  .pinbox h3{margin:0 0 5px;font-size:18px;font-weight:650;letter-spacing:.2px}
  .pinwhat{margin:0 0 20px;color:var(--tx-dim);font-size:13.5px;line-height:1.45;word-break:break-word}
  .pinwhat b{color:var(--tx);font-weight:600}
  .signform{display:flex;flex-direction:column;gap:10px;margin:0 0 6px;text-align:left}
  .signform[hidden]{display:none}
  .signform input{width:100%;padding:11px 13px;font:inherit;font-size:15px;color:var(--tx);background:#0d1117;
    border:1.5px solid #2b3444;border-radius:12px;transition:border-color .14s,box-shadow .14s}
  .signform input:focus{outline:none;border-color:var(--info);box-shadow:0 0 0 3.5px rgba(88,166,255,.16)}
  .signform.bad input{border-color:var(--crit);box-shadow:0 0 0 3.5px rgba(248,81,73,.13)}
  .signform.bad{animation:shake .32s}
  .pindigits{display:flex;gap:11px;justify-content:center;margin-bottom:6px}
  .pindigits[hidden]{display:none}
  .pindigits input{width:54px;height:64px;text-align:center;font-size:26px;font-weight:650;
    color:var(--tx);background:#0d1117;border:1.5px solid #2b3444;border-radius:13px;
    caret-color:var(--info);transition:border-color .14s,box-shadow .14s,transform .08s}
  .pindigits.wide input{width:min(260px,80vw);font-size:22px;letter-spacing:6px}
  .pindigits input:focus{outline:none;border-color:var(--info);box-shadow:0 0 0 3.5px rgba(88,166,255,.16)}
  .pindigits input.filled{border-color:#3d4a5f;background:#111823}
  .pindigits.bad input{border-color:var(--crit);box-shadow:0 0 0 3.5px rgba(248,81,73,.13)}
  .pindigits.bad{animation:shake .32s}
  @keyframes shake{0%,100%{transform:translateX(0)}20%{transform:translateX(-8px)}
    40%{transform:translateX(7px)}60%{transform:translateX(-4px)}80%{transform:translateX(3px)}}
  .pinother{margin:10px 0 0;font-size:12.5px}
  .pinother[hidden]{display:none}
  .pinother a{color:var(--info);text-decoration:none}
  .pinother a:hover{text-decoration:underline}
  .pinerr{min-height:19px;margin:8px 0 16px;font-size:13px;color:var(--crit)}
  .pinrow{display:flex;gap:10px;justify-content:center}
  .pinrow .btn{min-width:108px;justify-content:center}
  .btn.primary.danger{background:var(--crit-bg);border-color:rgba(248,81,73,.45);color:var(--crit)}
  .btn.primary.danger:hover:not(:disabled){background:rgba(248,81,73,.2);border-color:var(--crit)}
  .btn.primary:hover:not(:disabled){background:rgba(88,166,255,.2);border-color:var(--info)}

  /* ---- Control: a sidebar of sections, one section on screen at a time ---- */
  .ctl-layout{display:grid;grid-template-columns:236px minmax(0,1fr);gap:22px;align-items:start}
  .ctl-main{min-width:0}
  .ctl-nav{position:sticky;top:12px;display:flex;flex-direction:column;gap:2px;background:var(--panel);
           border:1px solid var(--line);border-radius:var(--r);padding:10px;max-height:calc(100vh - 24px);
           overflow:auto;scrollbar-width:thin}
  /* flex:none, or the rail - a column that scrolls - shrinks a heading with
     no text in it to nothing, and everything under it moves up */
  .ctl-nav .ctl-group{font-size:10.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;
                      color:var(--tx-mut);margin:11px 10px 3px;flex:none;height:16px;line-height:16px}
  .ctl-nav .ctl-group:first-of-type{margin-top:10px}
  .ctl-nav button{appearance:none;display:flex;align-items:center;gap:10px;width:100%;text-align:left;
                  font:inherit;font-size:13px;color:var(--tx-dim);background:transparent;border:0;
                  border-radius:9px;padding:6px 10px;cursor:pointer;position:relative;
                  transition:background .12s,color .12s}
  .ctl-nav button svg{flex:none;opacity:.85}
  .ctl-nav button:hover{background:var(--panel2);color:var(--tx)}
  .ctl-nav button.on{background:rgba(88,166,255,.12);color:var(--info);font-weight:600}
  .ctl-nav button.on::before{content:'';position:absolute;left:0;top:6px;bottom:6px;width:3px;
                             border-radius:3px;background:var(--info)}
  .ctl-nav button:focus-visible{outline:2px solid var(--info);outline-offset:1px}
  .ctl-find-wrap{position:relative}
  /* finding anything, from the header of every tab */
  .app-find-wrap{position:relative;width:260px;max-width:100%}
  #app-find{width:100%;box-sizing:border-box;font:inherit;font-size:13px;background:var(--panel2);color:var(--tx);
            border:1px solid var(--line);border-radius:9px;padding:7px 11px}
  #app-find:focus{border-color:var(--info);outline:none}
  .app-found{position:absolute;right:0;top:calc(100% + 4px);width:360px;max-width:92vw;z-index:80;background:var(--panel2);
             border:1px solid var(--line);border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.45);padding:4px;
             max-height:65vh;overflow:auto}
  .app-found .ctl-hit{appearance:none;display:flex;flex-direction:column;align-items:flex-start;gap:1px;width:100%;
             text-align:left;font:inherit;background:transparent;border:0;border-radius:8px;padding:7px 9px;cursor:pointer;color:var(--tx)}
  .app-found .ctl-hit:hover,.app-found .ctl-hit.sel{background:rgba(88,166,255,.12);outline:none}
  @media (max-width: 700px){.app-find-wrap{order:10;width:100%}.app-found{left:0;right:0;width:auto}}
  #ctl-find{width:100%;box-sizing:border-box;font:inherit;font-size:13px;background:var(--panel2);color:var(--tx);
            border:1px solid var(--line);border-radius:9px;padding:6px 11px;height:30px}
  #ctl-find:focus{border-color:var(--info);outline:none}
  .ctl-found{position:absolute;left:0;right:0;top:calc(100% + 4px);z-index:30;background:var(--panel2);
             border:1px solid var(--line);border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.45);
             padding:4px;max-height:60vh;overflow:auto}
  .ctl-nav .ctl-hit{appearance:none;display:flex;flex-direction:column;align-items:flex-start;gap:1px;width:100%;
           text-align:left;font:inherit;background:transparent;border:0;border-radius:8px;padding:7px 9px;
           cursor:pointer;color:var(--tx)}
  .ctl-nav .ctl-hit:hover,.ctl-nav .ctl-hit:focus{background:rgba(88,166,255,.12);outline:none}
  .ctl-hit-t{font-size:13px}
  .ctl-hit-w{font-size:11px;color:var(--tx-mut)}
  .ctl-none{padding:8px 10px;font-size:12.5px;color:var(--tx-mut)}
  .ctl-head{margin:2px 0 16px}
  .ctl-title{display:flex;align-items:center;gap:10px;margin:0;font-size:21px;font-weight:650;color:var(--tx)}
  .ctl-title svg{color:var(--info)}
  .ctl-lede{margin:5px 0 0;color:var(--tx-dim);font-size:13.5px;max-width:780px}
  #tab-control .grid.charts{gap:16px}
  #tab-control .grid.charts > .card{min-width:0}
  #tab-control .grid.charts > .card > h2{display:flex;align-items:center;gap:10px;font-size:15px;
      font-weight:650;letter-spacing:0;text-transform:none;color:var(--tx);margin:0 0 6px}
  #tab-control .grid.charts > .card > h2 .card-info{margin-left:auto;font-size:12px;color:var(--tx-dim);
      padding:4px 10px 4px 8px}
  #tab-control .card-lede{color:var(--tx-dim);font-size:13px;margin:0 0 14px;max-width:900px}
  #tab-control .grid.charts > .card > h2 .card-info,#lock-card > h2 .card-info{display:inline-flex;align-items:center;gap:5px}
  #tab-control .set-card.set-one .set-host > .set-grid > .set-head{display:none}
  #lock-card{display:flex;align-items:center;flex-wrap:wrap;gap:6px 18px;padding:12px 18px}
  #lock-card > h2{display:flex;align-items:center;gap:10px;margin:0;font-size:15px;font-weight:650;
                  letter-spacing:0;text-transform:none;color:var(--tx)}
  #lock-card > h2 .card-info{font-size:12px;color:var(--tx-dim);padding:4px 10px 4px 8px}
  #lock-card > .card-lede{flex:1 1 320px;margin:0;color:var(--tx-dim);font-size:13px}
  /* the lock and how long is left belong at the right edge of the bar, not
     wherever the note happens to end */
  #lock-card > .btnrow{margin:0 0 0 auto;display:flex;align-items:center;gap:10px}
  #lock-card > #lock-note{flex:1 1 320px;min-width:200px}
  #tab-control p.note.note-folded{display:none}
  #tab-control .set-empty{display:none !important}
  #tab-control .set-card .set-bar{margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}
  #tab-control .set-host > .set-grid:first-child{margin-top:0}
  #tab-control .set-host .set-head{font-size:13.5px;font-weight:650;letter-spacing:0;text-transform:none;
      color:var(--tx);padding:14px 0 6px;border-bottom:1px solid var(--line);margin-bottom:4px}
  #tab-control .set-host > .set-grid:first-child .set-head{padding-top:2px}
  #tab-control .set-item label:not(.sw){font-size:12.5px;letter-spacing:0;text-transform:none;color:var(--tx-dim);
      display:flex;align-items:center;gap:6px}
  #tab-control .set-host .set-cluster > .set-item.set-tall > label,
  #tab-control .set-host .set-grid > .set-item.set-tall > label{align-self:stretch;justify-content:flex-start;text-align:left}
  #tab-control .set-host .set-cluster > .set-sub{display:block}
  #tab-control .set-item .iinfo{flex:none;display:inline-grid;place-items:center;width:16px;height:16px;
      border-radius:50%;border:1px solid var(--tx-mut);color:var(--tx-dim);font-size:10.5px;font-weight:700;
      font-style:italic;font-family:Georgia,serif;cursor:pointer;line-height:1;opacity:.75}
  #tab-control .set-item .iinfo:hover,#tab-control .set-item .iinfo:focus{opacity:1;border-color:var(--info);
      color:var(--info);outline:none}
  /* needs the internet: a small globe beside the label. Fourteen pixels and
     no words, so a label keeps its line and the boxes under it keep theirs. */
  #tab-control .set-item label .net-mark{width:15px;height:15px;margin-left:4px;vertical-align:-2px}
  #tab-control .set-item select,#tab-control .set-item input[type=text],#tab-control .set-item input[type=number],
  #tab-control .set-item input[type=password],#tab-control .set-item input[type=time],
  #tab-control .set-item input[type=tel]{min-height:36px}
  .flash-here{animation:flash-here 2s ease-out}
  @keyframes flash-here{0%,35%{box-shadow:0 0 0 2px var(--info);border-radius:10px}100%{box-shadow:0 0 0 2px transparent}}
  /* one setting, whole */
  .sinfo-lead{color:var(--tx);font-size:13.5px;line-height:1.55;margin:0 0 12px}
  .sinfo-now{display:flex;align-items:baseline;flex-wrap:wrap;gap:8px 12px;background:var(--panel2);
             border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin:4px 0 14px}
  .sinfo-k{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--tx-mut)}
  .sinfo-v{font-size:18px;color:var(--tx)}
  .sinfo-src{font-size:12px;border-radius:999px;padding:2px 9px;border:1px solid var(--line);color:var(--tx-dim)}
  .sinfo-src.s-dashboard{color:var(--info);border-color:var(--info)}
  .sinfo-src.s-file{color:var(--ok);border-color:var(--ok)}
  .sinfo-flow{display:flex;align-items:stretch;gap:8px;flex-wrap:wrap;margin:0 0 12px}
  .sinfo-step{flex:1 1 150px;display:flex;flex-direction:column;gap:3px;border:1px solid var(--line);
              border-radius:11px;padding:10px 12px;background:#0d111788;position:relative}
  .sinfo-step.unset{opacity:.55;border-style:dashed}
  .sinfo-step.win{border-color:var(--ok);background:#1b3a2a44;opacity:1}
  .sinfo-sk{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--tx-mut)}
  .sinfo-sv{font-size:14px;color:var(--tx);word-break:break-word}
  .sinfo-badge{align-self:flex-start;margin-top:4px;font-size:10.5px;font-weight:700;color:var(--ok);
               border:1px solid var(--ok);border-radius:999px;padding:1px 8px}
  .sinfo-arrow{align-self:center;color:var(--tx-mut);font-size:18px}
  .sinfo-tech{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;font-size:12px;color:var(--tx-mut);
              margin:0 0 14px}
  .sinfo-tech code{color:var(--tx-dim)}
  /* On a desk: a rail of icons at the left edge, out of the page's way. It
     slides open under the pointer and closes again, or stays open when pinned;
     it scrolls on its own, and never takes the page with it. */
  /* The pin and the find box share one row. The box used to have a row of
     its own, which existed only while the rail was open: opening it under
     the pointer pushed every icon down by the height of that row, and the
     icon somebody was pointing at slid out from under the mouse. One row,
     the same height either way, and nothing moves. */
  .ctl-navtop{display:flex;align-items:center;gap:6px;height:34px;margin:0 0 6px}
  .ctl-navtop .ctl-find-wrap{flex:1 1 auto;min-width:0}
  /* Scrollbars in the page's own colours, and none on the closed rail: it
     still scrolls under the wheel, it just does not shout about it. */
  body.app-shell .wrap > section.panel, body.app-shell .ctl-main, .ctl-nav, .app-found, .ctl-found{
    scrollbar-width:thin;scrollbar-color:rgba(139,148,163,.28) transparent}
  body.app-shell .wrap > section.panel::-webkit-scrollbar, body.app-shell .ctl-main::-webkit-scrollbar,
  .ctl-nav::-webkit-scrollbar{width:8px;height:8px}
  body.app-shell .wrap > section.panel::-webkit-scrollbar-thumb, body.app-shell .ctl-main::-webkit-scrollbar-thumb,
  .ctl-nav::-webkit-scrollbar-thumb{background:rgba(139,148,163,.28);border-radius:8px;border:2px solid transparent;background-clip:padding-box}
  body.app-shell .wrap > section.panel::-webkit-scrollbar-track, body.app-shell .ctl-main::-webkit-scrollbar-track,
  .ctl-nav::-webkit-scrollbar-track{background:transparent}
  body.app-shell .wrap > section.panel::-webkit-scrollbar-button, body.app-shell .ctl-main::-webkit-scrollbar-button,
  .ctl-nav::-webkit-scrollbar-button{display:none;height:0}
  .ctl-nav:not(.open):not(.pinned){scrollbar-width:none}
  .ctl-nav:not(.open):not(.pinned)::-webkit-scrollbar{width:0;height:0;display:none}
  @media (min-width: 981px){
    .ctl-layout{display:block}
    #tab-control{padding-left:var(--rail-pad,0px);transition:padding-left .18s ease}
    .ctl-nav{position:fixed;top:var(--nav-top,0px);bottom:0;left:0;width:58px;z-index:60;max-height:none;
             border-left:0;border-radius:0 14px 14px 0;padding:8px 8px 14px;overflow-x:hidden;overflow-y:auto;
             overscroll-behavior:contain;transition:width .18s ease,box-shadow .18s ease}
    .ctl-nav.open,.ctl-nav.pinned{width:252px}
    .ctl-nav.open:not(.pinned){box-shadow:10px 0 34px rgba(0,0,0,.55)}
    .ctl-navtop{justify-content:flex-start}
    .ctl-nav .ctl-pin{appearance:none;display:grid;place-items:center;width:34px;height:30px;border-radius:8px;border:1px solid transparent;
             background:transparent;color:var(--tx-mut);cursor:pointer;flex:none;padding:0}
    .ctl-nav .ctl-pin:hover{color:var(--tx);background:var(--panel2)}
    .ctl-nav.pinned .ctl-pin{color:var(--info);border-color:rgba(88,166,255,.45);background:rgba(88,166,255,.12)}
    .ctl-nav button[data-sec]{white-space:nowrap}
    .ctl-nav button[data-sec] span{transition:opacity .12s}
    .ctl-nav:not(.open):not(.pinned) .ctl-navtop{justify-content:center}
    .ctl-nav:not(.open):not(.pinned) button[data-sec] span,
    /* shut, the find box is not there to be used - but its row is, so the
       icons below it do not move when it opens */
    .ctl-nav:not(.open):not(.pinned) .ctl-find-wrap{opacity:0;pointer-events:none;width:0;flex:none;overflow:hidden}
    /* A heading shut is a line across the rail - but it keeps the height of
       the heading it will be when the rail opens, line included, or every
       icon below it slides down as it opens and the one under the pointer
       goes with it. */
    .ctl-nav:not(.open):not(.pinned) .ctl-group{font-size:0;height:16px;margin:11px 6px 3px;
        background:linear-gradient(var(--line),var(--line)) center/100% 1px no-repeat}
    .ctl-nav:not(.open):not(.pinned) button.on::before{top:6px;bottom:6px}
  }
  /* Every tab on a desk is an application, not a document: the browser's
     page never scrolls, the header and the tabs stay put, and the tab below
     them scrolls in its own frame across the whole width of the screen. */
  @media (min-width: 981px){
    body.app-shell{height:100vh;height:100dvh;overflow:hidden;box-sizing:border-box;padding-bottom:14px;
                   display:flex;flex-direction:column}
    /* On an iPad 100vh is the screen with Safari's bars put away, so the
       page came out taller than the window and Safari scrolled the whole of
       it - header, tabs and the Editing bar - up out of sight. The visible
       height is used where the browser knows it, and the page itself is
       held still so a scroll inside a section cannot carry it along. */
    html.app-shell-root{height:100%;overflow:hidden;overscroll-behavior:none}
    html.app-shell-root body{overscroll-behavior:none}
    body.app-shell > #alertband{flex:none}
    body.app-shell > .wrap{flex:1 1 auto;min-height:0;width:100%;max-width:none;display:flex;flex-direction:column}
    body.app-shell .wrap > *{flex-shrink:0}
    body.app-shell .wrap > .tabs{margin-bottom:16px}
    body.app-shell .wrap > section.panel:not([hidden]){flex:1 1 auto;min-height:0;overflow-y:auto;
        overscroll-behavior:contain;padding-right:8px;padding-bottom:24px;box-sizing:border-box;
        scrollbar-width:thin;scrollbar-gutter:stable}
    body.app-shell .wrap > section#tab-control:not([hidden]){overflow:hidden;padding-bottom:0;padding-right:0}
  }
  /* Control on a desk is an application, not a document: the browser's page
     never scrolls. The header, the tabs, the Editing bar and the rail stay
     where they are; only the section on the right scrolls, and the whole
     width of the screen is used. */
  @media (min-width: 981px){
    body.ctl-shell #tab-control{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;
                                padding-left:0 !important;transition:none}
    body.ctl-shell #lock-card{flex:none;margin-bottom:12px !important}
    body.ctl-shell .ctl-layout{flex:1 1 auto;min-height:0;position:relative;display:block;padding-left:72px;
                               transition:padding-left .18s ease}
    body.ctl-shell .ctl-layout.nav-pinned{padding-left:266px}
    body.ctl-shell .ctl-nav{position:absolute;top:0;bottom:0;left:0;border-left:1px solid var(--line);
                            border-radius:var(--r)}
    body.ctl-shell .ctl-main{height:100%;overflow-y:auto;overscroll-behavior:contain;padding:0 10px 28px 0;
                             box-sizing:border-box;scrollbar-width:thin;scrollbar-gutter:stable}
  }
  @media (max-width: 980px){
    .ctl-navtop{height:auto}
    .ctl-navtop .ctl-pin{display:none}
    .ctl-layout{grid-template-columns:minmax(0,1fr);gap:12px}
    .ctl-nav{position:static;flex-direction:row;flex-wrap:nowrap;overflow-x:auto;overflow-y:hidden;
             max-height:none;padding:8px;gap:4px;-webkit-overflow-scrolling:touch}
    .ctl-nav .ctl-group{display:none}
    .ctl-nav button{width:auto;flex:none;white-space:nowrap;padding:7px 11px}
    .ctl-nav button.on::before{display:none}
    .ctl-find-wrap{flex:none;width:180px;position:static}
    .ctl-found{left:8px;right:8px;top:auto}
    .ctl-title{font-size:18px}
    .sinfo-arrow{transform:rotate(90deg)}
    .sinfo-flow{flex-direction:column}
  }
  /* things that were wider than a phone: a table scrolls in its own place,
     rows fold onto two lines, a long chip is cut rather than pushing the page */
  @media (max-width: 700px){
    #tab-control .bindtbl{display:block;overflow-x:auto;max-width:100%}
    .smscmd-row{grid-template-columns:44px minmax(0,1fr) 44px 44px 36px}
    .smscmd-row > *:nth-child(3),.smscmd-row > *:nth-child(4){grid-column:2 / -1}
    .smscmd-row.bind-head,.smscmd-row.head{display:none}
    .feedrows{grid-template-columns:minmax(0,max-content) auto minmax(0,1fr)}
    .feedrow > label,.feedrow > .muted{white-space:normal;min-width:0}
    .macchip{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
    #tab-control .card{padding:14px 14px}
    /* every tab: a table wider than a phone scrolls in its own place, and the
       heating rooms are one column the width of the screen */
    .card table{display:block;overflow-x:auto;max-width:100%}
    #heating-rooms{grid-template-columns:minmax(0,1fr)}
  }
  html.booting section.panel{visibility:hidden}
  /* what a text message already understands: one block per topic, one line
     per command - the switch, the words to send, what it does, and an
     example ready to copy onto a phone */
  #smsbuiltin-list{display:grid;gap:12px}
  .smshelp-group{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#0d111788}
  .smshelp-head{display:flex;align-items:center;gap:9px;padding:9px 12px;background:var(--panel2);
       border-bottom:1px solid var(--line);font-size:13.5px}
  .smshelp-head b{text-transform:lowercase}
  .smshelp-head .smshelp-all{margin-left:auto;flex:none}
  .smshelp-icon{font-size:15px;line-height:1}
  .smshelp-row{display:grid;grid-template-columns:auto minmax(150px,max-content) 1fr auto;gap:10px;
       align-items:start;padding:9px 12px;border-top:1px solid var(--line)}
  .smshelp-row:first-of-type{border-top:0}
  .smshelp-row.off{opacity:.45}
  .smshelp-row.off .smshelp-says{text-decoration:line-through}
  .smshelp-mid{display:grid;gap:7px;min-width:0}
  .smshelp-fold{justify-self:start;font-size:11.5px;padding:2px 8px}
  .smshelp-thingbar{display:flex;gap:6px}
  .smshelp-things{display:flex;flex-wrap:wrap;gap:6px;padding:8px;border:1px solid var(--line);
       border-radius:9px;background:var(--panel2);max-height:220px;overflow:auto}
  .smshelp-thing{display:inline-flex;align-items:center;gap:5px;font-size:12px;cursor:pointer;
       border:1px solid var(--line);border-radius:999px;padding:2px 9px 2px 6px;background:#0d111788;
       user-select:none}
  .smshelp-thing input{position:absolute;opacity:0;width:0;height:0}
  .smshelp-tick{width:12px;height:12px;border-radius:4px;border:1px solid var(--line);flex:none;
       display:inline-grid;place-items:center;background:var(--panel)}
  .smshelp-thing input:checked + .smshelp-tick{background:var(--ok,#3fb950);border-color:var(--ok,#3fb950)}
  .smshelp-thing input:checked + .smshelp-tick::after{content:'';width:4px;height:7px;margin-top:-2px;
       border:solid #0d1117;border-width:0 2px 2px 0;transform:rotate(45deg)}
  .smshelp-thing.off{opacity:.5}
  /* taken by one of your own commands: not in use, and why - amber, since
     nothing is wrong, it is only that something else answers first */
  .smshelp-row.taken{background:rgba(210,153,34,.07)}
  .smshelp-row.taken .smshelp-says{text-decoration:line-through;opacity:.7}
  .smshelp-taken{display:flex;gap:7px;align-items:flex-start;font-size:12px;line-height:1.45;
       color:var(--warn,#d29922);border:1px solid rgba(210,153,34,.35);border-radius:8px;
       padding:6px 9px;background:rgba(210,153,34,.08)}
  .smshelp-taken code{color:var(--tx);background:var(--panel2);border-radius:5px;padding:0 5px}
  .smshelp-taken-mark{flex:none}
  .smshelp-head-taken{color:var(--warn,#d29922);font-size:12px}
  .smshelp-fold.has-taken{border-color:rgba(210,153,34,.5);color:var(--warn,#d29922)}
  .smshelp-thing.taken{border-color:rgba(210,153,34,.55);color:var(--warn,#d29922);cursor:help}
  .smshelp-thing.taken .smshelp-tick{background:transparent;border-color:transparent;font-size:11px;
       color:var(--warn,#d29922)}
  .smshelp-thing.off .smshelp-thingname{text-decoration:line-through}
  .smshelp-thing input:focus-visible + .smshelp-tick{outline:2px solid var(--info);outline-offset:1px}
  .smshelp-says{font-size:12.5px;background:var(--panel2);border:1px solid var(--line);
       border-radius:7px;padding:3px 7px;white-space:nowrap;align-self:start}
  .smshelp-what{color:var(--muted);font-size:12.5px;line-height:1.45}
  .smshelp-eg{display:flex;align-items:center;gap:6px;white-space:nowrap;align-self:start}
  .smshelp-eg .lbl{color:var(--tx-mut);font-size:11px;text-transform:uppercase;letter-spacing:.4px}
  .smshelp-eg code{font-size:12.5px;color:var(--ok,#3fb950)}
  .smshelp-copy{flex:none}
  @media (max-width:900px){
    .smshelp-row{grid-template-columns:auto 1fr;row-gap:6px}
    .smshelp-what,.smshelp-eg{grid-column:2}
  }
  .intel-btns{display:inline-flex;gap:6px;margin:6px 0 0;flex-wrap:wrap}
  td .intel-btns{margin:0 0 0 6px;vertical-align:middle}
  .intel-btn{text-decoration:none}
  /* the ask-about buttons of the block history, in a column of their own:
     beside the address they ended wherever the address did, and a page of
     them was a ragged edge rather than a column the eye can run down */
  th.story-ask,td.story-ask{width:1px;white-space:nowrap;padding-left:10px;padding-right:10px}
  td.story-ask .intel-btns{margin:0;flex-wrap:nowrap}

  /* ---- what root does (5.18): the rules of otp's own stylesheet for the same
     panes (otp 1.0.70, web/assets/otp.css), taken as they are and scoped under
     .ot and #zmodal - zigmon has a .bar, .going, .dot and .lines of its own. */
  .ot,#zmodal{--accent:#58a6ff;--violet:#a371f7;--violet-bg:rgba(163,113,247,.12)}
  .ot [hidden],#zmodal [hidden]{display:none !important}
  .ot .drop{display:flex;align-items:center;justify-content:center;gap:8px; min-height:84px;padding:16px;border:1.5px dashed var(--line);border-radius:10px; background:var(--panel2);color:var(--tx-dim);cursor:pointer;text-align:center; transition:border-color .12s,background .12s,color .12s}
  .ot .drop:hover{border-color:var(--accent);color:var(--tx)}
  .ot .drop span{font-size:13px}
  #zmodal{position:fixed;inset:0;background:rgba(3,6,11,.72);display:flex;align-items:center; justify-content:center;z-index:300;padding:24px 16px;backdrop-filter:blur(2px)}
  #zmodal[hidden]{display:none}
  #zmodal .box{background:var(--panel);border:1px solid var(--line);border-radius:16px; width:min(1320px,100%);max-height:92vh;display:flex;flex-direction:column; box-shadow:0 26px 70px rgba(0,0,0,.6)}
  #zmodal .box.narrow{width:min(560px,100%)}
  #zmodal .box .zlines{max-height:46vh;overflow:auto;white-space:pre-wrap}
  #zmodal .box.medium{width:min(860px,100%)}
  #zmodal .body h4{margin:16px 0 6px;font-size:13.5px}
  #zmodal .head{display:flex;align-items:center;gap:12px;padding:16px 20px; border-bottom:1px solid var(--line)}
  #zmodal .head h3{margin:0;font-size:16px;font-weight:650;flex:1;word-break:break-word}
  #zmodal .body{padding:18px 20px;overflow:auto;display:flex;flex-direction:column; min-height:0}
  #zmodal .body > *{flex:none}
  #zmodal .foot{padding:14px 20px;border-top:1px solid var(--line);display:flex;gap:10px; justify-content:flex-end;flex-wrap:wrap}
  #zmodal .foot .left{margin-right:auto}
  .ot .xbtn{appearance:none;background:none;border:0;color:var(--tx-mut);font-size:22px; line-height:1;cursor:pointer;padding:2px 6px;border-radius:8px}
  .ot .xbtn:hover{color:var(--crit);background:var(--crit-bg)}
  .ot .going{margin-top:10px;max-width:none}
  .ot .going.wide{max-width:none}
  .ot .going .bar{height:7px;border-radius:99px;background:var(--panel2);overflow:hidden}
  .ot .going .bar span{display:block;height:100%;width:0;border-radius:99px; background:var(--info);transition:width .4s ease}
  .ot .going .bar span.creeping{width:35% !important; animation:creep 1.3s ease-in-out infinite alternate}
  .ot .going .says{margin-top:6px;color:var(--tx-dim);font-size:12.5px;white-space:nowrap; overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
  .ot .formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px 18px}
  .ot .formgrid .wide{grid-column:1/-1}
  .ot pre.zlines{white-space:pre-wrap;word-break:break-all;font-size:12px;max-height:60vh;overflow:auto; background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin:0}
  .ot .note.bad{color:var(--crit)}
  .ot .note.good{color:var(--ok)}
  #zmodal .body > .set-item + .set-item{margin-top:14px}
  .ot .formgrid > .set-item{margin-top:0 !important}
  .ot .formgrid{align-items:start}
  .ot .note.warn{color:var(--warn)}
  /* backups to other machines (5.21) */
  .ot .rb-off{opacity:.6}
  .ot .rb-copyme{display:block;white-space:pre-wrap;word-break:break-all;font-size:12px;padding:8px 10px;border:1px dashed var(--line);border-radius:8px;background:var(--panel2);cursor:copy;margin:4px 0 8px}
  .ot .rb-pass{font-size:16px;letter-spacing:.5px}
  .ot .rb-panel{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin-top:6px}
  .ot .rb-panel .btnrow{flex-wrap:wrap}
  .ot .rb-paste{margin:10px 0}
  .ot .rb-steps{margin:6px 0;padding-left:18px}
  .ot .rb-kinds{grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}
  .rb-pass-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:12px}
  #zmodal .head{padding:18px 24px}
  #zmodal .head h3{font-size:17px}
  #zmodal .body{padding:20px 24px;gap:0}
  #zmodal .foot{padding:14px 24px;gap:10px}
  #zmodal .box.medium{width:min(900px,100%)}
  .ot .form-sec .formgrid{margin-top:14px}
  .ot .form-sec > .set-item + .formgrid{margin-top:14px}
  .ot .formgrid > .asleep{opacity:.45}
  .ot .notice{padding:12px 14px;border-radius:10px;margin:0 0 16px;border:1px solid var(--line);background:var(--panel2);font-size:14px}
  .ot .notice.good{border-color:rgba(63,185,80,.45);background:var(--ok-bg)}
  .ot .notice.bad{border-color:rgba(248,81,73,.45);background:var(--crit-bg)}
  .ot .notice b{display:block;margin-bottom:2px}
  .ot .note.warn{color:var(--warn)}
  .ot .arow{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:60px;padding:11px 0}
  .ot .arow + .arow{border-top:1px solid rgba(38,44,55,.7)}
  .ot .arow-t{min-width:0;flex:1 1 auto}
  .ot .arow-k{font-size:14px;font-weight:600;color:var(--tx)}
  .ot .arow-s,.ot .arow-t > .small{font-size:12.5px;color:var(--tx-mut);margin-top:2px;line-height:1.45}
  .ot .arow-c{display:flex;gap:8px;align-items:center;flex:none}
  .ot .arow.wide{flex-direction:column;align-items:stretch;gap:8px}
  .ot .arow.wide .arow-c{flex:1 1 auto}
  .ot .arow.wide .arow-c > input{flex:1 1 auto;min-width:0}
  .ot .arow{min-height:50px;padding:7px 0}
  .ot .arow-c input.tw-move{width:240px}
  #zmodal .foot > .tw-foot{flex:1 1 auto;margin:0 !important}
  #zmodal .foot > .tw-foot .tw-del{margin-left:auto;margin-right:8px}
  @media (max-width:560px){.ot .arow{flex-wrap:wrap}.ot .arow-c{flex:1 1 100%;flex-wrap:wrap;justify-content:flex-end}.ot .arow-c > input{flex:1 1 140px;min-width:0;width:auto !important}}
  .ot .cert-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:14px;margin-top:12px}
  .ot .cert-card{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:14px 16px;display:flex;flex-direction:column;gap:10px;min-width:0}
  .ot .cert-h{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
  .ot .cert-title{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 8px;min-width:0}
  .ot .cert-title b{font-size:15px;overflow-wrap:anywhere}
  .ot .cert-target{font-size:10.5px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--tx-dim);width:100%}
  .ot .cert-cn{font:600 14px/1.4 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;overflow-wrap:anywhere}
  .ot .cert-life{height:6px;border-radius:3px;background:var(--line);overflow:hidden;margin:6px 0 2px}
  .ot .cert-life-fill{display:block;height:100%;border-radius:3px;background:var(--ok)}
  .ot .cert-life-fill.warn{background:var(--warn)}
  .ot .cert-life-fill.crit{background:var(--crit)}
  .ot .cert-life-fill.dim{background:var(--tx-mut)}
  .ot .cert-body .facts{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ot .cert-chips{display:flex;flex-wrap:wrap;gap:6px}
  .ot .cchip{display:inline-flex;align-items:center;padding:2px 9px;border-radius:999px;border:1px solid var(--line);font-size:11.5px;font-weight:600;color:var(--tx-dim);background:var(--panel)}
  .ot .cchip.warn{color:var(--warn);border-color:rgba(210,153,34,.4);background:var(--warn-bg)}
  .ot .cchip.dim{opacity:.8}
  .ot .cert-state{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--tx-dim)}
  .ot .cert-state .dot{width:9px;height:9px;border-radius:50%;flex:none;background:var(--tx-mut)}
  .ot .cert-state .dot.ok{background:var(--ok)}
  .ot .cert-state .dot.warn{background:var(--warn)}
  .ot .cert-state .dot.crit{background:var(--crit)}
  .ot .cert-tools{display:flex;flex-wrap:wrap;gap:6px;margin-top:auto;padding-top:4px;border-top:1px solid var(--line);padding-top:10px}
  .ot .cert-files{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}
  .ot .cert-paste{width:100%;min-height:110px;font-size:12px}
  .ot .cert-csr{white-space:pre;overflow-x:auto;font-size:11.5px;padding:10px 12px;border:1px dashed var(--line);border-radius:8px;background:var(--panel2);max-height:340px}
  @media (max-width:520px){.ot .cert-grid{grid-template-columns:1fr}.ot .cert-body .facts{grid-template-columns:1fr}}
  .ot .cert-kv{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:5px 14px;margin:8px 0 0;font-size:13px}
  .ot .cert-kv dt{color:var(--tx-dim);font-weight:600;white-space:nowrap}
  .ot .cert-kv dd{margin:0;overflow-wrap:anywhere;font-weight:600}
  .ot .tls-h{margin:4px 0 10px;font-size:11px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--tx-dim)}
  .ot .tls-tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
  .ot .tls-tile{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:4px;padding:12px 13px;border:1px solid var(--line);border-radius:10px;background:var(--panel2);transition:border-color .15s,background .15s}
  .ot .tls-tile:hover{border-color:var(--tx-mut)}
  .ot .tls-tile:focus-visible{outline:2px solid var(--info);outline-offset:2px}
  .ot .tls-tile.on{border-color:var(--info);background:rgba(88,166,255,.08);box-shadow:0 0 0 1px var(--info) inset}
  .ot .tls-tile-top{display:flex;align-items:center;justify-content:space-between;gap:6px}
  .ot .tls-tile-top b{font-size:13.5px;color:var(--tx)}
  .ot .tls-tile-top .tag{font-size:9.5px}
  .ot .tls-tile-prot{font:600 12px/1.3 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--info)}
  .ot .tls-tile-s{font-size:12px;line-height:1.45;color:var(--tx-mut)}
  .ot .tls-custom{margin-top:12px;padding:12px 14px;border:1px dashed var(--line);border-radius:10px}
  .ot .tls-sub{font-size:12.5px;font-weight:600;color:var(--tx-dim);margin:2px 0 6px}
  .ot .tls-prot{display:flex;gap:8px;margin-bottom:12px}
  .ot .tls-pill{all:unset;cursor:pointer;padding:5px 14px;border-radius:999px;border:1px solid var(--line);font-weight:600;font-size:12.5px;color:var(--tx-mut)}
  .ot .tls-pill.on{border-color:var(--ok);color:var(--ok);background:var(--ok-bg)}
  .ot .tls-ciphers{width:100%;font-size:12px}
  .ot .tls-used{margin-top:10px}
  .ot .tls-used summary{cursor:pointer;font-size:12.5px;color:var(--tx-dim)}
  .ot .tls-cipherlist{display:block;white-space:pre;margin-top:6px;padding:8px 12px;border-radius:8px;background:var(--panel2);font-size:11.5px;color:var(--tx-dim);overflow-x:auto}
  .ot .tls-rows{border-top:1px solid var(--line)}
  .ot .tls-rows .arow.dim .arow-k{color:var(--tx-mut)}
  .ot .tls-rows .arow-c select{min-width:230px}
  .ot .seg{display:inline-flex;border:1px solid var(--line);border-radius:9px;overflow:hidden}
  .ot .seg button{all:unset;cursor:pointer;padding:7px 12px;font-size:12.5px;font-weight:600;color:var(--tx-mut);border-left:1px solid var(--line)}
  .ot .seg button:first-child{border-left:0}
  .ot .seg button.on{background:rgba(88,166,255,.14);color:var(--info)}
  /* Network, Time, Restart, Backups, About and Upgrades laid out as otp's
     admin pages have them (otp 1.0.146, web/assets/otp.css): a heading with
     its small button on the right, facts as a grid of a small-caps label over
     its value, the form in boxes of its own, a card a machine. */
  .ot h2 > .right{margin-left:auto;display:inline-flex;align-items:center;gap:8px;font-size:13px;font-weight:500;color:var(--tx-dim)}
  .ot h2 > .right:empty{display:none}
  .ot h2 > .right + .card-info,#tab-control .grid.charts > .card.ot > h2 > .right + .card-info{margin-left:8px}
  .ot .set-item > .seg{align-self:flex-start;width:max-content;max-width:100%}
  .ot .net-facts{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px 22px;margin:4px 0 2px}
  .ot .net-fact{display:flex;flex-direction:column;gap:2px;min-width:0}
  .ot .net-fact .k{font-size:11.5px;color:var(--tx-mut);text-transform:uppercase;letter-spacing:.3px}
  .ot .net-fact .v{font-size:13.5px;word-break:break-word;color:var(--tx)}
  .ot .net-fact .v.good{color:var(--ok)} .ot .net-fact .v.bad{color:var(--crit)} .ot .net-fact .v.warn{color:var(--warn)}
  .ot .msect{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:14px 16px 16px;
    display:flex;flex-direction:column;gap:8px;min-width:0;margin-top:14px}
  .ot .msect > h4{margin:0;font-size:11px;letter-spacing:.8px;text-transform:uppercase;color:var(--tx-dim);font-weight:700}
  .ot .msect-lede{margin:0;color:var(--tx-mut);font-size:12.5px;line-height:1.5}
  .ot .msect-body{display:flex;flex-direction:column;gap:10px}
  .ot .msect .set-item{margin:0}
  .ot .net-form-top{margin-top:4px}
  .ot .net-form-top > .set-item:only-child{max-width:460px}
  .ot .formgrid > .set-item > input,.ot .formgrid > .set-item > select{width:100%;box-sizing:border-box}
  .ot .formgrid > .set-item > .says{margin-top:5px}
  .ot .net-go{margin-top:14px}
  .pw-wrap{min-width:0}
  .ot .pw-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:16px}
  .ot .pw-grid > .card{margin:0;min-width:0}
  .ot .ntp-grid{grid-template-columns:repeat(auto-fill,minmax(520px,1fr))}
  .ot .pw-head{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px;font-size:15px}
  .ot .pw-head .tag{margin-left:2px}
  .ot .pw-node .btnrow,.ot .ntp-node .btnrow{margin-top:14px}
  .ot .pw-node .note,.ot .ntp-node .note{margin:10px 0 0}
  .ot .dot{display:inline-block;width:8px;height:8px;border-radius:50%;flex:none;background:var(--tx-mut)}
  .ot .dot.ok{background:var(--ok)} .ot .dot.warn{background:var(--warn)} .ot .dot.bad{background:var(--crit)}
  .ot .ntp-big{margin:4px 0 12px}
  .ot .ntp-off{font-size:26px;font-weight:700;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--tx)}
  /* Automatic certificates (5.30), as otp.css has them */
  .ot .ac-grid{margin-top:4px}
  .ot .ac-grid{grid-template-columns:repeat(auto-fill,minmax(520px,1fr))}
  @media (max-width:620px){.ot .ac-grid{grid-template-columns:1fr}}
  .ot .ac-node .btnrow{margin-top:14px;flex-wrap:wrap}
  .ot .ac-said{display:flex;gap:8px;align-items:baseline;margin-top:10px;font-size:13px;overflow-wrap:anywhere}
  .ot .ac-said .dot{align-self:center}
  .ot .ac-said.bad{color:var(--crit)} .ot .ac-said.good{color:var(--ok)}
  .ot .ac-said .muted{margin-left:auto;white-space:nowrap}
  .ot .ac-manual{margin:12px 0;border-left:4px solid var(--warn)}
  .ot .ac-account{margin-top:12px;overflow-wrap:anywhere}
  .ot > #ac-host > .going{margin:0 0 12px}
  /* System updates (5.34), as otp.css has them */
  .ot .pw-head .pw-break{flex-basis:100%;height:0}
  .ot pre.zlines.ou-log{max-height:420px}
  .ot .notice.warn{border-color:rgba(210,153,34,.45);background:var(--warn-bg)}
  .ot .ou-reboot{margin:0 0 16px}
  .ot .ou-reboot h2{margin:0 0 4px}
  .ot .ou-reboot .btnrow,.ot .ou-reboot > .btn{margin-top:10px}
  #ou-host > .card + .card,#ou-host > .pw-grid + .card,#ou-host > .card + .pw-grid{margin-top:16px}
  #ou-host > .note{margin:0 0 12px}
  #ou-host .set-item{margin:14px 0 4px}
  #ou-host .seg{align-self:flex-start;flex-wrap:wrap;max-width:100%}
  #ou-host .card > .btnrow{margin-top:14px}
  #ou-host .card > .up-bar{margin:6px 0 14px}
  #ou-host .pw-node details.ou-fold{margin-top:12px}
  .ot details.ou-fold > summary{cursor:pointer;font-size:12.5px;color:var(--tx-dim)}
  .ot details.ou-fold > pre{margin-top:6px;max-height:300px}
  .ot .ou-grid{grid-template-columns:repeat(auto-fill,minmax(520px,1fr))}
  @media (max-width:620px){.ot .ou-grid{grid-template-columns:1fr}}
  /* Control - Proxy - Try it (5.35, otp 1.0.169): the way it went */
  .px-out{margin-top:14px;display:flex;flex-direction:column;gap:12px}
  .px-node .px-out{margin-top:0}
  .px-result{border:1px solid var(--line);border-radius:12px;padding:14px 16px;background:var(--panel2)}
  .px-verdict{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px}
  .px-verdict.ok b{color:var(--ok)} .px-verdict.bad b{color:var(--crit)}
  .px-path{display:flex;align-items:center;gap:0;flex-wrap:wrap;row-gap:12px}
  .px-stop{display:flex;flex-direction:column;align-items:center;gap:4px;min-width:150px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--panel);text-align:center}
  .px-stop .px-ic{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:var(--panel2);color:var(--tx-mut)}
  .px-stop.me .px-ic{color:var(--info)}
  .px-stop.good{border-color:color-mix(in srgb,var(--ok) 55%,var(--line))}
  .px-stop.good .px-ic{color:var(--ok)}
  .px-stop.bad{border-color:color-mix(in srgb,var(--crit) 55%,var(--line))}
  .px-stop.bad .px-ic{color:var(--crit)}
  .px-stop b{font-size:12.5px;word-break:break-all}
  .px-link{flex:1;min-width:90px;display:flex;flex-direction:column;align-items:center;gap:4px;padding:0 6px}
  .px-wire{display:block;width:100%;height:3px;border-radius:2px;background:var(--line)}
  .px-link.ok .px-wire{background:var(--ok)}
  .px-link.bad .px-wire{background:repeating-linear-gradient(90deg,var(--crit) 0 8px,transparent 8px 14px)}
  .px-link.going .px-wire{background:repeating-linear-gradient(90deg,var(--info) 0 10px,transparent 10px 20px);background-size:40px 3px;animation:px-run .8s linear infinite}
  @keyframes px-run{from{background-position:0 0}to{background-position:40px 0}}
  .px-lw{color:var(--tx-mut)}
  .px-link.ok .px-lw{color:var(--ok)} .px-link.bad .px-lw{color:var(--crit)}
  .px-steps{display:flex;flex-direction:column;gap:6px}
  .px-step{display:flex;gap:12px;align-items:flex-start;padding:8px 12px;border:1px solid var(--line);border-radius:8px}
  .px-step .px-n{flex:none;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;background:var(--panel2)}
  .px-step.ok .px-n{color:var(--ok);background:var(--ok-bg)}
  .px-step.bad .px-n{color:var(--crit);background:var(--crit-bg)}
  .px-step.off{opacity:.55}
  .px-st{flex:1;min-width:0}
  .px-st .mono{overflow-wrap:anywhere}
  .px-ms{flex:none}
  @media (max-width:700px){.px-link{min-width:100%;padding:4px 0}.px-stop{min-width:100%}}
  .ot > #ac-host > .note{margin:0 0 12px}
  .acme-dns{margin-top:14px}
  .acme-steps{margin:6px 0 12px 18px;padding:0;display:flex;flex-direction:column;gap:4px;color:var(--tx-dim)}
  .acme-dns td{vertical-align:middle}
  .acme-dns .dns-val{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
  .acme-dns .dns-val > span:first-child{overflow-wrap:anywhere;min-width:0;flex:0 1 auto}
  .acme-dns .dns-val > button{flex:none}
  .acme-dns .dns-val > div{flex-basis:100%}
  /* the copy buttons in a column of their own, right after the text (5.34.1):
     one under the other, not wherever a line of text happened to end */
  .acme-dns table.dns-tbl{table-layout:fixed;width:100%;min-width:980px}
  .acme-dns table.dns-tbl th,.acme-dns table.dns-tbl td{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .acme-dns table.dns-tbl td.dns-cell .dns-val{flex-wrap:nowrap}
  .acme-dns table.dns-tbl td.dns-cell .dns-val > span:first-child{overflow:hidden;text-overflow:ellipsis}
  .acme-dns td.dns-copy{padding-left:0;overflow:visible}
  .acme-steps-done{margin:10px 0 0}.acme-steps-done summary{cursor:pointer}
  .acme-steps-done .si-row{display:flex;gap:8px;padding:2px 0}
  .acme-steps-done .si-row > .mono{flex:none;min-width:52px;text-align:right}
  /* the one machine's card, as OTP draws it: a label and its value on one line */
  .ot .ntp-node .net-facts,.ot .pw-node .net-facts{display:flex;flex-direction:column;gap:5px;margin:2px 0 4px}
  .ot .ntp-node .net-fact,.ot .pw-node .net-fact{flex-direction:row;align-items:baseline;gap:12px}
  .ot .ntp-node .net-fact .k,.ot .pw-node .net-fact .k{flex:none;width:150px;font-size:12.5px;text-transform:none;letter-spacing:0}
  .ot .ntp-node .net-fact .v,.ot .pw-node .net-fact .v{font-size:13px;font-weight:600}
  .ot .ntp-set{margin:12px 0 0}
  .ot .reach{display:inline-flex;gap:2px;vertical-align:middle}
  .ot .reach i{display:inline-block;width:7px;height:12px;border-radius:2px;background:var(--panel2);border:1px solid var(--line)}
  .ot .reach i.on{background:var(--ok);border-color:transparent}
  .ot .ntp-own{margin:14px 0 6px}
  .ot.rb-hero{border-left:4px solid var(--line)}
  .ot.rb-hero.good{border-left-color:var(--ok)} .ot.rb-hero.warn{border-left-color:var(--warn)} .ot.rb-hero.bad{border-left-color:var(--crit)}
  .ot .rb-hero-head{display:flex;gap:16px;align-items:center;flex-wrap:wrap}
  .ot .rb-hero-ic{flex:none;width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:var(--panel2);color:var(--tx-dim)}
  .ot.rb-hero.good .rb-hero-ic{color:var(--ok);background:var(--ok-bg)} .ot.rb-hero.warn .rb-hero-ic{color:var(--warn);background:var(--warn-bg)}
  .ot.rb-hero.bad .rb-hero-ic{color:var(--crit);background:var(--crit-bg)}
  .ot .rb-hero-words{flex:1;min-width:260px}
  .ot .rb-hero-words > b{font-size:16px;display:block;margin-bottom:8px;color:var(--tx)}
  .ot .rb-hero-facts{display:flex;flex-wrap:wrap;gap:8px 18px}
  .ot .rb-fact{display:flex;flex-direction:column;gap:2px;font-size:13px}
  .ot .rb-fact .k{font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--tx-mut);font-weight:700}
  .ot .rb-fact.good .v{color:var(--ok)} .ot .rb-fact.bad .v{color:var(--crit);font-weight:700} .ot .rb-fact.warn .v{color:var(--warn)}
  .ot .rb-hero-why{margin-top:8px;overflow-wrap:anywhere;color:var(--crit)}
  .ot .rb-hero-acts{display:flex;gap:8px;flex-wrap:wrap}
  .ot.rb-hero .going{margin-top:14px}
  .ot .full-facts{margin:2px 0 14px}
  .ot .facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin:0 0 16px}
  .ot .facts .fact{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px 14px;min-width:0}
  .ot .facts .fact .k{display:block;color:var(--tx-mut);font-size:11px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;line-height:1.35}
  .ot .facts .fact .v{display:block;font-size:14.5px;font-weight:650;margin-top:4px;color:var(--tx);overflow-wrap:anywhere}
  .ot .sw-box{margin-top:20px;padding-top:16px;border-top:1px solid var(--line)}
  .ot .sw-h{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--tx-dim);margin:16px 0 10px}
  .ot .sw-box > .sw-h:first-child{margin-top:0}
  .ot .about-head{margin:0 0 12px;font-size:16px}
  .ot .up-cli-lede{margin:0 0 8px}
  .ot .sw-ext-h{margin-top:12px}
  @media (max-width:700px){.ot .pw-grid,.ot .ntp-grid{grid-template-columns:minmax(0,1fr)}.ot .ntp-node .net-fact .k,.ot .pw-node .net-fact .k{width:120px}}
  @media (max-width:760px){.ot .tls-tiles{grid-template-columns:repeat(2,minmax(0,1fr))}.ot .tls-rows .arow{flex-direction:column;align-items:flex-start}}
  .ot .cert-tools{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  /* the certificate's download (5.30): a format chosen from cards, then a password */
  .ot .fmt-group{margin:2px 0 14px}
  .ot .fmt-group > h4{margin:0 0 8px;font-size:11px;letter-spacing:.8px;text-transform:uppercase;color:var(--tx-dim);font-weight:700}
  .ot .fmt-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:8px}
  .ot .fmt-card{display:flex;gap:10px;align-items:flex-start;text-align:left;background:var(--panel2);border:1px solid var(--line);
    border-radius:10px;padding:10px 12px;cursor:pointer;color:var(--tx);font:inherit;min-width:0}
  .ot .fmt-card:hover{border-color:var(--tx-mut)}
  .ot .fmt-card.on{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset;background:var(--info-bg)}
  .ot .fmt-card .fmt-ic{flex:none;width:30px;height:30px;border-radius:8px;display:grid;place-items:center;
    background:var(--panel);font-size:15px}
  .ot .fmt-card.keyed .fmt-ic{background:var(--warn-bg)}
  .ot .fmt-card .fmt-t{display:flex;flex-direction:column;gap:2px;min-width:0}
  .ot .fmt-card b{font-size:13.5px;font-weight:650}
  .ot .fmt-card .fmt-x{font:11px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--tx-mut)}
  .ot .fmt-card .fmt-s{font-size:12px;color:var(--tx-mut);line-height:1.4}
  .ot .fmt-key{border-left:4px solid var(--warn);background:var(--warn-bg);border-radius:10px;padding:12px 14px;margin:4px 0 12px}
  .ot .fmt-key p{margin:0 0 10px;font-size:12.5px;line-height:1.5}
  .ot .fmt-pw{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px}
  .ot .fmt-pw input{width:100%;box-sizing:border-box}
  .ot .fmt-meter{height:4px;border-radius:2px;background:var(--line);margin:8px 0 4px;overflow:hidden;max-width:460px}
  .ot .fmt-key > .says{font-size:12px;color:var(--tx-mut);margin-bottom:6px}
  .ot .fmt-meter i{display:block;height:100%;width:0;background:var(--crit);transition:width .15s}
  /* the download (5.33): all of it at once, no scrolling - four formats a
     line, the password and its options in one band */
  #zmodal .box.cert-dl{width:min(1180px,100%)}
  .ot.cert-dl .fmt-group{margin:0 0 10px}
  .ot.cert-dl .fmt-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
  .ot.cert-dl .fmt-card{padding:8px 10px;gap:8px}
  .ot.cert-dl .fmt-card .fmt-ic{width:26px;height:26px}
  .ot.cert-dl .fmt-card .fmt-s{font-size:11.5px;line-height:1.3}
  .ot.cert-dl .fmt-key{padding:10px 14px;margin:2px 0 4px}
  .ot.cert-dl .fmt-key p{margin:0 0 8px}
  .ot.cert-dl .fmt-pw{grid-template-columns:repeat(2,minmax(0,1fr)) minmax(0,1.2fr);align-items:end}
  .ot.cert-dl .fmt-meter{max-width:none;margin:6px 0 2px}
  .ot.cert-dl .fmt-opts{display:flex;align-items:center;gap:6px;flex-direction:column;align-self:stretch;justify-content:flex-end}
  .ot.cert-dl .fmt-opts .zrow{margin:0;padding:0;border:0}
  @media (max-width:900px){.ot.cert-dl .fmt-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
    .ot.cert-dl .fmt-pw{grid-template-columns:1fr}}
  .ot .cert-tools > .btn{width:100%;justify-content:center;min-width:0}
  .ot .cert-icons{grid-column:1/-1;display:flex;justify-content:flex-end;gap:6px}
  .ot .cert-icons:empty{display:none}
  .ot .cert-for{width:100%;font-size:12px;color:var(--tx-mut);line-height:1.4}
  .ot .cert-tools > .btn.danger-soft{color:var(--crit)}
  .ot .cert-tools > .btn.danger-soft:hover{border-color:rgba(248,81,73,.5);background:var(--crit-bg)}
  .ot .cert-paste{min-height:330px;font:12.5px/1.55 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;resize:vertical;padding:12px 14px}
  .ot .cert-paste::placeholder{color:var(--tx-mut);opacity:.75;white-space:pre}
  .ot .cert-prog{display:flex;flex-direction:column;gap:5px;padding:9px 11px;border:1px solid rgba(88,166,255,.35);border-radius:9px;background:rgba(88,166,255,.06)}
  .ot .cert-prog-h{display:flex;justify-content:space-between;gap:10px;font-size:12.5px;font-weight:600;color:var(--tx)}
  .ot .cert-prog-h b{color:var(--info);font-variant-numeric:tabular-nums}
  .ot .cert-prog-bar{height:7px;border-radius:4px;background:var(--line);overflow:hidden}
  .ot .cert-prog-bar span{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,var(--info),#7cc4ff);transition:width .8s ease;position:relative}
  .ot .cert-prog-bar span::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.25),transparent);animation:certshine 1.6s linear infinite}
  @keyframes certshine{from{transform:translateX(-100%)}to{transform:translateX(100%)}}
  .ot .cert-prog-s{font-size:11.5px;color:var(--tx-mut)}
  .ot .cert-tools > .btn{white-space:normal;text-align:center;line-height:1.25}
  .ot .cert-h{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:10px;min-height:76px}
  .ot .cert-h > .tag{justify-self:end;white-space:nowrap}
  .ot .cert-for{min-height:34px}
  .ot .fw-acc{display:grid;gap:10px;margin-top:6px}
  .ot .fw-acc-row{display:grid;grid-template-columns:minmax(200px,1fr) minmax(0,1.6fr);gap:14px;align-items:start; background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:12px 14px}
  .ot .fw-acc-t b{display:block}
  .ot .fw-acc-c{display:flex;flex-direction:column;gap:8px;align-items:flex-start}
  .ot .fw-nets{width:100%;min-height:52px;resize:vertical}
  .ot .fw-acc-foot{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin-top:12px}
  .ot .fw-always{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
  .ot .fw-top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;flex-wrap:wrap}
  .ot .fw-master{display:inline-flex;gap:10px;align-items:center;cursor:pointer;font-weight:600; background:var(--panel2);border:1px solid var(--line);border-radius:999px;padding:7px 14px 7px 8px}
  .ot .fw-flow{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:16px 0 6px;font-size:13px}
  .ot .fw-flow.off{opacity:.45}
  .ot .fw-step{border:1px solid var(--line);border-radius:8px;padding:4px 10px;background:var(--panel2);white-space:nowrap}
  .ot .fw-step.mine{border-color:rgba(163,113,247,.5);background:var(--violet-bg)}
  .ot .fw-step.auto{border-color:rgba(63,185,80,.45);background:var(--ok-bg)}
  .ot .fw-step.rest{color:var(--tx-dim)}
  .ot .fw-arrow{color:var(--tx-mut)}
  .ot .fw-h{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-top:20px}
  .ot .fw-h h3{margin:0;font-size:16px}
  .ot .fw-table td.acts{white-space:nowrap;text-align:right}
  .ot .fw-table tr.dim td{opacity:.5}
  .ot .fam{display:inline-block;font-size:11px;font-weight:700;border-radius:6px;padding:1px 6px;white-space:nowrap}
  .ot .fam.fam4{background:var(--info-bg);color:var(--info)}
  .ot .fam.fam6{background:var(--violet-bg);color:var(--violet)}
  .ot .fam.famx{background:var(--panel2);color:var(--tx-dim);border:1px solid var(--line)}
  .ot .fw-auto{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px;margin-top:8px}
  .ot .fw-auto-card{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:12px 14px; display:flex;flex-direction:column;gap:10px}
  .ot .fw-auto-card.off{opacity:.55}
  .ot .fw-auto-top{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:start}
  .ot .fw-auto-rules{display:flex;flex-direction:column;gap:5px}
  .ot .fw-rl{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:13px}
  .ot .fw-what{font-size:12px}
  .ot .fw-from{color:var(--tx-dim)}
  .ot .fw-from code{color:var(--tx)}
  .ot .fw-other{margin-top:20px}
  .ot .fw-other summary{cursor:pointer;font-weight:600}
  .ot .fw-other .seg{margin:10px 0 8px}
  .ot .fw-pre{background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:10px 12px;max-height:340px; overflow:auto;font-size:12px;white-space:pre;margin:0}
  .ot .note.bad{background:var(--crit-bg);border-radius:10px;padding:10px 12px;display:flex;gap:10px;flex-wrap:wrap;align-items:center}
  .ot .note.warn{background:var(--warn-bg);border-radius:10px;padding:10px 12px}
  @media (max-width:760px){.ot .fw-acc-row{grid-template-columns:1fr}}
  .ot .lb-f .seg{align-self:flex-start}
  .ot .lb-facts .cchip b{color:var(--tx);margin-right:2px}
  .ot .note.good{background:var(--ok-bg);border-radius:10px;padding:10px 12px}
  .ot .vip-return .seg{flex-wrap:wrap}
  .ot .sure-strip{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:flex-end;width:100%; background:var(--crit-bg);border:1px solid rgba(248,81,73,.35);border-radius:10px;padding:8px 10px}
  .ot .sure-q{font-weight:600;color:var(--crit);margin-right:auto}
  .ot .up-bar{margin:6px 0 10px}
  .ot .up-bar.wide{margin:4px 0 14px}
  .ot td.up-how{min-width:180px;width:26%}
  .ot td.up-how .up-bar{margin:0}
  .ot .up-bar .says{font-size:12px;color:var(--tx-dim);margin-top:4px;overflow:hidden;text-overflow:ellipsis}
  .ot .up-bar.good .bar span{background:var(--ok)}
  .ot .up-bar.bad .bar span{background:var(--crit)}
  .ot .fw-pre .fw-line.fw-ours{color:var(--info);font-weight:600}
  .ot table.up-plan-table{table-layout:fixed;width:100%}
  .ot table.up-plan-table th:nth-child(1),.ot table.up-plan-table td:nth-child(1){width:12%}
  .ot table.up-plan-table th:nth-child(2),.ot table.up-plan-table td:nth-child(2){width:16%}
  .ot table.up-plan-table th:nth-child(3),.ot table.up-plan-table td:nth-child(3){width:24%}
  .ot table.up-plan-table th:nth-child(4),.ot table.up-plan-table td:nth-child(4){width:38%}
  .ot table.up-plan-table th:nth-child(5),.ot table.up-plan-table td:nth-child(5){width:10%}
  .ot table.up-plan-table td{vertical-align:top;overflow-wrap:anywhere}
  .ot table.up-plan-table td.up-how{min-width:0;width:24%;padding-right:24px}
  .ot table.up-plan-table td.up-how .says{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  /* zigmon's side of it: the popup under the PIN box (100), the fields, the
     tables, and the room between a drop zone and its buttons */
  #zmodal{z-index:95}
  #zmodal .box{background:linear-gradient(160deg,#1b2230 0%,#141922 60%,#11151d 100%);border-color:#2b3444;
    animation:rise .2s cubic-bezier(.2,.9,.3,1)}
  .ot input[type=text],.ot input[type=password],.ot textarea{font:inherit;font-size:13.5px;background:var(--panel2);color:var(--tx);
    border:1px solid var(--line);border-radius:9px;padding:8px 11px;width:100%;max-width:100%}
  .ot select{width:100%}
  .ot textarea{resize:vertical}
  .ot .mono,.ot code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
  .ot input:focus,.ot select:focus,.ot textarea:focus{outline:none;border-color:var(--info);box-shadow:0 0 0 3px rgba(88,166,255,.18)}
  .ot input:disabled,.ot textarea:disabled,.ot select:disabled{opacity:.55}
  .ot .arow-c input[type=text]{min-width:240px}
  .ot .note.reason{color:var(--tx-dim)}
  .ot .says{font-size:12px;color:var(--tx-mut);margin-top:2px}
  .ot .said{font-size:13px;min-height:1em;margin-top:6px} .ot .said.bad{color:var(--crit)}
  .ot .set-item{margin-bottom:10px}
  .ot .muted{color:var(--tx-mut)} .ot .dim{opacity:.55}
  .ot .drop{cursor:pointer;text-align:center}
  .ot .drop:focus{outline:none;border-color:var(--accent)}
  .ot .drop + *, .ot #up-drop-slot + *, .ot #full-drop-slot{margin-top:14px}
  .ot .btnrow{margin-top:14px}
  .ot table.plain{width:100%;border-collapse:collapse;font-size:13px}
  .ot table.plain th{text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--tx-mut);font-weight:600;
    padding:6px 8px;border-bottom:1px solid var(--line)}
  .ot table.plain td{padding:8px;border-bottom:1px solid var(--line);vertical-align:middle}
  .ot table.plain td.acts{white-space:nowrap;text-align:right}
  .ot table.plain td.acts .btn{margin-left:4px}
  .ot table.plain td.num{text-align:right;font-variant-numeric:tabular-nums}
  .ot .zfold{margin-top:12px} .ot .zfold summary{cursor:pointer;color:var(--info);font-size:13px}
  .ot a.fgo{color:var(--info);text-decoration:none} .ot a.fgo:hover{text-decoration:underline}
  .ot .dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--tx-mut);flex:0 0 auto}
  .ot .dot.ok{background:var(--ok)} .ot .dot.warn{background:var(--warn)} .ot .dot.crit{background:var(--crit)}
  .ot .fw-top h2{margin:0}
  .ot .tls-h{margin-top:18px} .ot .tls-h:first-child{margin-top:4px}
  .ot .tls-tile-top{flex-wrap:wrap}
  .ot .tls-tile-top .tag{padding:1px 6px}
  .ot .tls-used summary{margin-bottom:2px}
  .ot .cert-grid > .note{grid-column:1/-1;margin:0}
  .ot .cert-follow{border-top:1px solid var(--line);padding-top:8px}
  .ot .cert-follow .note{margin:6px 0 0}
</style>
</head>
<body class="app-shell">
<script>
// The page is drawn in its final shape from the first frame: the whole-width
// application layout, and Settings' own when that is where it opens. These
// were put on by the script at the end of the page, so a reload showed the
// old narrow page for half a second first and then jumped.
(function () {
  if (/^#control\b/.test(location.hash || '')) document.body.classList.add('ctl-shell');
  if (window.innerWidth <= 980) document.documentElement.classList.remove('app-shell-root');
  // the tab the address names is the first one seen, not Overview for a moment
  // before it (a fail-safe shows the page anyway should the script stop)
  if (location.hash && !/^#overview\b/.test(location.hash)) {
    document.documentElement.classList.add('booting');
    setTimeout(function () { document.documentElement.classList.remove('booting'); }, 3000);
  }
})();
</script>
