    svg += '<path d="' + d + '" fill="none" stroke="' + esc(s.color) + '" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>';
    if (count < 60) rows.forEach(function (r) {
      var v = r['s' + n];
