    + '<button class="creset" type="button" title="Back to the whole range"' + (full ? ' hidden' : '')
      + '>' + iconMarkup('reset', 10) + '<span>reset</span></button>'
    + '<span class="chint">drag to pan · wheel to zoom · double-click to reset</span>'
    + '<div class="tip"></div>';
