    var perPixel = (dragFrom.t1 - dragFrom.t0) / Math.max(1, plotWidth);
    var shift = -(e.clientX - dragFrom.x) * perPixel;
    if (Math.abs(e.clientX - dragFrom.x) > 2) state.zoomed = true;
    applyView(id, dragFrom.t0 + shift, dragFrom.t1 + shift);
