}
function legend(host, series) {
  host.innerHTML = '';
  series.forEach(function (s) {
    var item = el('span');
    item.innerHTML = '<span class="sw" style="background:' + esc(s.color) + '"></span>' + esc(s.name)
      + (s.ref ? objMarkHtml(s.ref, s.name) : '');
