// ---- the addresses that may not talk to this --------------------------------
// What each address has on its account. It is counted whether or not anybody
// is looking, and was nowhere to be seen: letting somebody back in while the
// weight against them still stood meant the next thing they did put them
// straight back on the list, and there was no way to tell why.
// A length of time in the words the blocked list uses: minutes up to an
// hour, hours up to a day, days after that.
function blockSpan(minutes) {
  var m = Math.max(0, Math.round(minutes || 0));
  if (m < 60) return m + ' min';
  if (m < 1440) return (m % 60 ? (m / 60).toFixed(1).replace(/\.0$/, '') : m / 60) + ' h';
  return (m % 1440 ? (m / 1440).toFixed(1).replace(/\.0$/, '') : m / 1440) + ' d';
}
function watchBar(one) {
  // How near this address is to being kept out, and to what: the score it has
  // against the bar that earns a block, and the step of the ladder waiting for
  // it. Worked out by the daemon from the Settings that decide it, so nobody
  // has to hold the ladder in their head while watching a list fill up.
  var bar = Math.max(1, one.bar || 1);
  var part = Math.max(0, Math.min(1, (one.score || 0) / bar));
  var box = el('div', 'wbar' + (part >= 0.85 ? ' close' : (part >= 0.6 ? ' soon' : '')));
  var track = el('div', 'wbar-track');
  var fill = el('i', 'wbar-fill');
  fill.style.width = Math.round(part * 100) + '%';
  track.appendChild(fill);
  box.appendChild(track);
  var next = one.next || {};
  var said = one.score + ' of ' + bar + ' · ' + Math.round(part * 100) + '%';
  if (next.words) {
    said += ' · ' + (next.forever ? 'then kept out ' : 'then ') + next.words;
  } else if (next.forever) {
    said += ' · then for good';
  }
  box.appendChild(el('span', 'wbar-words', said));
  box.title = 'What this address has on its account against what earns a block, and what it would '
    + 'get if it went over: Settings → Keeping addresses out sets the bar, the ladder and how '
    + 'long each step lasts. Nothing here keeps anybody out by itself.';
  return box;
}
function drawWatchRow(one, into) {
