  var eye = el('span', 'appr-icon', one.spared ? '🕊️' : '👁️');
  explain(eye, one.spared
    ? 'Let through whatever it does: this address is one of the house’s own, or is under '
      + 'Never kept out. What it is doing is still counted here, and nothing will come of it.'
    : 'Watched, not kept out: what this address has done is being counted, and if it goes over the '
      + 'bar it goes on the list below by itself. A hand always beats the counting.');
  slot(eye);
  if (one.from_proxy) {
    var globe = el('span', 'appr-icon', '🌐');
