    if (one.from_ntfy) {
      var bell = el('span', 'appr-icon', '🔔');
      explain(bell, 'And of the notification server’s logs in particular — its own log, '
        + 'its ban feed, or the nginx logs for its name.');
      slot(bell);
    } else {
      slot(null);
    }
  } else {
    var home = el('span', 'appr-icon', '🏠');
    explain(home, 'Seen here, by this machine itself — a press, a read, a lock — rather '
      + 'than read out of a log on the server in front.');
    slot(home);
    slot(null);
  }
  // the slot the list below keeps for the router: nothing is on the router
  // for an address that is not kept out, and the column still lines up
  slot(null);
  if (one.from_feed || (one.on_feeds || []).length) {
    var book = el('span', 'appr-icon', '📕');
    explain(book, 'A list somebody else keeps — '
      + ((one.on_feeds || []).join(', ') || one.from_feed)
      + ' — already has this address on it. Nothing is kept out for being on a list alone, but '
      + 'the first thing it does here weighs as much as several.');
    slot(book);
  } else {
    slot(null);
  }
  if (one.from_ids) {
    var dish = el('span', 'appr-icon', '📡');
