    lists.textContent = '📕 on ' + one.on_feeds.length + ' lists: ' + one.on_feeds.join(', ');
    what.appendChild(lists);
  }
  if (one.intel) {
    var said = el('span', 'muted small');
    said.style.display = 'block';
    said.textContent = '🔎 Shodan: ' + one.intel;
    what.appendChild(said);
  }
  // watched rather than kept out, and worth asking about for the same reason:
  // this is the list where somebody decides whether to keep it out
  var ask = intelButtons(one.ip, true);
  if (ask) what.appendChild(ask);
  what.appendChild(el('span', 'muted small', one.kinds.map(function (k) {
    return k.n + '× ' + k.words;
  }).join(', ') + ' · ' + (one.tries || 0) + ' thing(s) in the window'
