function idsWords(ids, where) {
  if (!ids || !(ids.sid || ids.rule || ids.host || (ids.links || []).length)) return null;
  var said = el('div', 'muted small');
  var line = [];
  if (ids.sid) line.push('rule ' + ids.sid + (ids.rev ? '.' + ids.rev : ''));
  if (ids.confidence) line.push(ids.confidence.toLowerCase() + ' confidence');
  if (ids.signature_severity) line.push(ids.signature_severity.toLowerCase());
  if (ids.attack_target) line.push('at the ' + ids.attack_target.toLowerCase());
  if (ids.proto) line.push('over ' + ids.proto);
  if (line.length) said.appendChild(document.createTextNode('\ud83d\udce1 ' + line.join(' \u00b7 ')));
  if (ids.rule && ids.rule.msg) {
    var msg = el('div');
    msg.style.wordBreak = 'break-word';
    msg.textContent = '\u201c' + ids.rule.msg + '\u201d'
      + (ids.rule.classtype ? '   \u2014 ' + ids.rule.classtype.replace(/-/g, ' ') : '');
    said.appendChild(msg);
  }
  if (ids.rule && (ids.rule.looks_for || []).length) {
    var forWhat = el('div');
    forWhat.style.wordBreak = 'break-all';
    forWhat.textContent = 'it looks for: '
      + ids.rule.looks_for.map(function (x) { return '\u201c' + x + '\u201d'; }).join(', ');
    explain(forWhat, 'The strings this rule matches on, taken from the rule itself on the server in '
      + 'front. This is the answer to \u201cwhy me\u201d: it fired because one of these was in '
      + 'what arrived.');
    said.appendChild(forWhat);
  }
  if (ids.host || ids.url) {
    var asked = el('div');
    asked.style.wordBreak = 'break-all';
    asked.textContent = (ids.host || '') + (ids.url || '')
      + (ids.status ? '  \u2014 answered ' + ids.status : '')
      + (ids.agent ? '   as ' + ids.agent : '');
    said.appendChild(asked);
  }
  (ids.links || []).forEach(function (link) {
    var row = el('div');
    var a = el('a', 'cve');
    a.href = link.where;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.textContent = link.what;
    explain(a, 'What this rule is about, on somebody else\u2019s site. Opens in a new tab.');
    row.appendChild(a);
    said.appendChild(row);
  });
  return said;
}

// A fold for the ones somebody else's list already knew. Shut to begin with,
// because there will be a great many of them in time and a long list of them
// buries the handful that are here for what they did here. Inside: the same
// rows, a box to search them, and pages.
var FOLDS = {listed: {open: false, text: '', cc: '', page: 0, per: 25},
             ids: {open: false, text: '', cc: '', page: 0, per: 25},
             system: {open: false, text: '', cc: '', page: 0, per: 25},
             // the ones that are not kept out yet, and are on their way
             watch: {open: true, text: '', cc: '', page: 0, per: 25}};
var FOLDED_OPEN = {};      // folded subnets somebody has opened, by subnet
// an address as the lists show it, with its mark on the same line - the
// column the address sits in stacks its lines, and the mark is not one
function addrLine(ip) {
  var line = el('span', 'appr-ipline');
  line.appendChild(el('span', 'appr-link', ip));
  line.appendChild(objMark('address:' + ip, ip));
  return line;
}
// ---- filtering by country, with the flags -------------------------------------
// Beside every text filter over rows that carry a country: the countries
// actually in those rows, each with its own flag and how many rows are its.
// The text box finds a country too - if you know the two letters. This
// answers the other question, which is which countries are even in there.
function countryPick(rows, getCc, chosen, onPick) {
  var wrap = el('span', 'cpick');
  var btn = el('button', 'btn cmd small cpick-btn');
  btn.type = 'button';
  var pop = el('div', 'cpick-pop');
  pop.hidden = true;
  var counts = {}, order = [];
  (rows || []).forEach(function (r) {
    var cc = ccOf({country: getCc(r)});           // 'ZZ' is every address no list could place
    if (counts[cc] === undefined) { counts[cc] = 0; order.push(cc); }
    counts[cc]++;
  });
  order.sort(function (a, b) { return counts[b] - counts[a] || a.localeCompare(b); });
  var name = function (cc) {
    return cc === 'ZZ' ? 'No country known' : (COUNTRY_NAMES[cc] || cc);
  };
  var paintButton = function () {
    btn.innerHTML = '';
    if (!chosen) {
      btn.appendChild(el('span', '', '\ud83c\udf10'));
      btn.appendChild(el('span', '', 'Every country'));
    } else {
      btn.appendChild(countryBadge(chosen === 'ZZ' ? '' : chosen));
      btn.appendChild(el('span', '', name(chosen)));
    }
    btn.appendChild(el('span', 'cpick-caret', '\u25be'));
    // the page's own words rather than the browser's box, which is drawn over
    // everything - including this list, whose first two lines it sat on
    explain(btn, 'Show only the addresses of one country. The flag comes from the country list '
      + 'fetched under Settings; nothing is judged by it.');
  };
  var away = function (e) {
    if (wrap.contains(e.target)) return;
    shut();
  };
  var shut = function () {
    pop.hidden = true;
    HOLD.select = 0;                   // the page may repaint again
    document.removeEventListener('mousedown', away, true);
  };
  var line = function (cc, label, n) {
    var one = el('button', 'cpick-one' + ((chosen || '') === cc ? ' on' : ''));
    one.type = 'button';
    if (cc === '') one.appendChild(el('span', '', '\ud83c\udf10'));
    else one.appendChild(countryBadge(cc === 'ZZ' ? '' : cc));
    one.appendChild(el('span', '', label));
    one.appendChild(el('span', 'cpick-n', String(n)));
    one.onclick = function () {
      shut();
      onPick(cc);
    };
    pop.appendChild(one);
  };
  paintButton();
  btn.onclick = function () {
    if (!pop.hidden) { shut(); return; }
    hideSettingHelp();                 // nothing of the page's own is left over the list either
    // a hand on the page, the same as an open dropdown: this list lives in a
    // card that repaints every second, and a block landing while it was open
    // threw it away under the pointer, mid-choice. The stamp has a way out of
    // its own, so a list left open cannot hold the page for ever.
    HOLD.select = Date.now();
    pop.innerHTML = '';
    line('', 'Every country', (rows || []).length);
    order.forEach(function (cc) { line(cc, name(cc), counts[cc]); });
    pop.hidden = false;
    document.addEventListener('mousedown', away, true);
  };
  wrap.appendChild(btn);
  wrap.appendChild(pop);
  return wrap;
}
// Which country a row belongs to, for filtering: anything that is not two
