// are the same bucket - and they were not, so picking the one with fourteen
// rows in it showed none of them.
function ccOf(one) {
  var his = String((one && one.country) || '').trim().toUpperCase();
  return (/^[A-Z]{2}$/.test(his) && his !== 'ZZ') ? his : 'ZZ';
