      var targets = [(st.plugs || []).map(function (p) { return p.name + (p.monitor_only ? '!' : '') + (p.online ? '' : '?'); }), st.switch_targets, st.scenes, st.sequences];
      // The shape of the card, not its figures: the watts move on nearly every
