      if (showing('#ptrig-card')) if (!PTRIG.dirty && sigChanged('ptrig', [st.presence_triggers, st.people, st.plugs && st.plugs.length, unlocked, (st.editor_groups || {}).ptrig])) { PTRIG.rows = null; renderPtrig(st); }
