  if (d.source === 'group') return 'sgroup';
  if (d.source === 'plug') return plugRoleKind(d.name);
  var v = d.values || {};
  if ('current_heating_setpoint' in v || 'occupied_heating_setpoint' in v || 'pi_heating_demand' in v) return 'valve';
  if (d.has_action) {
