    var sig = JSON.stringify([d.name, d.alias, d.topic_name, d.description, gatewayFirmware(d),
                              d.vendor, d.model, d.source, d.kind, d.id, d.level, d.reasons,
                              d.battery, d.linkquality, d.last_seen, d.first_seen, unlocked]);
    var had = kept[d.id];
