var FOCUS_ROW = '.rule-pack, .scene-row, .person-row, .tap-row, .bind-row, .ptrig-row, .msg-card, .smscmd-row, '
  + '.sgroup-row, .agroup-row, .seq-row, .sched-row, .heatcard, tr, .dev, .card';
function rowByModel(root, test) {
