function searchIndex() {
  var st = STATE.status || {}, out = [];
  var panel = function (id) { return function () { return $(id); }; };
  var byId = function (cardId, id) { return function () { var c = $(cardId); return c && rowByModel(c, function (m) { return m.id === id; }); }; };
  var byName = function (rootId, name) { return function () { var c = $(rootId); return c && rowByName(c, name); }; };
  Array.prototype.forEach.call(document.querySelectorAll('.tabs button[data-tab]'), function (b) {
    out.push({icon: '▸', text: b.textContent.trim(), what: 'tab', go: function () { goTab(b.dataset.tab); }});
  });
  (st.devices || []).forEach(function (d) {
    out.push({icon: deviceIcon(d), text: d.name, what: 'device', more: [d.vendor, d.model, d.id, d.alias].join(' '),
              go: function () { goTab('devices', byName('tab-devices', d.name)); }});
  });
  (st.plugs || []).forEach(function (p) {
    out.push({icon: deviceIcon(Object.assign({source: 'plug'}, p)), text: p.name, what: 'socket',
              go: function () { goTab('plugs', byName('tab-plugs', p.name)); }});
  });
  ((st.heating || {}).rooms || []).forEach(function (r) {
    out.push({icon: ICON.heat, text: r.name, what: 'room', go: function () { goTab('heating', byName('tab-heating', r.name)); }});
  });
  (st.scenes || []).forEach(function (x) {
    out.push({icon: ICON.scene, text: x.name, what: 'scene', go: function () { goControl('auto-scenes', byId('scenes-card', x.id)); }});
  });
  (st.sequences || []).forEach(function (x) {
    out.push({icon: ICON.seq, text: x.name, what: 'sequence', go: function () { goControl('auto-scenes', byId('sequences-card', x.id)); }});
  });
  (st.rules || []).forEach(function (r) {
    out.push({icon: '⚡', text: (nameFor(st, r.device) || r.device) + ' ' + r.key + ' ' + r.op + ' ' + r.value + ' → ' + targetLabel(st, r.plug),
              what: 'rule', go: function () { goControl('auto-rules', byId('rules-card', r.id)); }});
  });
  (st.bindings || []).forEach(function (b) {
    out.push({icon: ICON.button, text: (nameFor(st, b.device) || b.device) + ' ' + (b.action || '*') + ' → ' + targetLabel(st, b.plug),
              what: 'binding', go: function () {
