                  var c = $('bindings-card');
                  return c && rowByModel(c, function (m) { return m.device === b.device && (m.action || '') === (b.action || '') && m.plug === b.plug; });
                });
              }});
  });
  (st.messages || []).forEach(function (m) {
    out.push({icon: ICON.bell, text: m.name, what: 'alert', more: m.text, go: function () { goControl('msg-alerts', byId('messages-card', m.id)); }});
  });
  ((st.sms || {}).commands_list || st.sms_commands || []).forEach(function (c) {
    out.push({icon: '✉️', text: c.phrase, what: 'SMS command', go: function () { goControl('msg-sms', byId('smscmd-card', c.id)); }});
  });
  (st.people || []).forEach(function (x) {
    out.push({icon: ICON.person, text: x.name, what: 'person', go: function () { goControl('presence', byId('people-card', x.id)); }});
  });
  (st.taps || []).forEach(function (t) {
    out.push({icon: '🔗', text: t.name, what: 'one-tap link', go: function () { goControl('msg-taps', byId('taps-card', t.id)); }});
  });
  // every card on every tab, and everything in Control
  Array.prototype.forEach.call(document.querySelectorAll('section.panel:not(#tab-control) .card'), function (card) {
    var h = card.querySelector(':scope > h2'), pnl = card.closest('section.panel');
    if (!h || !pnl) return;
    out.push({icon: '▢', text: (h.childNodes[0] || h).textContent.trim(), what: 'card', more: (card.querySelector('.card-lede') || {}).textContent || '',
              where: TAB_NAMES[pnl.id.slice(4)] || '', go: function () { goTab(pnl.id.slice(4), function () { return card; }); }});
  });
  controlIndex().forEach(function (it) {
    out.push({icon: it.what === 'setting' ? '⚙️' : (it.what === 'section' ? '▸' : '▢'), text: it.text, what: it.what,
              more: it.more, key: it.key, where: 'Settings → ' + (CONTROL_SECTIONS[it.sec] || [''])[0],
              go: function () {
                goControl(it.sec, it.what === 'setting'
                  ? function () { var k = settingsQuery('[data-k="' + it.key + '"]'); return k ? (k.closest('.set-item') || k) : null; }
                  : (it.node ? function () { return it.node; } : function () { return $('ctl-head'); }));
              }});
  });
  var seen = {};
  return out.filter(function (it) {
    var k = it.what + '|' + it.text + '|' + (it.where || '');
    if (seen[k]) return false;
    seen[k] = true;
    return true;
  });
}
function searchMatch(items, query) {
  var words = String(query || '').toLowerCase().split(/\s+/).filter(function (w) { return w; });
  if (!words.length) return items;
  var scored = [];
  items.forEach(function (it) {
    var name = String(it.text || '').toLowerCase();
    var hay = name + ' ' + String(it.more || '').toLowerCase() + ' ' + String(it.key || '').toLowerCase()
      + ' ' + String(it.what || '').toLowerCase() + ' ' + String(it.where || '').toLowerCase();
    if (!words.every(function (w) { return hay.indexOf(w) >= 0; })) return;
    // the name itself first, then its start, then anywhere in what it says
    var q = words.join(' ');
    var score = name === q ? 0 : (name.indexOf(q) === 0 ? 1 : (name.indexOf(q) >= 0 ? 2 : 3));
    scored.push([score, it]);
  });
  scored.sort(function (a, b) { return a[0] - b[0]; });
