}
// scroll a named card into view and let it glow for a moment
function highlightCard(name) {
  var card = Array.prototype.filter.call(document.querySelectorAll('.card h3, .card h2'), function (h) {
    return h.textContent.trim() === name || ((h.childNodes[0] || {}).textContent || '').trim() === name;
  })[0];
  card = card && card.closest('.card');
  if (!card) return;
  card.scrollIntoView({block: 'center', behavior: 'smooth'});
