    else if (e.key === 'ArrowUp') { e.preventDefault(); FIND.at = Math.max(0, FIND.at - 1); paintFind(input.value, true); }
    else if (e.key === 'Enter') { e.preventDefault(); if (rows[FIND.at]) rows[FIND.at].click(); }
  };
