function talosTerms(feed, failed, held) {
  var wrap = el('div', 'feedterms');
  var accepted = !!(+(((STATE.status || {}).runtime_config || {}).feed_talos_accept || {}).value);
  var go = cmdButton(accepted ? 'Accept again and fetch' : 'Accept the terms and fetch', 'check', 'small'
    + (accepted || held ? '' : ' primary'));
  go.classList.remove('needs-unlock');
  go.title = 'Says the terms are accepted, keeps that with the settings, and fetches the list now. '
    + 'From then on it is fetched by itself, like every other list.';
  go.onclick = function () {
    if (go.disabled) return;
    go.disabled = true;
    setTimeout(function () { go.disabled = false; }, 8000);
    withPin('Accept the terms for the Talos list',
      'Cisco\u2019s terms for the Testing IP Block List, at snort.org. Accepting them here is the same '
      + 'as pressing Accept on their page: the daemon then fetches the list and keeps it up to date '
      + 'by itself. Nothing is sent anywhere but snort.org, and nothing else on this page changes.',
      function (pin) {
