          tick(true);
          if (!r.ok) throw new Error(r.message || 'snort.org would not hand it over');
          return (r.turned_on ? 'switched on and fetched: ' : 'fetched: ') + (r.message || 'done');
          // (a "wait" from snort.org is not a refusal: it comes back as the
          // message above, and the list is left alone for a few hours)
        });
      });
  };
  wrap.appendChild(go);
  var read = el('a', 'feedterms-link', 'Read the terms at snort.org \u2197');
  read.href = 'https://www.snort.org/downloads/ip-block-list/terms';
  read.target = '_blank'; read.rel = 'noopener noreferrer';
  explain(read, 'The terms themselves. If snort.org will not take the button above from a program, '
    + 'accept them here in the browser, keep the file on this machine \u2014 a daily '
    + 'wget from cron will do \u2014 and put its path in "Where the Talos list comes from" below.');
  wrap.appendChild(read);
  if (accepted && !failed) {
