      // and an n. The two lists disagreeing put a stray brace round six of
      // these and a literal \n in nine more.
      var whole = String(b[2]).replace(/\\n/g, '\n');
      if (!/^Whole/.test(String(b[5] || ''))) whole = '{' + whole + '}';
      return [b[0], b[1] + (b[4] ? ' \u2014 e.g. ' + String(b[4]).replace(/\\n/g, ' / ') : ''), undefined,
