// Typing "{" (or Ctrl+Space anywhere) lists every fact with what it means and
// an example value; typing a device name and "." lists that device's own keys
// with its current reading. Up/Down move, Enter or Tab take, Esc closes.
var COMPLETE = { box: null, pop: null, items: [], sel: 0, start: 0, opened: 0, blurTimer: null };
function closeCompleter() { if (COMPLETE.pop) { COMPLETE.pop.remove(); COMPLETE.pop = null; } COMPLETE.box = null; COMPLETE.items = []; }
// Leaving the box shuts the list a moment later, so that a click on the list
// itself is taken first. A button that opens the list - Examples, Facts -
// blurs the box on the way to being pressed, so that timer was still on its
// way when the button re-opened the list, and it shut it again a breath
// later: the button looked broken. Anything that opens the list calls this
// off first, and the list opened by a press stays open.
function holdCompleterOpen() { if (COMPLETE.blurTimer) { clearTimeout(COMPLETE.blurTimer); COMPLETE.blurTimer = null; } }
function completerContext(box) {
