    key2.onchange = function () { r.key2 = key2.value; markRules(); };
    r.op2 = fillSelect(op2, (st.rule_ops || []).map(function (o) { return [o, RULE_OP_SYMBOL[o] || o]; }), r.op2 || '>=');
