  var wide = box.getBoundingClientRect();
  var left = Math.min(Math.max(8, at.left), window.innerWidth - wide.width - 12);
  var top = at.bottom + 8;
  if (top + wide.height > window.innerHeight - 8) top = Math.max(8, at.top - wide.height - 8);
  box.style.left = left + 'px';
  box.style.top = top + 'px';
}
// Give a thing the nice panel instead of the browser's tooltip. The title is
// kept, so a screen reader and a touch-and-hold still find the same words.
function explain(over, words, keep) {
  if (!over || !words) return over;
  var html = richText(words);
  // The browser's own tooltip is taken away rather than left beside this one.
  // Both showing at once is what somebody actually sees: a white box from the
  // browser sitting on top of the page's own dark one, saying the same thing
  // in a different face. The words are kept where a screen reader still finds
  // them, and where anybody looking at the page's own markup can see them.
  if (over.getAttribute && over.getAttribute('title')) {
    over.dataset.said = over.getAttribute('title');
    over.removeAttribute('title');
  }
  if (keep !== false) {
    // Ours to keep up to date; somebody else's aria-label is left alone. It
    // used to be written once and never again, so a dropdown whose chosen
    // entry had changed still read out the one it was drawn with.
    var carried = String(words).slice(0, 300);
