var LADDER_PRESETS = [
  ['', 'No ladder \u2014 use the lengths above'],
  ['10, 60, 1440, forever', 'Gentle, then final \u2014 10 min \u00b7 1 h \u00b7 1 day \u00b7 for good'],
  ['10, 60, 1440', 'Gentle \u2014 10 min \u00b7 1 h \u00b7 1 day, then the same again'],
  ['60, 1440, 10080, forever', 'Firm \u2014 1 h \u00b7 1 day \u00b7 1 week \u00b7 for good'],
  ['1440, forever', 'Short-tempered \u2014 1 day, then for good'],
  ['custom', 'Something else\u2026']
