function ladderRead(text) {
  var out = [];
  String(text || '').replace(/;/g, ',').split(',').forEach(function (piece) {
    piece = piece.trim().toLowerCase();
    if (!piece) return;
    if (/^(forever|for good|permanent|always)$/.test(piece)) { out.push(0); return; }
    var n = parseInt(piece, 10);
    if (n > 0) out.push(n);
  });
  return out;
}
function ladderWrite(steps) {
  return steps.map(function (n) { return n === 0 ? 'forever' : String(n); }).join(', ');
}
