  CH: 'Switzerland', CN: 'China', CZ: 'Czechia', DE: 'Germany', DK: 'Denmark', ES: 'Spain',
  FI: 'Finland', FR: 'France', GB: 'the United Kingdom', HK: 'Hong Kong', HU: 'Hungary',
  ID: 'Indonesia', IE: 'Ireland', IN: 'India', IR: 'Iran', IT: 'Italy', JP: 'Japan',
  KR: 'South Korea', LT: 'Lithuania', LV: 'Latvia', MD: 'Moldova', NL: 'the Netherlands',
  NO: 'Norway', PL: 'Poland', PT: 'Portugal', RO: 'Romania', RS: 'Serbia', RU: 'Russia',
  SE: 'Sweden', SG: 'Singapore', SK: 'Slovakia', TR: 'Turkey', UA: 'Ukraine',
  US: 'the United States', VN: 'Vietnam', ZA: 'South Africa'};
// The flags themselves are pictures served from this house - web/flags/*.svg,
