    badge.classList.add('none');
    return badge;
  }
  var pic = document.createElement('img');
  pic.className = 'cflag-img';
  pic.src = 'flags/' + two.toLowerCase() + '.svg';
  pic.alt = two;
  pic.width = 20;
  pic.height = 15;
  pic.loading = 'lazy';
  pic.onerror = function () { pic.remove(); badge.classList.add('letters'); };
  badge.appendChild(pic);
  badge.appendChild(el('span', 'cflag-cc', two));
  explain(badge, 'The country this address belongs to, from the list fetched under Settings. '
    + (COUNTRY_NAMES[two] ? ('This one is ' + COUNTRY_NAMES[two] + '. ') : '')
