function ntfyParts(url) {
  var out = {mode: 'public', base: '', topic: '', token: '', user: '', pass: ''};
  var text = String(url || '').trim();
  if (!text) return out;
  var m = /^(https?:\/\/)(?:([^@\/]*)@)?([^\/]+)\/(.*)$/.exec(text);
  if (!m) { out.base = text; return out; }
  out.base = m[1] + m[3];
  out.topic = m[4];
  var who = m[2] || '';
  if (!who) return out;
  var cut = who.indexOf(':');
  var user = cut < 0 ? who : who.slice(0, cut);
  var secret = cut < 0 ? '' : who.slice(cut + 1);
  try { user = decodeURIComponent(user); secret = decodeURIComponent(secret); } catch (e) {}
  if (!user && secret) { out.mode = 'token'; out.token = secret; return out; }
