// Why one list did not download, said so that it cannot be taken for
// another's: its name first, where it was asked for, what came back, how
// many times in a row, whether the copy held before is still keeping
// addresses out, and when it is tried again by itself.
function feedTrouble(feed, failed, held) {
  var bad = el('div', 'feedbad small');
  var head = el('div', 'feedbad-head');
  head.appendChild(document.createTextNode('\u26a0 '));
  head.appendChild(el('b', '', feed.short || feed.name));
  var times = parseInt(failed.times, 10) || 1;
  head.appendChild(document.createTextNode(' did not download \u2014 '
    + (times > 1 ? times + '\u00d7 in a row, first ' + ago(failed.since) + ', last ' + ago(failed.at)
                 : ago(failed.at))));
  bad.appendChild(head);
  var line = function (label, text, cls) {
    var one = el('div', 'feedbad-line' + (cls ? ' ' + cls : ''));
    one.appendChild(el('span', 'feedbad-k', label));
    one.appendChild(el('span', 'feedbad-v', text));
    bad.appendChild(one);
  };
  line('what came back', failed.words || 'nothing was said');
  if (failed.url) line('asked', failed.url, 'feedbad-url');
  line('meanwhile', held
    ? 'the copy from ' + ago(failed.held_at || ((((STATE.status || {}).feeds || {}).at || {})[feed.name]))
      + ' is still in use: ' + held + ' range(s)'
    : 'nothing is held from it, so this list keeps nobody out yet');
  if (failed.on === false) {
    line('next', 'switched off \u2014 it is not tried again');
  } else if (failed.next) {
    var left = Math.round(failed.next - Date.now() / 1000);
    line('next', left > 60 ? 'tried again by itself in ' + (left >= 3600
      ? Math.floor(left / 3600) + ' h ' + Math.floor((left % 3600) / 60) + ' min' : Math.floor(left / 60) + ' min')
      + ' \u2014 or with \u201cFetch them now\u201d'
      : 'tried again by itself with the next round');
  }
  return bad;
}
function feedsEditor(key, info, mark) {
  var box = el('div', 'ladder compose feedlist');
  var feeds = ((STATE.status || {}).feeds) || {};
  var known = feeds.known || [];
  var on = (String(info.value || '').split(',').map(function (w) { return w.trim(); })
            .filter(Boolean));
  var hidden = el('input');
  hidden.type = 'hidden';
  hidden.dataset.k = key;
  hidden.value = on.join(', ');
  var settle = function () { hidden.value = on.join(', '); mark(); };
  var rows = el('div', 'feedrows');
  box.appendChild(rows);
  known.forEach(function (feed) {
    var row = el('div', 'feedrow');
    var name = el('label', '', feed.short || feed.name);
    explain(name, (feed.what || '') + '\n' + (feed.short || feed.name));
    var sw = makeSwitch(on.indexOf(feed.name) >= 0, function (ticked) {
      var at = on.indexOf(feed.name);
      if (ticked && at < 0) on.push(feed.name);
      if (!ticked && at >= 0) on.splice(at, 1);
      settle();
    }, {});
    row.appendChild(name);
    row.appendChild(sw);
    var held = (feeds.sizes || {})[feed.name];
    var when = (feeds.at || {})[feed.name];
    var note = el('span', 'muted small');
    note.style.display = 'block';
    note.textContent = held ? (held + ' range(s), fetched ' + ago(when))
                            : 'not fetched yet';
    row.appendChild(note);
