function ntfyEditor(key, info, mark) {
  var box = el('div', 'ladder compose');
  var parts = ntfyParts(info.value);
  if (!parts.base && !parts.topic) { parts.base = 'https://ntfy.sh'; }
  var hidden = el('input');
  hidden.type = 'hidden';
  hidden.dataset.k = key;
  var said = el('div', 'muted small');
  var rows = el('div', 'compose-rows');
  var pick = el('select');
  fillSelect(pick, [
    ['public', 'A public server \u2014 ntfy.sh, the topic is the whole secret'],
    ['token', 'A private server \u2014 with a token'],
    ['login', 'A private server \u2014 with a user and a password']
  ], parts.mode);
  // as the ladder above: the first draw is not a change, and saying it was
  // froze the whole Settings card for the rest of the session
  var drawn = false;
  var settle = function () {
    hidden.value = ntfyJoin(parts);
    said.textContent = hidden.value
      ? ('what is saved: ' + hidden.value.replace(/\/\/[^@/]*@/, '//\u2026@'))
      : 'nothing is saved until a server and a topic are both filled in';
    if (drawn) mark();
  };
  var field = function (label, name, kind, hint) {
    var row = el('div', 'compose-row');
    row.appendChild(el('label', '', label));
    var input = el('input');
    input.type = kind || 'text';
    input.value = parts[name] || '';
    if (hint) input.placeholder = hint;
    input.oninput = function () { parts[name] = input.value.trim(); settle(); };
    row.appendChild(input);
    return row;
  };
  var paint = function () {
    rows.innerHTML = '';
    rows.appendChild(field('The server', 'base', 'text', 'https://ntfy.falco81.net'));
    rows.appendChild(field('The topic', 'topic', 'text', 'zigmon-house'));
    if (parts.mode === 'token') {
      rows.appendChild(field('Its token', 'token', 'password', 'tk_\u2026'));
    } else if (parts.mode === 'login') {
      rows.appendChild(field('The user', 'user', 'text', 'falco'));
      rows.appendChild(field('Its password', 'pass', 'password', ''));
    }
    settle();
  };
  pick.onchange = function () {
    parts.mode = pick.value;
    if (parts.mode === 'public') { parts.token = parts.user = parts.pass = ''; }
    else if (parts.mode === 'token') { parts.user = parts.pass = ''; }
    else { parts.token = ''; }
    paint();
  };
  box.appendChild(pick);
  box.appendChild(rows);
  box.appendChild(said);
