// A list of addresses, one per line. Kept as a comma-separated string, which
// is what the daemon has always taken - the lines are only how it is read and
// written. Blank lines and stray commas are somebody typing, not a mistake to
// be refused, so they are simply dropped on the way out.
function addressList(key, info, mark) {
  var wrap = el('div', 'addrlist');
  var box = el('textarea');
  box.dataset.k = key;
  box.dataset.list = '1';
  box.rows = 6;
  box.spellcheck = false;
  box.autocapitalize = 'off';
  box.autocomplete = 'off';
  box.placeholder = '192.168.1.0/24\n2a01:430::/48\n89.24.9.9';
  box.value = String(info.value === null || info.value === undefined ? '' : info.value)
    .split(',').map(function (x) { return x.trim(); })
    .filter(function (x) { return x; }).join('\n');
  var count = el('div', 'btnhelp addrcount');
  var retell = function () {
    var many = box.value.split('\n').map(function (x) { return x.trim(); })
      .filter(function (x) { return x; }).length;
    count.textContent = many === 0 ? 'nothing here yet'
      : (many === 1 ? '1 address or range' : many + ' addresses or ranges');
    // grows with what is in it, up to a point: a scroll bar inside a settings
    // card is worse than a tall card
    box.rows = Math.max(4, Math.min(16, box.value.split('\n').length + 1));
  };
  box.oninput = function () { retell(); mark(); };
  retell();
  wrap.appendChild(box);
  wrap.appendChild(count);
  return wrap;
