function ladderEditor(key, info, mark) {
  var box = el('div', 'ladder');
  var steps = ladderRead(info.value);
  var pick = el('select');
  var body = el('div', 'ladder-steps');
  var said = el('div', 'muted small');
  var hidden = el('input');
  hidden.type = 'hidden';
  hidden.dataset.k = key;
  // Drawn once and then whenever the user changes something. The first draw
  // is not a change: calling mark() there set "Unsaved changes" on a card
  // nobody had touched, and renderSettings refuses to redraw a dirty card -
  // so from the first time Control was opened, the Settings card never
  // followed anything again. A setting changed from the CLI, from a phone or
  // by "Fetch them now" simply never appeared, and the note was wiped at the
  // end of the same pass so there was nothing to see either.
  var drawn = false;
  var settle = function () {
    hidden.value = ladderWrite(steps);
    said.textContent = ladderWords(steps);
    if (drawn) mark();
    // the settings a ladder takes over are dimmed as soon as it has one
    try { applySettingsWhen(); } catch (e) { /* drawn before the grid is whole */ }
  };
  var paint = function () {
    body.innerHTML = '';
    steps.forEach(function (value, index) {
      var row = el('div', 'ladder-row');
      row.appendChild(el('span', 'ladder-n', (index + 1) + '.'));
      var when = el('select');
      fillSelect(when, LADDER_STEPS.map(function (s) { return [String(s[0]), s[1]]; }), String(value));
      when.onchange = function () {
        steps[index] = parseInt(when.value, 10);
        // for good is the end of any ladder: nothing after it can happen
        if (steps[index] === 0) steps = steps.slice(0, index + 1);
        pick.value = 'custom';
        settle();
        paint();
      };
      row.appendChild(when);
      var drop = iconButton('trash', 'Take this step away');
      drop.onclick = function () {
        steps.splice(index, 1);
        pick.value = 'custom';
        settle();
        paint();
      };
      row.appendChild(drop);
      body.appendChild(row);
    });
    var add = cmdButton('Add a step', 'add', 'small');
    add.classList.remove('needs-unlock');
    add.disabled = steps.length >= 8 || steps.indexOf(0) >= 0;
    add.title = steps.indexOf(0) >= 0
      ? 'The ladder ends at \u201cfor good\u201d; nothing can come after it'
      : 'One more step, taken the next time that address comes back';
    add.onclick = function () {
      steps.push(steps.length ? Math.min(43200, steps[steps.length - 1] * 4) : 10);
      pick.value = 'custom';
      settle();
      paint();
    };
    var bar = el('div', 'btnrow');
    bar.appendChild(add);
    body.appendChild(bar);
  };
  fillSelect(pick, LADDER_PRESETS, LADDER_PRESETS.some(function (p) {
    return p[0] === ladderWrite(steps);
  }) ? ladderWrite(steps) : (steps.length ? 'custom' : ''));
  pick.onchange = function () {
    if (pick.value === 'custom') { settle(); return; }
    steps = ladderRead(pick.value);
    settle();
    paint();
  };
  box.appendChild(pick);
  box.appendChild(body);
  box.appendChild(said);
  box.appendChild(hidden);
  settle();
  paint();
  drawn = true;              // from here on, a settle really is a change
  return box;
}
