function applySettingsWhen() {
  if (!$('settings-grid')) return;
  // every host at once, as one grid: a choice in one card can hide a box in another
  var grid = {querySelector: settingsQuery, querySelectorAll: settingsQueryAll};
  var now = function (key) {
    var box = grid.querySelector('[data-k="' + key + '"]');
    if (!box) return '';
    // A switch is a checkbox, and a checkbox's value is the word "on"
    // whether it is on or not - so every rule that asked whether a switch was
    // off read NaN and answered yes. What is wanted is whether it is ticked.
    if (box.dataset.bool || box.type === 'checkbox') return box.checked ? '1' : '0';
    return String(box.value);
  };
  // one condition, or several joined by & - each key=value or key!=value
  grid.querySelectorAll('[data-when]').forEach(function (item) {
    item.hidden = !String(item.dataset.when).split('&').every(function (c) {
      var neg = c.indexOf('!=') > 0, parts = c.split(neg ? '!=' : '=');
      return neg ? now(parts[0]) !== parts[1] : now(parts[0]) === parts[1];
    });
  });
