$('settings-save').onclick = function () {
  var body = {};
  settingsQueryAll('input[data-k], select[data-k], textarea[data-k]').forEach(
      function (b) {
    if (b.dataset.secret && b.value === '') return;      // left alone: it keeps the one it has
    if (b.dataset.list) {
      // one per line on the card, comma-separated for the daemon, which is
      // what it has always taken. Blank lines and stray commas are somebody
      // typing rather than a mistake worth refusing.
      var many = b.value.split(/[\n,]/).map(function (x) { return x.trim(); })
        .filter(function (x) { return x; });
      body[b.dataset.k] = many.length ? many.join(', ') : null;
      return;
    }
    body[b.dataset.k] = b.dataset.bool ? (b.checked ? 1 : 0) : (b.value === '' ? null : b.value);
  });
  withPin('Save settings', 'They apply immediately; no restart.', function (pin) {
    body.pin = pin;
    return post('config-save', body).then(function (r) {
      SETTINGS.dirty = false; forgetSig('settings');
      STATE._ovLoaded = 0;                 // redraw charts at once if a chart setting changed
      if (STATE.tab === 'history') loadHistory();
