    row.enabled = on; markSmsBuiltin(); paintSmsBuiltin();
  }, {small: true, disabled: !!taken, title: taken
      ? 'Not in use: your own command “' + taken + '” answers these words first'
      : row.enabled === false
        ? 'Switched off — a message saying this is answered as though nobody understood it'
        : 'On — a message saying this does it'});
