  var says = el('code', 'smshelp-says');
  says.textContent = row.phrase;
  line.appendChild(says);
  if (row.key) says.appendChild(objMark(objRef('smsbuiltin', row.key), row.phrase));
  var mid = el('div', 'smshelp-mid');
  mid.appendChild(el('div', 'smshelp-what', row.what));
  if (taken) {
    var why = el('div', 'smshelp-taken');
    why.appendChild(el('span', 'smshelp-taken-mark', '⚠'));
    var words = el('span', '');
    words.innerHTML = 'Not in use: your own command <code>' + esc(taken) + '</code> answers these words '
      + 'first. Delete it or change its words above and this one comes back by itself'
      + (taken.indexOf(' ') < 0 && taken.indexOf('\u007b') < 0    // one word, no {name} in it
          ? ' — a command of one word with no <code>{name}</code> in it answers <i>any</i> '
            + 'message that has that word anywhere in it.'
          : '.');
    why.appendChild(words);
    mid.appendChild(why);
  }
  var members = row.members || [];
  if (members.length) {
    var openNow = SMSBUILT.open[row.key] === true;
    var lit = members.filter(function (m) { return m.enabled !== false && !m.overridden_by; }).length;
    var takenN = members.filter(function (m) { return m.overridden_by; }).length;
    var fold = el('button', 'btn small smshelp-fold' + (takenN && !taken ? ' has-taken' : ''));
    fold.type = 'button';
    fold.textContent = (openNow ? '▾ ' : '▸ ') + lit + ' of ' + members.length + ' '
      + row.covers + (taken ? ''          // the box above says why, for all of them
        : takenN ? ' — ⚠ ' + takenN + ' taken by your own commands'
        : (lit === members.length ? '' : ' — some off'));
