      + 'answered as though nobody understood it; the rest still work.');
    fold.onclick = function () { SMSBUILT.open[row.key] = !openNow; paintSmsBuiltin(); };
    mid.appendChild(fold);
    if (openNow) {
      var bar = el('div', 'smshelp-thingbar');
      ['all on', 'all off'].forEach(function (label) {
        var b = el('button', 'btn small');
        b.type = 'button';
        setButtonIcon(b, label === 'all on' ? 'check' : 'close', label);
        b.onclick = function () {
          members.forEach(function (m) { m.enabled = label === 'all on'; });
          markSmsBuiltin(); paintSmsBuiltin();
