        box.disabled = !!m.overridden_by;
        box.onchange = function () { m.enabled = box.checked; markSmsBuiltin(); paintSmsBuiltin(); };
        chip.appendChild(box);
        chip.appendChild(el('span', 'smshelp-tick', m.overridden_by ? '⚠' : ''));
        chip.appendChild(el('span', 'smshelp-thingname', m.name));
        chip.title = m.overridden_by
          ? m.name + ': your own command “' + m.overridden_by + '” answers this first'
          : m.enabled === false
