setButtonIcon($('smsbuiltin-save'), 'save');
$('smsbuiltin-save').onclick = function () {
  withPin('Save what a text message understands',
          'What is switched off here is answered as though nobody understood it.', function (pin) {
    var off = [];
    (SMSBUILT.rows || []).forEach(function (r) {
      if (r.enabled === false) off.push(r.key);
      // a thing's own switch is kept whether or not its family is on, so
      // switching the family back on brings back exactly what was set here
      (r.members || []).forEach(function (m) {
        if (m.enabled === false) off.push(r.key + ':' + m.id);
      });
    });
    return post('sms-commands', {built_in_off: off, pin: pin}).then(function (r) {
      if (!r.ok) throw new Error(r.error || 'could not save');
      SMSBUILT.rows = r.built_in || SMSBUILT.rows;
      SMSBUILT.dirty = false;
      $('smsbuiltin-note').textContent = '';
      paintSmsBuiltin();
      return 'saved';
    });
  });
};
$('smscmd-add').onclick = function () {
  SMSCMD.rows = SMSCMD.rows || [];
  SMSCMD.rows.push({id: '', phrase: '', target: '', do: 'on', reply: '', enabled: true});
  markSmsCmd(); paintSmsCmd(STATE.status);
};
$('smscmd-save').onclick = function () {
  withPin('Save the SMS commands', 'The gateway is listened to at once.', function (pin) {
    return post('sms-commands', {commands: rowsToSave(SMSCMD, 'SMS commands'), pin: pin}).then(function (r) {
      if (!r.ok) throw new Error(r.error || 'could not save');
      saveGroups('smscmd', SMSCMD);
      SMSCMD.dirty = false; SMSCMD.rows = null; $('smscmd-note').textContent = ''; forgetSig('smscmd');
      // your own commands decide which built-in ones are in use, so that card
      // is asked again with them (what was switched there and not saved stays)
      if (!SMSBUILT.dirty) SMSBUILT.rows = null;
      tick(true);
      return (r.commands || []).length + ' command(s) saved';
    });
  });
};

// ---- action groups: several things switched under one name -------------------
