    row.appendChild(pick);
    attachCardMenu(row, {head: g.name || 'group', rows: [
      ['\ud83d\udd0c Switch it off now', function () { runTarget('act:' + g.id, 'off', g.name); }],
      ['\ud83d\udca1 Switch it on now', function () { runTarget('act:' + g.id, 'on', g.name); }],
