    return post('target-set', {target: target, do: action, pin: pin}).then(function (r) {
      if (!r.ok) throw new Error(r.error || 'could not'); return r.message || (label + ' \u2192 ' + action);
    });
  });
}
$('agroup-add').onclick = function () {
  AGROUPS.rows = AGROUPS.rows || [];
