// One key panel, told which machine it is for. The router and the server in
// front keep their own key; the words and the four buttons are the same, and
// two copies of them drift apart.
function sshKeyPanel(which, about) {
  var box = el('div', 'subpanel');
  box.style.gridColumn = '1/-1';
  box.appendChild(el('p', 'note', 'The key is made here and never leaves except when you download '
    + 'it. Put the public half on ' + about + ' \u2014 in that machine\u2019s '
    + '~/.ssh/authorized_keys \u2014 and it can log in without a password. Keep the private half '
    + 'safe: anybody holding it can log in there too. It goes into a settings export only when you '
    + 'ask for one with the secrets in it.'));
  var pub = el('div', 'muted small'); pub.style.margin = '6px 0';
  box.appendChild(pub);
  var bar = el('div', 'btnrow');
  var make = explain(cmdButton('Make a key', 'key', 'small'),
    'Make a new key pair here. The private half stays on this machine; the public half is shown so you '
    + 'can paste it into ' + about + '. Any key held now stops being used the moment this replaces it.');
  var mine = explain(cmdButton('Use my own', 'upload', 'small'),
    'Take a private key you already have, from a file. It must have no passphrase \u2014 nothing is here '
    + 'to type one in. Its public half is worked out and shown.');
  var down = explain(cmdButton('Download it', 'download', 'small'),
    'Download the PRIVATE half, as a file. Anybody who has it can log in wherever this key logs in, so '
    + 'it is worth a moment\u2019s thought about where it lands. The download is written into the audit log.');
  var drop = explain(cmdButton('Forget it', 'trash', 'small danger'),
    'Throw the key away. Logging in falls back to a password if one is set, and to nothing if not. What '
    + 'is in ' + about + '\u2019s authorized_keys is not touched \u2014 tidy that up there.');
  var act = function (what, title, why, extra, danger) {
    withPin(title, why, function (pin) {
      return post(which, Object.assign({pin: pin, do: what}, extra || {})).then(function (r) {
        if (!r.ok) throw new Error(r.error || 'could not');
        // The panel says what it said when it was drawn. Asking the settings
        // to be drawn again does not reach it while anything else on the page
        // is unsaved - which is why a new key only appeared after a reload.
        // It refreshes itself instead.
        refresh();
        forgetSig('settings');
        tick(true);
        return r.message || 'done';
      });
    }, !!danger);
  };
  make.onclick = function () {
    act('generate', 'Make a key',
        'A new key is made here. The old one stops working the moment ' + about + ' is given the new one.');
  };
  mine.onclick = function () {
    var box2 = document.createElement('input');
    box2.type = 'file';
    box2.onchange = function () {
      var f = box2.files && box2.files[0];
      if (!f) return;
      var reader = new FileReader();
      reader.onload = function () {
        act('upload', 'Use this key', 'It replaces whatever key is held now.',
            {key: String(reader.result)});
      };
      reader.readAsText(f);
    };
    box2.click();
  };
  down.onclick = function () {
    if (!isUnlocked()) { unlockFlow(function () { down.onclick(); }); return; }
    downloadBehindPin(which + '-key-download', 'zigmon-' + which + '-key');
  };
  drop.onclick = function () {
    act('forget', 'Forget the key for ' + about,
        'The daemon will have no key for it; a password can still be used.', null, true);
  };
  [make, mine, down, drop].forEach(function (b) { bar.appendChild(b); });
  box.appendChild(bar);
  var said = false;
  function refresh() {
    api(which).then(function (r) {
      if (!r.can_keygen && !said) {
        said = true;
        make.disabled = true; mine.disabled = true;
        box.insertBefore(el('p', 'note reason', 'ssh-keygen is not installed on this machine, so a key '
          + 'cannot be made or read here: dnf install openssh-clients.'), box.firstChild);
      }
      down.disabled = !r.has_key;
      drop.disabled = !r.has_key;
      pub.textContent = r.has_key ? '' : 'No key yet \u2014 make one, or let it log in with a password.';
      if (r.public) {
        pub.innerHTML = 'The public half: <code class="copyme" data-copy="' + esc(r.public)
          + '" title="Click to copy">' + esc(r.public) + '</code>';
        pub.querySelector('.copyme').onclick = function () { copyText(r.public); };
      }
    }, function () { pub.textContent = ''; });
  }
  refresh();
  return box;
}
// What the server in front is for: reading its log, and saying what came of it.
function proxyPanel() {
  var box = el('div', 'subpanel');
  box.style.gridColumn = '1/-1';
  var line = el('div', 'muted small'); line.style.marginBottom = '8px';
  box.appendChild(line);
  // The PHP this page is served by, and whether it carries the fix for the
  // two holes of 21 October 2026. Here rather than on the health card
  // because that one answers without a PIN, and the version of PHP is the
  // first thing anybody deciding what to try would like to know.
  var php = el('div', 'small'); php.style.marginBottom = '8px';
  box.appendChild(php);
  var bar = el('div', 'btnrow');
  var test = cmdButton('Try the log', 'search', 'small');
  var read = cmdButton('Read it now', 'refresh', 'small primary');
  var whole = cmdButton('Read it from the top', 'first', 'small');
  test.title = 'Read the last five lines and say how many of them this can weigh. Weighs nothing';
  read.title = 'Read whatever has been added since last time, and weigh it';
  whole.title = 'Read it from the beginning (at most the last two megabytes of it)';
  var run = function (what, title, why, extra) {
    withPin(title, why, function (pin) {
      return post('proxy', Object.assign({pin: pin, do: what}, extra || {})).then(function (r) {
        if (!r.ok) throw new Error(r.error || 'could not');
        if (r.lines && r.lines.join) {
          showDetail('The last of the log', [{section: 'as it arrived'}], null, true);
          var host = $('attnbody');
          r.lines.forEach(function (one) {
            var row = el('div', 'muted small');
            row.style.cssText = 'font-family:ui-monospace,Menlo,monospace;word-break:break-all;margin:2px 0';
            row.textContent = one;
            host.appendChild(row);
          });
        }
        tick(true);
        return r.message || 'done';
      });
    });
  };
  test.onclick = function () { run('test', 'Try the log', 'It reads the last five lines and weighs nothing.'); };
  read.onclick = function () {
    run('read', 'Read the log now',
        'Whatever has been added since the last reading is read and weighed. An address that has been '
        + 'trying things may end on the blocked list.');
  };
  whole.onclick = function () {
    run('read', 'Read the log from the top',
        'At most the last two megabytes of it, weighed as though it had just arrived. On a log that '
        + 'has been running a while this may put several addresses on the list at once.', {whole: true});
  };
  [test, read, whole].forEach(function (b) { bar.appendChild(b); });
  box.appendChild(bar);
  api('proxy').then(function (r) {
    var said = [];
    said.push(r.ready ? ('reading ' + r.log) : 'no server in front is set');
    if (r.ready && !r.watching) said.push('not being read by itself \u2014 turn proxy_watch on');
    if (r.last && r.last.at) {
      said.push('last read ' + ago(r.last.at) + ': ' + (r.last.lines || 0) + ' line(s), '
        + (r.last.addresses || 0) + ' address(es) weighed');
    }
    if (r.trouble) said.push('last reading failed: ' + r.trouble);
    line.textContent = said.join(' \u00b7 ');
    var p = r.php || {};
    if (!p.found) {
      php.textContent = '';
    } else if (p.vulnerable) {
      php.className = 'sh-line bad';
      php.textContent = 'PHP ' + p.version + ' serves this page, and it has the two holes published '
        + 'on 21 October 2026 (' + (p.cves || []).join(', ') + ', both 9.2). One request from '
        + 'anybody who can reach php-fpm is enough, and it is acted on before any of this page '
        + 'runs \u2014 no sign-in and no address rule is in front of it. ' + (p.fix || '');
    } else {
      php.className = 'muted small';
      php.textContent = 'PHP ' + p.version + (p.patched_by
        ? ' \u2014 patched by the distribution (' + p.patched_by + ')'
        : ' \u2014 carries the fix of 21 October 2026')
        + (p.multipart_refused === false
           ? '. nginx does not refuse multipart bodies in front of it; the shape is the way in '
             + 'and nothing here ever sends one.' : '');
    }
  }, function () { line.textContent = ''; php.textContent = ''; });
  return box;
}
function mikrotikKey(what, title, why, extra, danger) {
