// The router's own list, read now, with everything this house knows about each
// address beside it. Two halves that mean little apart: the list is the truth
// about what is being stopped, and the reason, the ladder step and the lines
// that earned it live here.
function routerSheet() {
  withPin('Read the router now',
    'It logs in and reads the address list, both families. Nothing is changed.', function (pin) {
      return post('blocked-router', {pin: pin}).then(function (r) {
        if (!r.ok) throw new Error(r.error || 'could not read the router');
        drawRouterSheet(r);
        return 'read in ' + r.read_in_ms + ' ms';
      });
    });
}
// Folding addresses into the subnets their lists name whole. Always shown
// first: what would be folded, into what, and why each subnet is allowed -
// and only then, on a second press, done.
function foldSheet(widest) {
  withPin('Fold into subnets',
    'It works out what could be folded and shows it. Nothing changes until you say so.', function (pin) {
      return post('blocked-fold', {pin: pin, widest: widest}).then(function (r) {
        if (!r.ok) throw new Error(r.error || 'could not work it out');
        drawFoldSheet(r);
        return r.folded ? r.folded + ' address(es) could be folded' : 'nothing to fold';
      });
    });
}
function drawFoldSheet(r) {
  showDetail('Fold into subnets', [], null, true);
  var host = $('attnbody');
  var lead = el('p', 'lead');
  if (!(r.groups || []).length) {
    lead.innerHTML = '<b>Nothing to fold.</b> Of the ' + r.singles + ' address(es) kept out on their own, '
      + r.on_lists + ' are on an enabled list — but no list names a whole subnet (no wider than /'
      + r.widest + ') with two or more of them in it. Addresses stay one line each unless a list '
      + 'names the whole street they live in.';
    host.appendChild(lead);
  } else {
    lead.innerHTML = '<b>' + r.before + '</b> line(s) on the list now; folding leaves <b>' + r.after
      + '</b>. That is <b>' + r.folded + '</b> address(es) kept out as <b>' + r.subnets
      + '</b> subnet(s)' + (r.into_standing ? ', plus some into ' + r.into_standing
        + ' subnet(s) already kept out for good' : '') + '. '
      + 'Each subnet below is named <b>whole</b> by an enabled list; an address whose street no list '
      + 'names stays a line of its own, so nothing is kept out because a neighbour was. Every folded '
      + 'address keeps its reason and its story under the subnet, and taking a subnet off puts its '
      + 'addresses back as they were.';
    host.appendChild(lead);
  }
  // how wide a subnet may be: a list naming a /16 is still a list naming it,
