  widths.appendChild(el('span', 'muted small', 'no wider than'));
  [24, 20, 16].forEach(function (w) {
    var b = foldButton('/' + w, 'net', w === r.widest ? 'primary' : '');
    explain(b, 'Allow subnets up to /' + w + ' for IPv4 (' + Math.pow(2, 32 - w).toLocaleString()
      + ' addresses), and up to /' + ({24: 64, 20: 56, 16: 48})[w] + ' for IPv6 — only where a '
      + 'list names that whole range.');
    b.onclick = function () { if (w !== r.widest) foldSheet(w); };
    widths.appendChild(b);
  });
  host.appendChild(widths);
  var sheet = el('div', 'alertsheet rtr');
  (r.groups || []).forEach(function (g) {
