    head.appendChild(el('span', 'road', g.members.length + ' address(es)'));
    if (g.existing) head.appendChild(el('span', 'road same', 'already kept out for good'));
    if ((g.lists || []).length) {
      head.appendChild(el('span', 'road none', '📕 whole subnet on ' + g.lists.join(', ')));
    }
    card.appendChild(head);
    var proof = el('div', 'proof');
    proof.appendChild(el('div', 'ph', 'folded from'));
    g.members.forEach(function (m) {
      var line = el('div', 'pl');
      line.appendChild(el('span', 't', m.ip));
      line.appendChild(document.createTextNode(String(m.why || '').slice(0, 140)
        + (m.since ? '   — since ' + stamp(m.since) : '')));
      proof.appendChild(line);
    });
    card.appendChild(proof);
    sheet.appendChild(card);
  });
  host.appendChild(sheet);
  if ((r.groups || []).length) {
    var go = el('div', 'btnrow');
    go.style.marginTop = '12px';
    var yes = foldButton('Fold ' + r.folded + ' address(es) into '
      + (r.subnets + r.into_standing) + ' subnet(s)', 'fold', 'primary');
    yes.onclick = function () {
      foldJobStart('Folding into subnets', {apply: true, widest: r.widest},
                   'Keep out these subnets instead of the addresses in them.');
    };
    go.appendChild(yes);
    var no = foldButton('Leave them as they are', 'cancel');
    no.onclick = function () { $('attnback').hidden = true; };
