function foldHistory(host, r) {
  host.appendChild(el('div', 'attn-sec', 'Earlier folds — the last ' + (r.keep || 10)
    + ' are kept (Settings → The router that carries the list)'));
  var vs = r.versions || [];
  if (!vs.length) {
    host.appendChild(el('p', 'muted small', 'Nothing has been folded yet.'));
  }
  vs.forEach(function (v) {
    var row = el('div', 'btnrow');
    row.style.alignItems = 'center';
    row.style.margin = '4px 0';
    var words = el('span', 'small' + (v.undone ? ' muted' : ''));
    words.textContent = stamp(v.ts) + ' · ' + v.folded + ' address(es) into '
      + (v.subnets || []).length + ' new subnet(s) · ' + v.before + ' → ' + v.after
      + ' line(s) · no wider than /' + v.widest + (v.by ? ' · by ' + v.by : '')
      + (v.undone ? ' · undone ' + stamp(v.undone) + (v.undone_by ? ' by ' + v.undone_by : '') : '');
    explain(words, (v.subnets || []).join(', ') || 'only into subnets that were there already');
    row.appendChild(words);
    if (!v.undone) {
      var undo = foldButton('Undo this fold', 'undo');
      explain(undo, 'Takes apart what this fold made: its subnets come off, and the addresses in them '
        + 'go back as lines of their own with their own reasons and ends. Anything kept out since '
        + 'stays kept out. The router is told and read back, as when folding.');
      undo.onclick = function () {
        foldJobStart('Undoing the fold of ' + stamp(v.ts), {undo: v.id},
                     'Take apart what this fold made and put its addresses back as they were.');
      };
      row.appendChild(undo);
    }
    // Out of the history, by hand: only this one record goes.
    var drop = foldForgetButton(r, v.id, 'Remove', 'Remove this fold from the history',
      'Takes only this fold out of the undo history; the others stay. Nothing on the list or the '
      + 'router changes: its subnets stay kept out, and each still shows the addresses it was folded '
      + 'from. Taking one of those subnets off still puts its addresses back. What goes is only this '
      + 'one-press undo.');
    row.appendChild(drop);
    host.appendChild(row);
  });
  var bar = el('div', 'btnrow');
  bar.style.marginTop = '10px';
  if (vs.length > 1) {
    bar.appendChild(foldForgetButton(r, 'all', 'Clear the whole history (' + vs.length + ')',
      'Clear the whole fold history',
      'Takes every fold above out of the undo history at once. Nothing on the list or the router '
      + 'changes: the subnets stay kept out and keep what they were folded from, and taking one off '
      + 'still puts its addresses back. What goes is only the one-press undo of each fold.'));
  }
  if (r.router) {
    var check = foldButton('Check the router now', 'router');
    explain(check, 'Reads the router and holds it against the list here. Anything missing on it, or '
      + 'left on it that is no longer kept out here, is put right and read back once more.');
    check.onclick = function () {
      foldJobStart('Checking the router', {check: true},
                   'Read the router and put it in step with the list here.');
    };
    bar.appendChild(check);
  }
  if (bar.children.length) host.appendChild(bar);
}
// Taking a fold - or every fold - out of the undo history. Two presses, since
// an undo that is gone does not come back: the first turns it red and asks
// again for four seconds.
function foldForgetButton(r, which, label, title, why) {
  var drop = foldButton(label, 'trash', 'small');
  explain(drop, why);
  drop.onclick = function () {
    if (!drop.dataset.armed) {
      drop.dataset.armed = '1';
      drop.classList.add('danger');
      setButtonIcon(drop, 'trash', 'Press again to remove');
      drop._disarm = setTimeout(function () {
        delete drop.dataset.armed;
        drop.classList.remove('danger');
        setButtonIcon(drop, 'trash', label);
      }, 4000);
      return;
    }
    clearTimeout(drop._disarm);
    withPin(title, 'Only the undo record goes; the subnets stay kept out.', function (pin) {
      return post('blocked-fold', {pin: pin, widest: r.widest, forget: which}).then(function (x) {
        if (!x.ok) throw new Error(x.error || 'could not remove it');
        drawFoldSheet(x);
        if (x.forgot && !x.forgot.ok) throw new Error(x.forgot.message);
        return (x.forgot && x.forgot.message) || 'removed';
      });
    }, true);
  };
  return drop;
}

// ---- imports on trial -------------------------------------------------------------
// New things from a file, added without touching what is in force, doing
// nothing but saying what they would have done until committed.
var TRIAL = {data: null, name: '', sections: null, alerts: false};
var TRIAL_CALLED = {messages: 'Alert messages', scripts: 'Little scripts', sensor_groups: 'Sensor groups',
                    action_groups: 'Action groups', scenes: 'Scenes', sequences: 'Sequences', rules: 'Rules', schedules: 'Schedules',
                    presence_triggers: 'Presence triggers', sms_commands: 'SMS commands'};
var TRIAL_STATE = {trial: ['on trial', 'test'], committed: ['committed', 'good'],
                   rolled_back: ['rolled back', 'same'], replaced: ['closed by a whole import', 'same']};
// Two presses for anything that cannot be taken back: the first turns the
// button red and asks again for four seconds.
function armedButton(label, key, cls, action) {
  var b = foldButton(label, key, cls);
  b.onclick = function () {
    if (!b.dataset.armed) {
      b.dataset.armed = '1';
      b.classList.add('danger');
      setButtonIcon(b, key, 'Press again');
      b._disarm = setTimeout(function () {
        delete b.dataset.armed;
        b.classList.remove('danger');
        setButtonIcon(b, key, label);
      }, 4000);
      return;
    }
    clearTimeout(b._disarm);
    action();
  };
  return b;
}
setButtonIcon($('trial-import'), 'flask');
setButtonIcon($('trial-manager'), 'list');
$('trial-import').onclick = function () { $('trial-file').click(); };
$('trial-manager').onclick = function () { trialManager(); };
$('trial-file').onchange = function () {
  var file = $('trial-file').files[0];
  if (!file) return;
  file.text().then(function (text) {
    var data;
    try { data = JSON.parse(text); } catch (e) { toast('Not a JSON file', false); return; }
    TRIAL.data = data; TRIAL.name = file.name; TRIAL.sections = null; TRIAL.alerts = false;
    trialPlan();
  });
  $('trial-file').value = '';
};
function trialPlan() {
  withPin('Import on trial', 'It looks at the file and shows what it would add. Nothing changes yet.',
    function (pin) {
      return post('trial', {pin: pin, do: 'plan', data: TRIAL.data, sections: TRIAL.sections}).then(function (r) {
        if (!r.ok) throw new Error(r.error || 'could not read it');
        drawTrialPlan(r);
        return r.fit ? (r.adds + r.replaces) + ' item(s) could go on trial'
                                         : 'this file cannot go on trial as it is';
      });
    });
}
function drawTrialPlan(r) {
  showDetail('Import on trial — ' + TRIAL.name, [], null, true);
  var host = $('attnbody');
  var lead = el('p', 'lead');
  lead.innerHTML = r.blocked.length
    ? '<b>Refused.</b> This file would change what is in force, so nothing of it can go in. Take those '
      + 'parts out of the file, or untick their section below.'
    : (r.adds + r.replaces
       ? '<b>' + r.adds + '</b> new item(s)' + (r.replaces ? ', and <b>' + r.replaces + '</b> taking the place of '
         + 'items still on trial from an earlier file' : '') + '. Nothing in force is changed. On trial, '
         + 'nothing here acts: each writes down what it would have done.'
       : '<b>Nothing to import</b> in the sections ticked.');
  host.appendChild(lead);
  // which parts of the file to take
  if ((r.offered || []).length > 1) {
    var pick = el('div', 'trial-pick');
    pick.appendChild(el('span', 'muted small', 'take from the file:'));
    r.offered.forEach(function (k) {
      var lab = el('label');
      var box = el('input'); box.type = 'checkbox';
      box.checked = !TRIAL.sections || TRIAL.sections.indexOf(k) >= 0;
      box.onchange = function () {
        var now = Array.prototype.filter.call(pick.querySelectorAll('input'), function (x) { return x.checked; })
          .map(function (x) { return x.dataset.k; });
        TRIAL.sections = now;
        trialPlan();
      };
      box.dataset.k = k;
      lab.appendChild(box);
      lab.appendChild(document.createTextNode(TRIAL_CALLED[k] || k));
      pick.appendChild(lab);
    });
    host.appendChild(pick);
  }
  var sheet = el('div', 'alertsheet');
  if (r.blocked.length) {
    var bad = el('div', 'ak refused');
    bad.appendChild(el('h4', '', '⛔ Would change what is in force'));
    var list = el('div', 'proof');
    r.blocked.forEach(function (b) { list.appendChild(el('div', 'pl', b)); });
    bad.appendChild(list);
    sheet.appendChild(bad);
  }
  (r.sections || []).forEach(function (sec) {
    var card = el('div', 'ak trial');
    var head = el('h4');
    head.appendChild(el('span', '', TRIAL_CALLED[sec.key] || sec.key));
    head.appendChild(el('span', 'road test', sec.items.length + ' on trial'));
    card.appendChild(head);
    sec.items.forEach(function (it) {
      var line = el('div', 'pl');
      line.style.margin = '5px 0';
      line.appendChild(el('span', '', it.title));
      if (it.replaces) {
        var rp = el('span', 'road same', 'replaces a trial item');
        rp.style.marginLeft = '8px';
        explain(rp, 'Takes the place of ' + it.replaces.title + ', still on trial from an earlier file. '
          + 'Rolling this import back puts that one back.');
        line.appendChild(rp);
      }
      (it.warnings || []).forEach(function (w) {
        var wl = el('div', 'muted small', '⚠️ ' + w);
        wl.style.marginLeft = '14px';
        line.appendChild(wl);
      });
      card.appendChild(line);
    });
    sheet.appendChild(card);
  });
  host.appendChild(sheet);
  var opt = el('label', 'trial-pick');
  var al = el('input'); al.type = 'checkbox'; al.checked = TRIAL.alerts;
  al.onchange = function () { TRIAL.alerts = al.checked; };
  opt.appendChild(al);
  opt.appendChild(document.createTextNode('Let its alert messages really go out, marked [TEST] — ntfy and Telegram only, never SMS'));
  host.appendChild(opt);
  var row = el('div', 'btnrow');
  var go = foldButton('Add on trial', 'flask', 'primary');
  go.disabled = !r.fit;
  go.onclick = function () {
    withPin('Add on trial', 'Only new items; nothing in force changes.', function (pin) {
      return post('trial', {pin: pin, do: 'add', data: TRIAL.data, sections: TRIAL.sections,
                            name: TRIAL.name, alerts: TRIAL.alerts}).then(function (x) {
        if (!x.ok) throw new Error(x.error || 'not imported');
        drawTrialManager(x.imports);
        trialRefresh();
        return x.message;
      });
    });
  };
  row.appendChild(go);
  var no = foldButton('Cancel', 'cancel');
  no.onclick = function () { $('attnback').hidden = true; };
  row.appendChild(no);
  host.appendChild(row);
}
function trialManager() {
  withPin('Imports on trial', 'Shows what is on trial and what was done with earlier imports.', function (pin) {
    return post('trial', {pin: pin, do: 'list'}).then(function (x) {
      if (!x.ok) throw new Error(x.error || 'could not read them');
      drawTrialManager(x.imports);
      return (x.imports || []).filter(function (b) { return b.state === 'trial'; }).length + ' on trial';
    });
  });
}
// After anything on trial changes, the editors read their lists again - one
// holding an old copy would save it back over the change. One being edited
// is left alone; it says so when saved.
function trialRefresh() {
  [MESSAGES, PTRIG, RULES, SGROUPS, SMSCMD, AGROUPS, SCHEDULES, SCENES, SEQUENCES].forEach(function (x) {
    if (x && !x.dirty) x.rows = null;
  });
  if (!SCRIPTS.dirty) loadScripts();
  tick(true);
}
function trialDo(title, why, body) {
  withPin(title, why, function (pin) {
    return post('trial', Object.assign({pin: pin}, body)).then(function (x) {
      if (!x.ok) throw new Error(x.error || 'it did not work');
      drawTrialManager(x.imports);
      trialRefresh();
      return x.message;
    });
  }, true);
}
function drawTrialManager(imports) {
  showDetail('Imports on trial', [], null, true);
  var host = $('attnbody');
  var open = (imports || []).filter(function (b) { return b.state === 'trial'; });
  var done = (imports || []).filter(function (b) { return b.state !== 'trial'; });
  var lead = el('p', 'lead');
  lead.innerHTML = open.length
    ? '<b>' + open.length + '</b> import(s) on trial. What they add does nothing yet — below is what it '
      + 'would have done. <b>Commit</b> makes it ordinary configuration; <b>Roll back</b> takes out exactly '
      + 'what it added.'
    : 'Nothing is on trial. Import a file with <b>Import on trial…</b> in Settings → Backup.';
  host.appendChild(lead);
  var sheet = el('div', 'alertsheet');
  open.forEach(function (b) {
    var card = el('div', 'ak trial');
    var head = el('h4');
    head.appendChild(el('span', '', b.name));
    head.appendChild(el('span', 'road test', 'on trial'));
    if (b.alerts) head.appendChild(el('span', 'road on', 'TEST alerts go out'));
    card.appendChild(head);
    card.appendChild(el('div', 'what', stamp(b.ts) + (b.by ? ' · by ' + b.by : '')));
    var what = el('div', 'proof');
    Object.keys(b.titles || {}).forEach(function (k) {
      var mine = (b.items || {})[k] || [];
      var h = el('div', 'muted small', (TRIAL_CALLED[k] || k) + ' \u2014 ' + mine.length);
      h.style.cssText = 'margin-top:6px;text-transform:uppercase;letter-spacing:.04em;font-size:11px';
      what.appendChild(h);
      (b.titles[k] || []).forEach(function (t) {
        var one = el('div', 'pl', t);
        one.style.marginLeft = '10px';
        what.appendChild(one);
      });
    });
    card.appendChild(what);
    var would = el('div', 'eg');
    would.appendChild(el('span', 'egt', 'Would have acted ' + (b.would_n || 0) + ' time(s)'));
    (b.would || []).slice(0, 6).forEach(function (w) {
      would.appendChild(el('div', 'egw', stamp(w[0]) + ' — ' + w[1]));
    });
    if (!(b.would || []).length) would.appendChild(el('div', 'egw', 'Nothing yet.'));
    card.appendChild(would);
    var row = el('div', 'btnrow');
    row.style.marginTop = '10px';
    var commit = armedButton('Commit', 'check', 'primary', function () {
      trialDo('Commit "' + b.name + '"', 'It becomes ordinary configuration and starts acting for real.',
              {do: 'commit', id: b.id});
    });
    explain(commit, 'Everything this import added starts acting for real, as ordinary configuration.');
    row.appendChild(commit);
    var back = armedButton('Roll back', 'undo', '', function () {
      trialDo('Roll back "' + b.name + '"', 'Takes out exactly what it added.', {do: 'rollback', id: b.id});
    });
    explain(back, 'Takes out exactly what this import added. Where it took the place of an item still on '
      + 'trial from an earlier file, that one comes back. Nothing in force is touched.');
    row.appendChild(back);
    var tests = foldButton(b.alerts ? 'Stop TEST alerts' : 'Send TEST alerts', 'bell');
    explain(tests, 'Whether its alert messages really go out while on trial, marked [TEST] — ntfy and '
      + 'Telegram only, never SMS.');
    tests.onclick = function () {
      trialDo('Test alerts', 'Only for this import.', {do: 'alerts', id: b.id, on: !b.alerts});
    };
    row.appendChild(tests);
    card.appendChild(row);
    sheet.appendChild(card);
  });
  host.appendChild(sheet);
  host.appendChild(el('div', 'attn-sec', 'History — committed and rolled back'));
  if (!done.length) host.appendChild(el('p', 'muted small', 'Nothing here yet.'));
  var boxes = [];
  done.forEach(function (b) {
    var line = el('label', 'trial-hist');
    var box = el('input'); box.type = 'checkbox'; box.dataset.id = b.id;
    boxes.push(box);
    line.appendChild(box);
    var st = TRIAL_STATE[b.state] || [b.state, 'same'];
    var badge = el('span', 'road ' + st[1], st[0]);
    var sheetish = el('span', 'alertsheet');
    sheetish.style.display = 'inline';
    sheetish.appendChild(badge);
    line.appendChild(sheetish);
    var n = Object.keys(b.titles || {}).reduce(function (a, k) { return a + (b.titles[k] || []).length; }, 0);
    line.appendChild(el('span', '', b.name + ' · ' + n + ' item(s) · on trial ' + stamp(b.ts)
      + ' · ' + st[0] + ' ' + stamp(b.closed) + (b.closed_by ? ' by ' + b.closed_by : '')
      + (b.again_as ? ' · put on trial again' : '')));
    if (b.again) {
      // what a rollback took out is kept with the record: back on trial with
      // one press, through the same checks a new file goes through
      var again = foldButton('On trial again', 'flask', 'small');
      again.classList.add('trial-again');
      explain(again, 'Puts exactly what this import added back on trial, without the file. Refused, the '
        + 'same as a new file, if any of it would now take the place of something in force.');
      again.onclick = function (ev) {
        ev.preventDefault(); ev.stopPropagation();
        trialDo('Put "' + b.name + '" on trial again', 'What it added goes back on trial; nothing in force is touched.',
                {do: 'again', id: b.id});
      };
      line.appendChild(again);
    }
    host.appendChild(line);
  });
  var row = el('div', 'btnrow');
  row.style.marginTop = '10px';
  if (done.length) {
    row.appendChild(armedButton('Remove selected', 'trash', 'small', function () {
      var ids = boxes.filter(function (x) { return x.checked; }).map(function (x) { return x.dataset.id; });
      if (!ids.length) { toast('Tick the ones to remove first', false); return; }
      trialDo('Remove from the history', 'Only the record goes; the configuration is not touched.',
              {do: 'forget', ids: ids});
    }));
    row.appendChild(armedButton('Clear the history (' + done.length + ')', 'trash', 'small', function () {
      trialDo('Clear the history', 'Only the records go; the configuration is not touched.',
              {do: 'forget', all: true});
    }));
  }
  var more = foldButton('Import on trial…', 'flask');
  more.onclick = function () { $('trial-file').click(); };
  row.appendChild(more);
  var close = foldButton('Close', 'close', 'primary');
  close.onclick = function () { $('attnback').hidden = true; };
  row.appendChild(close);
  host.appendChild(row);
}
// A fold, an undo or a check, watched step by step: here, then the router
// line by line, then the router read back.
var FOLD_TITLES = {fold: 'Folding into subnets', undo: 'Undoing a fold', check: 'Checking the router'};
function foldJobStart(title, body, why) {
  withPin(title, why, function (pin) {
    return post('blocked-fold', Object.assign({pin: pin}, body)).then(function (x) {
      if (!x.ok) throw new Error(x.error || 'could not start');
      // one runs at a time: pressed while another is running, it is that one
      // that is shown, under its own name, and said so
      var asked = body.apply ? 'fold' : body.undo ? 'undo' : 'check';
      var joined = x.job.kind !== asked || x.job.started < Date.now() / 1000 - 2;
      foldJobWatch(joined ? FOLD_TITLES[x.job.kind] || title : title, x.job.id);
      return joined ? 'one was already running \u2014 showing it; press again when it is done' : 'started';
    });
  });
}
function foldJobWatch(title, id) {
  showDetail(title, [], null, true);
  var host = $('attnbody');
  var list = el('div', 'fold-stages');
  var barBox = el('div', 'fold-bar');
  barBox.style.cssText = 'height:8px;border-radius:4px;background:rgba(127,127,127,.25);'
    + 'margin:10px 0 4px;overflow:hidden';
  var bar = el('div');
  bar.style.cssText = 'height:100%;width:0;background:#3fb950;transition:width .3s';
  barBox.appendChild(bar);
  var count = el('div', 'muted small');
  var tail = el('div');
  host.appendChild(list);
  host.appendChild(barBox);
  host.appendChild(count);
  host.appendChild(tail);
  var MARK = {running: '⏳', done: '✅', failed: '❌', skipped: '➖'};
  var draw = function (job) {
    list.innerHTML = '';
    (job.stages || []).forEach(function (st) {
      var line = el('div', 'fold-stage');
      line.style.margin = '6px 0';
      line.appendChild(el('b', '', (MARK[st.state] || '') + ' ' + st.label));
      if (st.words) {
        var w = el('div', 'muted small');
        w.style.marginLeft = '22px';
        w.style.wordBreak = 'break-word';
        w.textContent = st.words;
        line.appendChild(w);
      }
      list.appendChild(line);
    });
    var pct = job.total ? Math.round(100 * job.sent / job.total) : (job.done ? 100 : 0);
    bar.style.width = pct + '%';
    count.textContent = job.total ? ('router: ' + job.sent + ' of ' + job.total + ' change(s) sent') : '';
    if (!job.done) return;
    bar.style.background = job.ok ? '#3fb950' : '#f85149';
    tail.innerHTML = '';
    var verdict = el('p', 'lead');
    var chk = job.check;
    verdict.innerHTML = job.error ? '<b>It stopped:</b> ' + esc(job.error)
      : (chk ? (chk.ok
                ? '<b>✅ The router is in step with the list here.</b> ' + chk.here + ' line(s) here, '
                  + chk.on_router + ' of ours on the router.'
                : '<b>❌ The router is not in step.</b> ' + chk.missing_n + ' kept out here and missing '
                  + 'on the router; ' + chk.extra_n + ' on the router and no longer kept out here. It was '
                  + 'told twice. The list here is what counts: those addresses are still refused by this '
                  + 'machine.')
         : '<b>Done.</b>');
    tail.appendChild(verdict);
    if (chk && !chk.ok) {
      ['missing', 'extra'].forEach(function (k) {
        if (!(chk[k] || []).length) return;
        var box = el('div', 'proof');
        box.appendChild(el('div', 'ph', k === 'missing' ? 'missing on the router'
                                                         : 'on the router, not kept out here'));
        chk[k].forEach(function (a) { box.appendChild(el('div', 'pl mono', a)); });
        tail.appendChild(box);
      });
    }
    var btns = el('div', 'btnrow');
    btns.style.marginTop = '10px';
    var version = job.result && job.result.version;
    if (job.kind === 'fold' && version && !job.error) {
      var undo = foldButton('Undo this fold', 'undo');
      undo.onclick = function () {
        foldJobStart('Undoing that fold', {undo: version},
                     'Take apart what this fold made and put its addresses back as they were.');
      };
      btns.appendChild(undo);
    }
    if (job.ok === false) {
      var again = foldButton('Try the router again', 'refresh');
      again.onclick = function () {
        foldJobStart('Checking the router', {check: true},
                     'Read the router and put it in step with the list here.');
      };
      btns.appendChild(again);
    }
    var close = foldButton('Close', 'close', 'primary');
    close.onclick = function () { $('attnback').hidden = true; };
    btns.appendChild(close);
    tail.appendChild(btns);
    loadApprovals(true);
  };
  var poll = function () {
    post('blocked-fold', {job: id}).then(function (x) {
      if (!x.ok) { tail.textContent = x.error || 'the job is gone'; return; }
      draw(x.job);
      if (!x.job.done && !$('attnback').hidden) setTimeout(poll, 400);
    }, function (e) {
      var said = String((e && e.message) || e);
      // the editing session ran out: asking again will not help, and the job
      // goes on regardless - say so rather than retrying for ever
      if (signInNeeded(said) || /locked|may not do that/i.test(said)) {
        tail.textContent = 'Stopped watching: ' + said + '. It carries on by itself; sign in and open '
          + 'Fold into subnets again to see how it ended.';
        return;
      }
      tail.textContent = 'lost touch with it: ' + said + ' \u2014 retrying';
      if (!$('attnback').hidden) setTimeout(poll, 1500);
    });
  };
  poll();
}
function drawRouterSheet(r) {
  showDetail('What the router is carrying', [], null, true);
  var host = $('attnbody');
  var lead = el('p', 'lead');
  lead.innerHTML = 'Read from the list <code>' + esc(r.list) + '</code> just now, in '
    + r.read_in_ms + ' ms \u2014 both the IPv4 and the IPv6 side. '
