    if (!mine.length) {
      host.appendChild(el('p', 'lead', 'None written yet. Settings \u2192 Alerts \u2192 Messages: a name, '
        + 'the words, and which roads they take \u2014 then a rule, a schedule or a link can send it.'));
    } else {
      var own = el('div', 'alertsheet');
