}
$('notify-sheet').onclick = notifySheet;
$('notify-save').onclick = function () {
  var body = {devices: {}, systems: {}};
  Array.prototype.forEach.call($('notify-systems').querySelectorAll('.notify-sys'), function (row) {
    var own = row.querySelector('.swrow input');       // the first switch is "its own roads"
    if (!own) return;
    if (!own.checked) {
      // left alone it follows the house - which for a kind that starts quiet
      // has to be said, or it would go back to quiet
      if (row.dataset.dflt === 'off') body.systems[row.dataset.system] = {follow: true};
      return;
    }
    var roads = Array.prototype.filter.call(row.querySelectorAll('input[data-road]'), function (b) { return b.checked; })
      .map(function (b) { return b.dataset.road; });
    body.systems[row.dataset.system] = roads.length ? {roads: roads.join(',')} : {off: true};
  });
  Array.prototype.forEach.call($('notify-opts').querySelectorAll('input'), function (b) { body[b.dataset.k] = b.checked; });
  body.channels = {};
  Array.prototype.forEach.call($('notify-roads').querySelectorAll('input'), function (b) {
    body.channels[b.dataset.road] = b.checked;
  });
  Array.prototype.forEach.call($('notify-devices').querySelectorAll('select[data-device]'), function (sel) {
    if (!sel.value) return;
    var roadPick = sel.parentNode.querySelector('select[data-roads]');
    var roads = roadPick && roadPick.value ? '@' + roadPick.value : '';
    if (sel.value === 'custom') {
      var cats = Array.prototype.filter.call(sel.parentNode.querySelectorAll('.notify-custom input'), function (b) { return b.checked; })
        .map(function (b) { return b.dataset.cat; });
      if (cats.length) body.devices[sel.dataset.device] = 'custom:' + cats.join(',') + roads;
    } else body.devices[sel.dataset.device] = sel.value + roads;
  });
  withPin('Save notification choices', 'What is worth a push message.', function (pin) {
    body.pin = pin;
    return post('notify-save', body).then(function () { NOTIFY.dirty = false; forgetSig('notify'); return 'Notification choices saved'; });
  });
};
// One road, or all of them. Sending down all of them at once tells you that
// something arrived; it does not tell you which one is the one that did not,
// which is the question somebody setting up a second channel actually has.
function testNotify(road) {
  var name = road ? (road === 'ntfy' ? 'ntfy' : 'Telegram') : 'every configured channel';
  withPin('Send a test message',
    road ? ('One message, down ' + name + ' alone - so a road that does not work says so by itself.')
         : 'One message through every configured channel.',
    function (pin) {
      return post('notify-test', road ? {pin: pin, road: road} : {pin: pin}).then(function (r) {
        return 'Sent through ' + (r.channels || []).join(' and ');
      });
    });
}
// One address, and everything this house knows about it: which list knows it,
// which country it is in, whether it is kept out and why, and what it has
// actually asked for - which is the question somebody has when they see an
// address they do not recognise.
function drawLook(found) {
  var host = $('look-out');
  host.innerHTML = '';
  if (!found) return;
  var card = el('div', 'proof');
  var head = el('div', 'ph');
  head.textContent = found.ip + '  ' + (found.country ? (flagOf(found.country) + ' ' + found.country) : '')
    + (found.feed ? '  \ud83d\udcd5 on the ' + found.feed + ' list' : '')
    + (found.house ? '  \u00b7 one of the house\u2019s own' : '')
    + (found.spared ? '  \u00b7 never kept out' : '');
  card.appendChild(head);
  var say = function (words) {
    var line = el('div', 'pl');
    line.textContent = words;
    card.appendChild(line);
  };
  if (!found.known) say('nothing is known about it: it has never been seen here.');
  if (found.blocked) {
    say((found.forever ? 'kept out for good' : 'kept out until ' + stamp(found.until))
        + (found.folded_into ? ', by the subnet ' + found.folded_into : '') + '.');
  }
  // folded into that subnet: what it was kept out for in the first place
  if (found.folded) {
    say('🧩 folded into it' + (found.folded.folded_at ? ' ' + stamp(found.folded.folded_at) : '')
        + '; before that it was kept out on its own since ' + stamp(found.folded.since) + ' for: '
        + (found.folded.why || 'no reason written down'));
  }
  if (found.before) {
    say('kept out ' + found.before + ' time(s) in all, ' + found.lately + ' of them lately.');
  }
  if (found.lines) {
    say(found.lines + ' line(s) in the logs, ' + found.spread + ' different path(s), first '
        + stamp(found.first) + ', last ' + stamp(found.last) + '.');
  }
  if (found.score) say('on its account now: ' + found.score + ' of ' + found.bar + '.');
  var idsHere = idsWords(found.ids);
  if (idsHere) {
    idsHere.style.margin = '4px 0 2px';
    card.appendChild(idsHere);
  }
  (found.asked || []).forEach(function (a) {
    say('   ' + a.n + '\u00d7 ' + (a.path || '') + '   \u2014 answered ' + a.status);
  });
  var intel = found.intel || {};
  if (intel.shodan) {
    var sh = intel.shodan;
    say('Shodan: ' + (sh.skipped || (sh.error ? '\u26a0 ' + sh.error : (sh.nothing ? 'nothing on this address' : sh.words || ''))));
  }
  if (intel.talos) say('Cisco Talos: ' + (intel.talos.list_on ? (intel.talos.listed ? 'on its IP block list' : 'not on its IP block list') : 'its block list is not switched on'));
  var ib = intelButtons(found.ip);
  if (ib) card.appendChild(ib);
  host.appendChild(card);
}
$('look-go').onclick = function () {
  var ip = ($('look-ip').value || '').trim();
  if (!ip) return;
  withPin('Ask about ' + ip, 'Nothing is changed; this only says what is already known.',
    function (pin) {
      return post('address-look', {pin: pin, ip: ip}).then(function (r) {
        drawLook(r.found);
