  HOLD.timer = setTimeout(releaseHold, 120);
});

function applyStatus(st) {
  if (userHolding()) {
    // keep the data, keep the long poll, draw nothing
    STATE.status = st;
    HOLD.waiting = true;
    waitLoop();
    // said plainly, because a page that has stopped drawing for a reason
    // nobody can see is indistinguishable from one that has stopped working
    $('updated-label').textContent = HOLD.select ? 'Held \u2014 a list is open' : 'Held \u2014 text selected';
    return;
  }
  var tPaint = performance.now();
  if (sigChanged('alertband', [st.alerts, Math.floor(Date.now() / 30000)])) renderAlertBand(st);
  if (st.server_now) CHG.skew = st.server_now - Date.now() / 1000;
  if (sigChanged('changes', [st.changes, isAdmin()])) renderChanges(st);
  applyRuntimeFlags(st);                     // before any card is built this tick
  STATE.status = st;
  var pill = $('pill');
  setIf(pill, 'className', 'pill ' + st.level);
  setIf($('pill-text'), 'textContent', levelWord(st.level) + (st.connected ? '' : ' — broker unreachable'));
  if (setFavicon.last !== st.level) setFavicon(st.level);
  waitLoop();
  renderLock();
  setIf(document, 'title', (st.level === 'ok' ? '' : (st.level === 'crit' ? '⚠ ' : '● ')) + 'Sensors — ' + st.counts.devices + ' devices');
  renderOverview(st);                        // the metric cards - cheap, always
  // Every tab there is. Heating and Events were left out of this list, so
  // leaving Heating and coming back drew nothing: the rooms sat at whatever
  // they read when you left until the next tick - and with the page paused,
  // for ever.
  ['overview', 'plugs', 'sensors', 'buttons', 'heating', 'history', 'devices', 'events', 'sms',
   'wifi', 'all', 'control', 'approvals'].forEach(function (t) { TAB_STALE[t] = true; });
  renderTab(STATE.tab, st);
