    explainWhatWasDrawn.soon = null;
    var batch = EXPLAIN_FRESH;
    EXPLAIN_FRESH = [];
    try {
      if (!batch.length) { explainLongTitles(); return; }
      batch = foldBatch(batch);
      for (var i = 0; i < batch.length; i++) {
        if (batch[i].isConnected === false) continue;
        explainLongTitles(batch[i]);
