// half a second of a phone's first load, and the first drawing of the visible
// tab done twice. Everything below it still had to happen, though - the
// overview's charts and the events table are not in the status - and leaving
// it out was how they came up empty.
function afterStatus(force) {
  if (userHolding()) return;             // the lists below replace themselves whole, exactly as the cards do
  $('updated-label').textContent = STATE.paused ? 'Paused' : 'Live';
  if (STATE.tab === 'overview') {
    if (!STATE._ovLoaded || (Date.now() - STATE._ovLoaded) > 60000) { loadOverviewCharts(); STATE._ovLoaded = Date.now(); }
    else if (force) scheduleOverviewCharts();     // a live update: the cards are already fresh; the charts follow shortly
  }

  // every change anywhere is a forced tick; five hundred events fetched and
  // the table redrawn for each of them kept the rows sliding under the
  // reader. At most every three seconds, and the last change is never lost.
  if (STATE.tab === 'events' && force) {
    var gap = Date.now() - (EVENTS.at || 0);
