  ['up-plan', 'up-log', 'up-pkg', 'up-ready', 'full-says'].forEach(function (id) { if ($(id)) $(id).textContent = ''; });
  if ($('up-plan-card')) $('up-plan-card').hidden = true;
  host.appendChild(el('p', 'note reason', words));
  var b = cmdButton(LOCK.who ? 'Sign in as an administrator' : 'Sign in', 'person', 'small primary');
  b.classList.remove('needs-unlock');
