/* ---- the popup, as otp has it ------------------------------------------------ */
var ZM = {gen: 0, from: null, onClose: null};
function zmodalEl() {
  var m = $('zmodal');
  if (m) return m;
  var w = el('div');
  w.innerHTML = '<div class="modal" id="zmodal" hidden><div class="box ot" id="zmodal-box" role="dialog" aria-modal="true">'
    + '<div class="head"><h3 id="zmodal-title"></h3><button class="xbtn" id="zmodal-x" type="button" aria-label="Close">×</button></div>'
    + '<div class="body" id="zmodal-body"></div><div class="foot" id="zmodal-foot"></div></div></div>';
  document.body.appendChild(w.firstChild);
  $('zmodal-x').onclick = closeZModal;
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && $('zmodal') && !$('zmodal').hidden) closeZModal();
  });
