}
function zmodal(title, build, buttons, size) {
  var m = zmodalEl();
  ZM.gen += 1;
  ZM.onClose = null;
  $('zmodal-title').textContent = title;
  $('zmodal-box').className = 'box ot' + (size ? ' ' + size : '');
  var body = $('zmodal-body');
  body.innerHTML = '';
  if (typeof build === 'function') build(body); else if (build) body.appendChild(build);
  var foot = $('zmodal-foot');
  foot.innerHTML = '';
  (buttons || [{words: 'Close', close: true}]).forEach(function (b) {
    if (b.spacer) { foot.appendChild(el('span', 'left')); return; }
    var button = el('button', 'btn cmd' + (b.cls ? ' ' + b.cls : ''));
    button.type = 'button';
    setButtonIcon(button, b.icon || (b.close && !b.go ? 'close' : 'check'), b.words);
    var run = function () {
      var was = ZM.gen;
      if (b.go) b.go(button);
      if (b.close && ZM.gen === was) closeZModal();
    };
    button.onclick = run;
    /* Anything that destroys is asked twice: the first click turns the
       buttons into "Really?", the second does it. */
    if (/\bdanger\b/.test(b.cls || '') && b.go && !b.once) {
      button.onclick = function () {
        var strip = el('div', 'sure-strip');
        strip.appendChild(el('span', 'sure-q', 'Really? This cannot be taken back.'));
        var no = el('button', 'btn cmd'); no.type = 'button';
        setButtonIcon(no, 'close', 'No, leave it');
        var yes = el('button', 'btn cmd danger'); yes.type = 'button';
        setButtonIcon(yes, b.icon || 'check', b.words);
        strip.appendChild(no); strip.appendChild(yes);
        // the buttons it stands in for are taken out of sight - by style as
        // well as `hidden`, which a .btn's own display would otherwise beat
        var kept = Array.prototype.slice.call(foot.children);
        var show = function (on) { kept.forEach(function (c) { c.hidden = !on; c.style.display = on ? '' : 'none'; }); };
        show(false);
        foot.appendChild(strip);
        no.onclick = function () { strip.remove(); show(true); };
        yes.onclick = function () { strip.remove(); show(true); run(); };
        setTimeout(function () { try { no.focus(); } catch (e) {} }, 0);
      };
    }
    foot.appendChild(button);
  });
  if (m.hidden) ZM.from = document.activeElement;
  m.hidden = false;
  var first = body.querySelector('input:not([type=hidden]):not([disabled]), select:not([disabled]), textarea:not([disabled])')
    || foot.querySelector('.btn.primary:not(.danger)') || foot.querySelector('.btn:not(.danger)');
  if (first) setTimeout(function () { try { first.focus(); } catch (e) {} }, 0);
  return {body: body, foot: foot};
}
