    more.appendChild(el('summary', '', 'what is waiting (' + ck.packages.length + ')'));
    more.appendChild(el('pre', 'zlines', ck.packages.slice(0, 300).join('\n') + (ck.packages.length > 300 ? '\n…' : '')));
