    if (after) uc.appendChild(el('p', 'note warn', (d.node || 'This server') + ' needs a restart after this update: ' + (ck.reboot_why || []).join(', ') + '.'));
    var seg2 = el('div', 'seg');
    [['all', 'Every update'], ['security', 'Only the security updates']].forEach(function (o) {
