/* ==== Upgrades ======================================================================== */
var UP = {last: null, misses: 0, loaded: null, timer: null, tailOpen: false};
var UP_STEP = {'waiting for root': ['waiting for root', 'dim', 3], 'checking the package': ['checking the package', 'info', 8],
               backup: ['backing the whole installation up', 'info', 15], installing: ['being put in', 'info', 50],
               checking: ['asking the new version', 'info', 88], 'rolling back': ['putting the old one back', 'warn', 92]};
function upAgain(ms) {
  clearTimeout(UP.timer);
  UP.timer = setTimeout(function () {
    if (STATE.tab !== 'control' || CONTROL_SEC !== 'sys-upgrade') return;
    if (document.hidden) { upAgain(ms); return; }
    loadUpgrade(true);
  }, ms);
}
function loadUpgrade(quiet) {
  var host = $('up-nodes');
  if (!host) return;
  rootTimer('sys-upgrade', function () { if (!(UP.last && UP.last.running)) loadUpgrade(true); }, 8000);
  if (!isUnlocked()) {
    rootLocked(host, 'An administrator\u2019s to see. Putting a new version in is root\u2019s work, asked for by an administrator.', loadUpgrade);
    return;
  }
  rootUnlockedHost(host);
  var running = UP.last && UP.last.running;
  api('upgrade').then(function (d) {
    UP.misses = 0;
    if ($('up-retry')) $('up-retry').textContent = '';
    if (!UP.loaded) UP.loaded = d.version;
    drawUpgrade(d);
  }).catch(function (e) {
    /* the daemon being put in is restarting: asked again until it answers */
    if (running && UP.misses++ < 200) {
      if ($('up-retry')) $('up-retry').textContent = 'zigmon is restarting - asking again…';
      upAgain(2000);
      return;
    }
    if (!quiet) zoops(e);
  });
}
function upPercent(st) {
  if (st.state === 'done' || st.state === 'failed') return 100;
  var w = UP_STEP[st.step] || UP_STEP['waiting for root'];
  var pc = w[2];
  if (st.step === 'installing') {
    var parts = (st.tail || []).filter(function (l) { return /^==> /.test(l); }).length;
    pc = Math.min(82, 20 + parts * 6);
  }
  return pc;
}
function upBar(pc, kind, words, wide) {
  var box = el('div', 'going up-bar' + (wide ? ' wide' : '') + (kind ? ' ' + kind : ''));
  var bar = el('div', 'bar'), fill = el('span');
  fill.style.width = Math.max(0, Math.min(100, pc)) + '%';
  bar.appendChild(fill); box.appendChild(bar);
  if (words) box.appendChild(el('div', 'says', words));
  return box;
}
/* New versions from the web (5.21): what upgrade_url had when it was last
   asked, and one click to put the newest in. Every word that came from the
   address - a version, a link, an error a server sent back - is escaped: it
   is somebody else's text, written into this page. */
function drawUpWeb(d) {
  var host = $('up-web');
  if (!host) return;
  var w = d.web || {}, o = w.online || {};
  var here = esc(o.here || d.version || '?');
  host.innerHTML = '';
  var p = el('p', 'note' + (o.error ? ' bad' : (o.newer ? ' good' : '')));
  if (!o.at) p.innerHTML = w.check ? 'Not looked at yet &ndash; within minutes, or press Look now.'
    : 'Not looked at: looking every day is switched off below. Look now asks once.';
  else if (o.error) p.innerHTML = 'Looked ' + esc(ago(o.at)) + ': ' + esc(o.error);
  else if (o.newer) p.innerHTML = 'zigmon <b>' + esc(o.newest.version) + '</b> is there &ndash; this server runs '
    + here + ' (looked ' + esc(ago(o.at)) + ')';
  else if (o.newest) p.innerHTML = 'Nothing newer: the newest there is ' + esc(o.newest.version)
    + ' and this server runs ' + here + ' (looked ' + esc(ago(o.at)) + ')';
  else p.innerHTML = 'No zigmon package there (looked ' + esc(ago(o.at)) + ')';
  host.appendChild(p);
  var at = el('p', 'small muted');
  at.innerHTML = '<code>' + esc(w.url || o.url || '–') + '</code>';
  host.appendChild(at);
  var row = el('div', 'btnrow');
  var look = cmdButton('Look now', 'refresh', '');
  look.disabled = !!(d.running || w.busy);
  look.onclick = function () {
    zbusy(look, true);
    rootPost('upgrade-do', {action: 'online_look'}).then(function (x) { toast(x.message, true); drawUpgrade(x); }, zoops)
      .then(function () { zbusy(look, false); });
  };
  row.appendChild(look);
  if (o.newer && !d.running && !d.asked) {
    var v = String(o.newest.version), vurl = String(o.newest.url || w.url || '');
    var up = cmdButton('Upgrade to ' + v + ' now', 'play', 'primary');
    // more than one version newer than this one: which of them is chosen
    // here, the newest first; with one, nothing is asked and nothing changes
    var many = (o.newer_list || []).filter(function (x) { return x && x.version; });
    if (many.length > 1) {
      var pick = zSelect(many.map(function (x, i) {
        return [x.version, 'zigmon ' + x.version + (i === 0 ? ' (the newest)' : '')];
      }), v);
      pick.className = 'up-pick';
      pick.title = 'More than one newer version is there: the one to go to';
      pick.onchange = function () {
        v = pick.value;
        vurl = String((many.filter(function (x) { return x.version === v; })[0] || {}).url || w.url || '');
        setButtonIcon(up, 'play', 'Upgrade to ' + v + ' now');
