  if (!d.helper) rd.appendChild(el('p', 'note bad', 'This machine cannot put a version in by itself yet: zigmon-upgrade.path is not '
    + 'installed. Upgrade it once on the command line (sudo ./install.sh --upgrade), which puts it in.'));
