/* ==== The whole installation ============================================================ */
var FULL = {last: null, watching: null};
var FULL_PARTS = {database: 'The database', config: 'The configuration', web: 'nginx', tls: 'The certificate',
                  broker: 'The broker', firewall: 'The firewall', system: 'The units', zigbee: 'Zigbee2MQTT'};
function loadFull(quiet) {
  var host = $('full-list');
  if (!host) return;
  rootTimer('sys-backup', loadFull, 6000);
  if (!isUnlocked()) {
    rootLocked(host, 'An administrator\u2019s to see. A backup of the whole installation holds the certificate’s key and every password of the house.', loadFull);
    return;
  }
  rootUnlockedHost(host);
  api('fullbackup' + (quiet ? '' : '&fresh=1')).then(drawFull).catch(function (e) { if (!quiet) zoops(e); });
}
function drawFull(d) {
  FULL.last = d;
  var host = $('full-list');
  if (typingIn(host)) return;
  host.innerHTML = '';
  if (!d.helper) rootNotInstalled(host);
  var says = $('full-says');
  says.innerHTML = '';
  if (d.progress) says.appendChild(rootProgress(d.progress));
  else if (d.busy) {
    says.appendChild(rootStateLine({waiting: true}, ''));
    var stuck = rootStuck(d.busy);
    if (stuck) says.appendChild(stuck);
  }
  else if (d.status && d.status.state === 'failed') says.appendChild(el('p', 'note bad', (d.status.said || []).join('; ')));
  var list = d.list || [], newest = list[0];
  var ff = otFacts([['Newest', newest ? ago(newest.ts) : 'none yet'], ['Its size', newest ? sizeText(newest.bytes) : ''],
    ['Kept here', String(list.length)], ['Where', d.dir || '', 'mono']]);
  ff.classList.add('full-facts');
  host.appendChild(ff);
  host.appendChild(zTable(['Backup', 'Made', 'Size', '', ''], list, function (b) {
    var tr = el('tr');
    var nm = el('td', 'mono', b.file);
    tr.appendChild(nm);
    tr.appendChild(el('td', 'muted', stamp(b.ts)));
    tr.appendChild(el('td', 'num', sizeText(b.bytes)));
    var why = el('td');
    if (b.why) why.appendChild(el('span', 'tag ' + (b.why === 'uploaded' ? 'info' : 'dim'), b.why));
    tr.appendChild(why);
    var acts = el('td', 'acts');
    var dl = iconButton('download', 'Download - with a password if you give one');
    dl.onclick = function () { fullDownload(b.file); };
    var rs = iconButton('undo', 'Put back - all of it, or the parts you choose');
    rs.onclick = function () { fullRestore(b.file); };
    var rm = iconButton('trash', 'Delete');
    rm.onclick = function () {
      zconfirm('Delete ' + b.file, 'The backup is removed from ' + (d.dir || 'the server') + '.', 'Delete', function () {
        FULL.last = Object.assign({}, FULL.last || d, {busy: {since: 0}});
        drawFull(FULL.last);                  // the buttons off at once, not at the next look
        rootPost('fullbackup-do', {action: 'delete', file: b.file}).then(function (x) {
          return rootWait('fullbackup', x.asked).then(function () { toast('deleted', true); loadFull(); });
        }).catch(function (e) { zoops(e); loadFull(); });
      });
    };
    // one request to root at a time: while it works on one, the others wait
    // here rather than being pressed into "root is still busy"
    if (d.busy) [rs, rm].forEach(function (x) { x.disabled = true; x.title = 'Root is busy with what was asked a moment ago'; });
    [dl, rs, rm].forEach(function (x) { acts.appendChild(x); });
    tr.appendChild(acts);
    return tr;
  }, 'plain|None yet - make one now, or let the nightly backup make one'));
}
function fullDownload(file) {
  var f = {};
  zmodal('Download ' + file, function (body) {
    body.appendChild(el('p', 'note', 'It holds the certificate’s private key and every password of the house. With a password '
      + 'it is locked (AES-256) before it leaves this machine; it is then put back with the same password.'));
    f.pw = zSecret('eight characters or more - recommended');
    body.appendChild(zField('Password for the copy', f.pw, 'Not kept anywhere: without it the copy cannot be opened.'));
  }, [{words: 'Cancel', close: true},
      {words: 'Download', cls: 'primary', icon: 'download', go: function (b) {
        zbusy(b, true);
        rootPost('fullbackup-do', {action: 'get', file: file, passphrase: f.pw.value || ''}).then(function (x) {
          closeZModal();
          toast('root is handing it over…', true);
          return rootWait('fullbackup', x.asked).then(function (d) {
            if (!d.ready) throw new Error(((d.status || {}).said || ['it was not handed over']).join('; '));
            downloadBehindPin('fullbackup-download&file=' + encodeURIComponent(d.ready.file), d.ready.file);
            loadFull(true);
          });
        }).catch(zoops).then(function () { zbusy(b, false); });
      }}], 'narrow');
}
function fullRestore(file) {
  rootPost('fullbackup-do', {action: 'inspect', file: file}).then(function (x) {
    toast('root is looking into it…', true);
    return rootWait('fullbackup', x.asked);
  }).then(function (d) {
    var st = d.status || {};
    if (st.state !== 'done' || !st.inspected) throw new Error((st.said || ['it could not be read']).join('; '));
    fullRestoreAsk(st.inspected);
  }).catch(zoops);
}
function fullRestoreAsk(info) {
  var chosen = {};
  zmodal('Put back from ' + info.file, function (body) {
    body.appendChild(el('p', 'note', 'Made on ' + (info.host || '?') + ' by zigmon ' + (info.version || '?') + ', '
      + stamp(info.made_at) + (info.why ? ' (' + info.why + ')' : '') + '. A backup of how it is now is made first, so this can be undone.'));
    if (!info.trusted) body.appendChild(el('p', 'note warn', 'This backup was not made by this machine. Its database, configuration, '
      + 'certificate and Zigbee backup can be put back from here; the rest only by root on the command line: '
      + 'sudo zigmon --full-restore FILE --parts web,broker,firewall,system - because putting nginx, a unit or the broker back from '
      + 'an uploaded file would be root for any administrator of the page.'));
    var rows = el('div', 'tls-rows');
    (info.parts || []).forEach(function (p) {
      var may = (info.from_page || []).indexOf(p.part) >= 0;
      var sw = zSwitch(may && p.part !== 'firewall' && p.part !== 'system');
      sw._input.disabled = !may;
      chosen[p.part] = sw;
      var row = zRow((FULL_PARTS[p.part] || p.part) + ' · ' + p.files + ' file(s), ' + sizeText(p.bytes),
                     p.words + (p.paths && p.paths.length ? ' - ' + p.paths.slice(0, 4).join(', ') : ''), sw);
      if (!may) row.classList.add('dim');
      rows.appendChild(row);
    });
    body.appendChild(rows);
    body.appendChild(el('p', 'note', 'Putting back the database or the configuration stops zigmon for the moment it takes; these pages '
      + 'come back by themselves.'));
  }, [{words: 'Cancel', close: true},
      {words: 'Put it back', cls: 'danger', icon: 'undo', go: function (b) {
        var parts = Object.keys(chosen).filter(function (k) { return chosen[k]._get() && !chosen[k]._input.disabled; });
        if (!parts.length) { toast('choose what to put back', false); return; }
        zbusy(b, true);
        rootPost('fullbackup-do', {action: 'restore', file: info.file, parts: parts}).then(function (x) {
          closeZModal();
          toast('root is putting it back…', true);
          return rootWait('fullbackup', x.asked, null, function (d) {
            if (!d && $('full-says')) $('full-says').textContent = 'zigmon is restarting - asking again…';
          }).then(function (d) {
            var st = d.status || {};
            if (st.state === 'failed') throw new Error((st.said || []).join('; '));
            zmodal('Put back', function (body2) {
              var ul = el('ul');
              (st.said || []).forEach(function (s) { ul.appendChild(el('li', '', s)); });
              body2.appendChild(ul);
            }, null, 'narrow');
            loadFull();
            tick(true);
          });
        }).catch(zoops).then(function () { zbusy(b, false); });
      }}], 'medium');
}
function fullWire() {
  var slot = $('full-drop-slot');
  if (!slot || slot.dataset.wired) return;
  slot.dataset.wired = '1';
  var words = 'Drop a backup of the whole installation here (zigmon-full-….tar.gz or .enc), or press to choose one';
  var drop = dropZone(words, '.gz,.enc,application/gzip,application/octet-stream', function (files) {
    var file = files[0];
    var f = {};
    zmodal('Send ' + file.name, function (body) {
      body.appendChild(el('p', 'note', sizeText(file.size) + ', sent in pieces. Root looks into it before it joins the list; '
        + 'nothing is put back until you choose what.'));
