      body.appendChild(zField('Its password', f.pw));
    }, [{words: 'Cancel', close: true},
        {words: 'Send it', cls: 'primary', icon: 'upload', go: function (b) {
          zbusy(b, true);
          closeZModal();
          sendInPieces('fullbackup-upload', file, {passphrase: f.pw.value || ''}, function (pc) {
            drop._says.textContent = 'sending ' + file.name + '… ' + pc + ' %';
          }).then(function (x) {
            drop._says.textContent = 'root is looking into it…';
            return rootWait('fullbackup', x.asked);
          }).then(function (d) {
            drop._says.textContent = words;
            var st = d.status || {};
            if (st.state === 'failed') throw new Error((st.said || []).join('; '));
            toast('taken in: ' + ((st.inspected || {}).file || ''), true);
