            ipv4: {method: f.method, addr: f.addr.value.trim(), gw: f.gw.value.trim(), dns: list(f.dns), search: list(f.search)},
            ipv6: {on: !!f.on6._get(), mode: f.mode6.value, addr: f.addr6.value.trim(), gw: f.gw6.value.trim(), dns: list(f.dns6)}};
