  fact('Next', d.next ? d.next.replace('T', ' ') : 'by hand only', d.next ? '' : 'warn');
  fact('Locked', d.locked ? 'with the password (AES-256)' : 'NOT locked - set the password: nothing is sent without it', d.locked ? 'good' : 'bad');
