    if (e.target.closest && e.target.closest('button[data-sec]')) { shut(0); return; }
    if (e.target.closest && e.target.closest('input, .ctl-found, .ctl-pin')) return;
    if (nav.classList.contains('open')) shut(0);
    else { clearTimeout(CTLNAV.shutT); nav.classList.add('open'); }
  });
  nav.addEventListener('focusin', function () { if (!byFinger()) open(); });
  nav.addEventListener('focusout', function () { if (!nav.contains(document.activeElement)) shut(120); });
  window.addEventListener('scroll', queueCtlNav, {passive: true});
  // a picker or a list of suggestions is hung on the page, not in the frame:
  // when the frame scrolls it would be left floating over the wrong box
  document.addEventListener('scroll', function (e) {
    var t = e.target;
    if (!t || !t.classList || !(t.classList.contains('panel') || t.classList.contains('ctl-main'))) return;
    if (typeof closePicker === 'function') closePicker();
    if (typeof closeCompleter === 'function') closeCompleter();
    Array.prototype.forEach.call(document.querySelectorAll('.pickbox.whopick'), function (x) { x.remove(); });
  }, true);
  window.addEventListener('resize', function () {
    queueCtlNav();
    document.documentElement.classList.toggle('app-shell-root',
      window.innerWidth > 980 && document.body.classList.contains('app-shell'));
  });
  pinCtlNav(CTLNAV.pinned);
})();
// Every Save on a settings card saves every setting, wherever it is drawn -
// the same one Save it always was.
Array.prototype.forEach.call(document.querySelectorAll('.set-save-alt'), function (b) {
  setButtonIcon(b, 'save');
  b.onclick = function () { $('settings-save').onclick(); };
});
// A card says in a line what it is for; the whole of it is one press away.
// Only notes that nothing writes into are folded - one with an id is live.
function firstSentence(text) {
  text = String(text || '').replace(/\s+/g, ' ').trim();
  var m = /^(.{25,170}?[.!?])(\s|$)/.exec(text);
  if (m) return m[1];
  if (text.length <= 170) return text;
  // no sentence ends soon enough: stop at the last clause that does
  var head = text.slice(0, 170);
  var cut = Math.max(head.lastIndexOf(' \u2014 '), head.lastIndexOf('; '), head.lastIndexOf(': '));
  if (cut > 40) return head.slice(0, cut).replace(/[ ,;:]+$/, '') + '.';
  return head.replace(/[ ,;:]+\S*$/, '') + '\u2026';
}
// notes that the page writes into as it goes: left as they are
var LIVE_NOTES = {'notify-note': 1, 'wifi-api-note': 1, 'wifi-seen-note': 1};
function decorateControlCards(root) {
  Array.prototype.forEach.call((root || document).querySelectorAll('section.panel .card, #lock-card'), function (card) {
    var h = card.querySelector(':scope > h2');
    if (!h || h.dataset.decorated) return;
    h.dataset.decorated = '1';
    var notes = Array.prototype.filter.call(card.querySelectorAll(':scope > p.note'), function (n) {
      return !(LIVE_NOTES || {})[n.id] && !n.querySelector('[id]') && (n.textContent || '').trim();
    });
    if (!notes.length) return;
    var full = notes.map(function (n) { return n.innerHTML; });
    var lede = el('p', 'card-lede', firstSentence(notes[0].textContent));
    notes[0].parentNode.insertBefore(lede, notes[0]);
    notes.forEach(function (n) { n.classList.add('note-folded'); });
    var b = el('button', 'btn small card-info');
    b.type = 'button';
    setButtonIcon(b, 'info', 'About');
    b.onclick = function () {
      showDetail(h.childNodes[0] ? h.childNodes[0].textContent : h.textContent, [], null, true);
      var host = $('attnbody');
      full.forEach(function (html) {
        var p = el('p', 'sinfo-lead');
        p.innerHTML = html;
        host.appendChild(p);
      });
      var row = el('div', 'btnrow');
      var close = foldButton('Close', 'close', 'primary');
      close.onclick = function () { $('attnback').hidden = true; };
      row.appendChild(close);
      host.appendChild(row);
    };
    h.appendChild(b);
  });
}
decorateControlCards();
// Finding anything from the header: a tab, a card on any tab, a Control
// section, card or setting, or a device - and going there.
var TAB_NAMES = {overview: 'Overview', plugs: 'Plugs', sensors: 'Sensors', buttons: 'Buttons', heating: 'Heating',
                 history: 'History', devices: 'Devices', sms: 'SMS', wifi: 'WiFi', events: 'Events',
                 approvals: 'Public API', control: 'Settings', all: 'All values'};
(function () {
  var box = $('app-find'), list = $('app-found');
  if (!box || !list) return;
  var shut = function () { list.hidden = true; list.innerHTML = ''; box._index = null; };
  var go = function (it) { shut(); box.value = ''; box.blur(); it.go(); };
  box.oninput = function () {
    var words = box.value.toLowerCase().split(/\s+/).filter(function (w) { return w; });
    list.innerHTML = '';
    if (!words.length) { shut(); return; }
    // the index is built once per search, when typing starts, and kept for
    // the letters that follow: built for every letter, it walked every card
    // and every rule's target list each time
    if (!box._index || Date.now() - box._indexAt > 20000) { box._index = searchIndex(); box._indexAt = Date.now(); }
    var hits = searchMatch(box._index, box.value).slice(0, 14);
    if (!hits.length) list.appendChild(el('div', 'ctl-none', 'Nothing called that'));
    hits.forEach(function (it, i) {
      var b = el('button', 'ctl-hit' + (i === 0 ? ' sel' : ''));
      b.type = 'button';
      b.appendChild(el('span', 'ctl-hit-t', it.text));
      b.appendChild(el('span', 'ctl-hit-w', it.what + (it.where ? ' \u00b7 ' + it.where : '')));
      b.onclick = function () { go(it); };
      list.appendChild(b);
    });
    list.hidden = false;
  };
  box.onkeydown = function (e) {
    var items = Array.prototype.slice.call(list.querySelectorAll('.ctl-hit'));
    var at = items.findIndex(function (x) { return x.classList.contains('sel'); });
    if (e.key === 'Escape') { box.value = ''; shut(); box.blur(); }
    else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!items.length) return;
      if (at >= 0) items[at].classList.remove('sel');
      at = (at + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
      items[at].classList.add('sel');
      if (items[at].scrollIntoView) items[at].scrollIntoView({block: 'nearest'});
    } else if (e.key === 'Enter' && items.length) {
      (items[at >= 0 ? at : 0]).click();
    }
  };
  document.addEventListener('click', function (e) {
    if (!list.hidden && e.target !== box && !list.contains(e.target)) shut();
  });
  // "/" from anywhere that is not a box being typed in
  document.addEventListener('keydown', function (e) {
    if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey) return;
    var a = document.activeElement, tag = a && (a.tagName || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || tag === 'select' || (a && a.isContentEditable)) return;
    e.preventDefault(); box.focus();
  });
})();
// Finding a setting or a card by what it is called, across every section
function controlIndex() {
  var out = [];
  Object.keys(CONTROL_SECTIONS).forEach(function (sec) {
    out.push({sec: sec, what: 'section', text: CONTROL_SECTIONS[sec][0], more: CONTROL_SECTIONS[sec][1]});
  });
  Array.prototype.forEach.call(document.querySelectorAll('#tab-control .grid.charts > .card'), function (card) {
    var h = card.querySelector(':scope > h2');
    if (!h || card.classList.contains('set-card') || !card.dataset.sec) return;
    out.push({sec: card.dataset.sec, what: 'card', text: (h.childNodes[0] || h).textContent.trim(), node: card,
              more: (card.querySelector('.card-lede') || {}).textContent || ''});
  });
  SETTINGS_LAYOUT.forEach(function (group) {
    var sec = SETTINGS_WHERE[group[0]] || 'sys-all';
    group[1].forEach(function (pair) {
      if (pair[0] === '|') return;
      out.push({sec: sec, what: 'setting', key: pair[0], text: pair[2] ? pair[1] : splitSettingWords(pair[1])[0],
                more: group[0] + ' \u00b7 ' + pair[0] + ' ' + (pair[2] || pair[1])});
    });
  });
  return out;
}
(function () {
  var box = $('ctl-find'), list = $('ctl-found');
  if (!box || !list) return;
  var shut = function () { list.hidden = true; list.innerHTML = ''; };
  box.oninput = function () {
    var words = box.value.toLowerCase().split(/\s+/).filter(function (w) { return w; });
    list.innerHTML = '';
    if (!words.length) { shut(); return; }
    var hits = controlIndex().filter(function (it) {
      var hay = (it.text + ' ' + it.more + ' ' + (it.key || '')).toLowerCase();
      return words.every(function (w) { return hay.indexOf(w) >= 0; });
    }).slice(0, 12);
    if (!hits.length) list.appendChild(el('div', 'ctl-none', 'Nothing called that'));
    hits.forEach(function (it) {
      var b = el('button', 'ctl-hit');
      b.type = 'button';
      b.appendChild(el('span', 'ctl-hit-t', it.text));
      b.appendChild(el('span', 'ctl-hit-w', (CONTROL_SECTIONS[it.sec] || [''])[0] + ' \u00b7 ' + it.what));
      b.onclick = function () {
        shut(); box.value = '';
        showControlSection(it.sec);
        setTimeout(function () {
          if (it.what === 'setting') {
            var k = settingsQuery('[data-k="' + it.key + '"]');
            flashThere(k && k.closest ? k.closest('.set-item') : null);
          } else if (it.node) {
            flashThere(it.node);
          }
        }, 120);
      };
      list.appendChild(b);
    });
    list.hidden = false;
  };
  box.onkeydown = function (e) {
    if (e.key === 'Escape') { box.value = ''; shut(); }
    if (e.key === 'Enter') { var first = list.querySelector('.ctl-hit'); if (first) first.click(); }
  };
  document.addEventListener('click', function (e) {
    if (!list.hidden && e.target !== box && !list.contains(e.target)) shut();
  });
})();
$('updated').onclick = function () {
  STATE.paused = !STATE.paused;
  $('updated').classList.toggle('paused', STATE.paused);
  $('updated-label').textContent = STATE.paused ? 'Paused' : 'Live';
  if (!STATE.paused) tick(true);
};
document.addEventListener('visibilitychange', function () { if (!document.hidden) tick(true); });
function pickOverviewRange(r) {
  if (STATE.ovRange !== r) { delete CHART_STATE['ov-temp']; delete CHART_STATE['ov-hum']; }   // a new span, not the old zoom
  STATE.ovRange = r; rangeButtons($('ov-ranges'), ['6h', '24h', '7d'], r, pickOverviewRange); loadOverviewCharts();
}
rangeButtons($('ov-ranges'), ['6h', '24h', '7d'], STATE.ovRange, pickOverviewRange);

if (INITIAL) applyStatus(INITIAL);
var wanted = (location.hash || '#overview').substring(1);
var wantedSec = wanted.split('/')[1] || '';
wanted = wanted.split('/')[0];
if (wantedSec && (CONTROL_SECTIONS[wantedSec] || CONTROL_ALIAS[wantedSec])) CONTROL_SEC = controlSecOf(wantedSec);
showControlSection(CONTROL_SEC);
showTab(['overview', 'plugs', 'sensors', 'buttons', 'heating', 'history', 'devices', 'wifi', 'events', 'approvals', 'control', 'all'].indexOf(wanted) >= 0 ? wanted : 'overview');
// Asked for once at the start: what it brings - the verbs the script box
// offers, and the names a command or a link may point at - is wanted by
// editors drawn before anything else would think to ask.
loadScripts();
// The status is already here, inlined in the page the server built, and
// applyStatus above has drawn it. Fetching it again at once was a third of a
// megabyte over the wire and the first drawing of the visible tab done twice,
// for data the page was holding - half a second of a phone's first load. The
// long poll beside the clock below hears about anything that changes from
// here on, so nothing is missed; without an INITIAL there is nothing drawn
// yet and the first fetch still happens at once.
if (INITIAL) {
  // ...and everything that first tick did BESIDES fetching: the overview's
  // charts, the events table, the health card, the Live label. None of it is
  // in the status, and leaving it out was how the overview and the events
  // tab came up empty on a first load.
  setTimeout(markHeaderIndent, 50);
  afterStatus(true);
} else {
  tick(true);
}
// The long poll is what keeps this page live: the daemon answers it the
// moment anything changes. This interval is the net underneath it, and with a
// healthy poll it was fetching the whole quarter-megabyte status every five
// seconds for nothing - about 2,880 fetches and a couple of gigabytes of JSON
// over an evening, per open tab, which on a phone is radio and battery. It
// now only fetches when the poll is failing or has said nothing for a minute;
// the daemon answers a wait every 30 s even when nothing has happened, so a
// minute of silence means the poll is not getting through.
STATE.timer = setInterval(function () {
  if (WAIT.failures > 0 || Date.now() - (WAIT.answered || 0) > 60000) tick(false);
}, REFRESH_MS);
// Anything drawn with more than a label's worth of title gets the panel
// rather than the browser's tooltip. Run after each drawing, since most of
// the page is drawn again as things change; each element is taken once.
// Whatever is drawn, whenever it is drawn - a tab, a card, a dialogue - is
// swept once a moment after it appears. Hooking the drawing passes caught most
// of it and missed everything opened in a dialogue, which is exactly where the
// longest explanations are.
explainLongTitles();
// ...and again now and then. The observer catches what changes while it is
// watching; a title set in the same breath as a redraw, before the sweep runs,
// slipped past it - six of them did. Cheap: only elements that still carry a
// title are touched, and on a settled page there are none.
setInterval(function () {
  // an empty title says nothing and needs no panel, so it is not a reason to
  // walk the whole page - it was the reason the sweep never rested
  if (document.querySelector('[title]:not([title=""])')) explainLongTitles(document);
}, 4000);
if (window.MutationObserver) {
  // Only what was just added, rather than the whole page each time: the page
  // redraws every second, and walking four hundred elements to find the three
  // that are new costs more than the drawing did. Anything the help panel
  // itself does is ignored, or showing it would ask for another sweep.
  new MutationObserver(function (records) {
    var fresh = [];
    for (var i = 0; i < records.length; i++) {
      var target = records[i].target;
      if (target && target.closest && target.closest('.sethelp')) continue;
      // a title put on an element that was already there - most of the page
      // is drawn again every second and sets its titles then, so watching
      // only what is added left nine of them showing the browser's own box
      if (records[i].type === 'attributes' && target && target.nodeType === 1) {
        fresh.push(target);
      }
      var added = records[i].addedNodes || [];
      for (var j = 0; j < added.length; j++) {
        if (added[j].nodeType === 1) fresh.push(added[j]);
      }
    }
    if (!fresh.length) return;
    EXPLAIN_FRESH = (EXPLAIN_FRESH || []).concat(fresh);
    explainWhatWasDrawn();
  }).observe(document.body, {childList: true, subtree: true,
                             attributes: true, attributeFilter: ['title']});
}
</script>
</body>
</html>
